/**
 * Year 2 — Functions and Graphs § 2.4 Inverse Functions
 * Ref: y2fg4
 * 71 questions in UK A-Level exam style: each states the function with its
 * domain, asks for f^{-1} with its domain and range, and many are multi-part
 * with numeric evaluations f^{-1}(k). Covers linear, quadratic (restricted
 * domain), rational, exponential/log/sqrt inverses, self-inverses, domain and
 * range of f^{-1}, f(f^{-1}(x)) = x verifications and graph-based problems.
 */
export const questions: Question[] = [
  { id: "y2fg4-001", topicRef: "y2fg4", topicTitle: "Inverse Functions 01", difficulty: "Standard", answerType: "expression", questionText: "The function \\( h \\) is defined by \\( h(x) = 2x^2 - 7, \\; x \\in \\mathbb{R}, \\; x \\ge 0 \\).  (a) Find \\( h^{-1}(x) \\), stating its domain and range.  (b) Evaluate \\( h^{-1}(43) \\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["inverse", "quadratic", "domain", "range", "evaluate"], workedSolution: { steps: [ { stepNumber: 1, description: "Set the output equal to \\(y\\).", workingLatex: "y = 2x^2 - 7", explanation: "Writing \\(y = h(x)\\) gives an equation we can rearrange to make \\(x\\) the subject; that rearranged form is the inverse." }, { stepNumber: 2, description: "Add 7 to both sides.", workingLatex: "y + 7 = 2x^2", explanation: "We undo the operations of \\(h\\) in reverse order. The last operation applied was subtracting 7, so the first step of inverting is adding 7." }, { stepNumber: 3, description: "Divide both sides by 2.", workingLatex: "x^2 = \\tfrac{y + 7}{2}", explanation: "Dividing by 2 undoes the multiplication by 2, leaving \\(x^2\\) isolated on one side." }, { stepNumber: 4, description: "Take square roots, choosing the positive branch.", workingLatex: "x = \\sqrt{\\tfrac{y + 7}{2}}", explanation: "Square-rooting gives \\(x = \\pm\\sqrt{(y+7)/2}\\), but the stated domain \\(x \\ge 0\\) means only the positive root is valid. A common slip is to keep the \\(\\pm\\) and produce a non-function." }, { stepNumber: 5, description: "Swap variables to write \\(h^{-1}(x)\\).", workingLatex: "h^{-1}(x) = \\sqrt{\\tfrac{x + 7}{2}}", explanation: "Relabelling \\(y \\to x\\) expresses the inverse as a function of its own input, in the standard \\(h^{-1}(x)\\) form." }, { stepNumber: 6, description: "Find the range of \\(h\\) from its endpoints.", workingLatex: "h(0) = 2(0)^2 - 7 = -7, \\qquad h(x) \\to \\infty \\text{ as } x \\to \\infty", explanation: "On \\(x \\ge 0\\) the function \\(h\\) is strictly increasing, so its smallest value is at \\(x = 0\\) and it grows without bound. Hence the range of \\(h\\) is \\(y \\ge -7\\)." }, { stepNumber: 7, description: "State the domain and range of \\(h^{-1}\\).", workingLatex: "\\text{domain: } x \\ge -7, \\qquad \\text{range: } h^{-1}(x) \\ge 0", explanation: "The domain of \\(h^{-1}\\) equals the range of \\(h\\), so \\(x \\ge -7\\); the range of \\(h^{-1}\\) equals the domain of \\(h\\), so \\(h^{-1}(x) \\ge 0\\). Inverting always swaps domain and range." }, { stepNumber: 8, description: "Substitute \\(x = 43\\) for part (b).", workingLatex: "h^{-1}(43) = \\sqrt{\\tfrac{43 + 7}{2}} = \\sqrt{\\tfrac{50}{2}}", explanation: "Part (b) asks for a single numerical value, so substitute \\(x = 43\\) into the inverse found in part (a)." }, { stepNumber: 9, description: "Simplify the surd to a whole number.", workingLatex: "h^{-1}(43) = \\sqrt{25} = 5", explanation: "Since \\(50/2 = 25\\) is a perfect square, the result is exact. Check: \\(h(5) = 2(25) - 7 = 43\\), confirming the value." } ], finalAnswer: "(a) \\( h^{-1}(x) = \\sqrt{\\tfrac{x+7}{2}} \\), domain \\( x \\ge -7 \\), range \\( h^{-1}(x) \\ge 0 \\).  (b) \\( h^{-1}(43) = 5 \\)." } },
  // ── Basic linear inverses ────
  { id: "y2fg4-002", topicRef: "y2fg4", topicTitle: "Inverse Functions 02", difficulty: "Foundation", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = 2x + 3, \\; x \\in \\mathbb{R} \\). Find \\( f^{-1}(x) \\), stating its domain and range.", marks: 3, examStyle: false, yearCreated: 2026, tags: ["inverse", "linear", "domain", "range"], workedSolution: { steps: [ { stepNumber: 1, description: "Set the output equal to \\(y\\).", workingLatex: "y = 2x + 3", explanation: "Writing \\(y = f(x)\\) gives an equation in \\(x\\) and \\(y\\); rearranging it to make \\(x\\) the subject produces the inverse." }, { stepNumber: 2, description: "Subtract 3 from both sides.", workingLatex: "y - 3 = 2x", explanation: "We reverse the operations of \\(f\\) in the opposite order. The last operation \\(f\\) applied was adding 3, so the first inverting step is subtracting 3." }, { stepNumber: 3, description: "Divide both sides by 2.", workingLatex: "x = \\tfrac{y - 3}{2}", explanation: "Dividing by 2 undoes the multiplication by 2, leaving \\(x\\) on its own." }, { stepNumber: 4, description: "Swap variables to write \\(f^{-1}(x)\\).", workingLatex: "f^{-1}(x) = \\tfrac{x - 3}{2}", explanation: "Relabelling \\(y \\to x\\) expresses the inverse as a function of \\(x\\) in the usual notation." }, { stepNumber: 5, description: "State the domain and range of \\(f^{-1}\\).", workingLatex: "\\text{domain: } x \\in \\mathbb{R}, \\qquad \\text{range: } f^{-1}(x) \\in \\mathbb{R}", explanation: "Since \\(f\\) has domain \\(\\mathbb{R}\\) and range \\(\\mathbb{R}\\), inverting swaps these, so \\(f^{-1}\\) also has domain \\(\\mathbb{R}\\) and range \\(\\mathbb{R}\\)." } ], finalAnswer: "\\( f^{-1}(x) = \\tfrac{x - 3}{2} \\), domain \\( x \\in \\mathbb{R} \\), range \\( f^{-1}(x) \\in \\mathbb{R} \\)." } },
  { id: "y2fg4-003", topicRef: "y2fg4", topicTitle: "Inverse Functions 03", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = ax + b, \\; x \\in \\mathbb{R} \\), where \\( a \\) and \\( b \\) are constants. It is given that \\( f(2) = 1 \\) and \\( f(5) = 13 \\).  (a) Find the values of \\( a \\) and \\( b \\).  (b) Find \\( f^{-1}(x) \\), stating its domain and range.  (c) Solve the equation \\( f(x) = f^{-1}(x) \\).", marks: 8, examStyle: true, yearCreated: 2026, tags: ["inverse", "linear", "domain", "range", "unknown-constant"], workedSolution: { steps: [ { stepNumber: 1, description: "Substitute \\(x = 2\\) into \\(f(x) = ax + b\\).", workingLatex: "2a + b = 1", explanation: "The condition \\(f(2) = 1\\) means the input 2 gives output 1; substituting into the formula gives a linear equation in \\(a\\) and \\(b\\)." }, { stepNumber: 2, description: "Substitute \\(x = 5\\) into \\(f(x) = ax + b\\).", workingLatex: "5a + b = 13", explanation: "Similarly \\(f(5) = 13\\) gives a second equation. Two equations are needed to find the two unknowns \\(a\\) and \\(b\\)." }, { stepNumber: 3, description: "Subtract the equations to eliminate \\(b\\).", workingLatex: "(5a + b) - (2a + b) = 13 - 1 \\Rightarrow 3a = 12", explanation: "Both equations contain \\(+b\\), so subtracting removes it and leaves a single equation in \\(a\\)." }, { stepNumber: 4, description: "Solve for \\(a\\).", workingLatex: "a = \\tfrac{12}{3} = 4", explanation: "Dividing by 3 gives the gradient \\(a = 4\\)." }, { stepNumber: 5, description: "Back-substitute to find \\(b\\).", workingLatex: "2(4) + b = 1 \\Rightarrow 8 + b = 1 \\Rightarrow b = -7", explanation: "Putting \\(a = 4\\) into the first equation gives \\(b\\). So the function is \\(f(x) = 4x - 7\\)." }, { stepNumber: 6, description: "Set \\(y = f(x)\\) to begin inverting.", workingLatex: "y = 4x - 7", explanation: "For part (b), write the output as \\(y\\) so the formula can be rearranged to make \\(x\\) the subject." }, { stepNumber: 7, description: "Add 7, then divide by 4.", workingLatex: "y + 7 = 4x \\Rightarrow x = \\tfrac{y + 7}{4}", explanation: "Undo \\(f\\) in reverse: add 7 to cancel the \\(-7\\), then divide by 4 to cancel the \\(\\times 4\\)." }, { stepNumber: 8, description: "Swap variables and state domain and range.", workingLatex: "f^{-1}(x) = \\tfrac{x + 7}{4}, \\quad \\text{domain } x \\in \\mathbb{R}, \\;\\text{range } f^{-1}(x) \\in \\mathbb{R}", explanation: "Relabel \\(y \\to x\\). Since \\(f\\) has domain and range \\(\\mathbb{R}\\), inverting swaps them, so \\(f^{-1}\\) also has domain and range \\(\\mathbb{R}\\)." }, { stepNumber: 9, description: "Set up the equation \\(f(x) = f^{-1}(x)\\).", workingLatex: "4x - 7 = \\tfrac{x + 7}{4}", explanation: "Part (c) asks where the two functions give equal outputs; equate the two expressions found above." }, { stepNumber: 10, description: "Multiply both sides by 4 to clear the fraction.", workingLatex: "16x - 28 = x + 7", explanation: "Clearing the denominator avoids fraction errors. Note \\(4 \\times (4x - 7) = 16x - 28\\) — multiply every term, not just one." }, { stepNumber: 11, description: "Collect like terms.", workingLatex: "16x - x = 7 + 28 \\Rightarrow 15x = 35", explanation: "Gather the \\(x\\)-terms on one side and the constants on the other." }, { stepNumber: 12, description: "Solve for \\(x\\) and simplify.", workingLatex: "x = \\tfrac{35}{15} = \\tfrac{7}{3}", explanation: "Dividing by 15 and cancelling the factor 5 gives \\(x = \\tfrac{7}{3}\\). Check: \\(f(\\tfrac{7}{3}) = \\tfrac{28}{3} - \\tfrac{21}{3} = \\tfrac{7}{3}\\), confirming the point lies on \\(y = x\\)." } ], finalAnswer: "(a) \\( a = 4, \\; b = -7 \\).  (b) \\( f^{-1}(x) = \\tfrac{x + 7}{4} \\), domain \\( x \\in \\mathbb{R} \\), range \\( f^{-1}(x) \\in \\mathbb{R} \\).  (c) \\( x = \\tfrac{7}{3} \\)." } },
  { id: "y2fg4-004", topicRef: "y2fg4", topicTitle: "Inverse Functions 04", difficulty: "Foundation", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = 4 - x, \\; x \\in \\mathbb{R} \\).  (a) Find \\( f^{-1}(x) \\), stating its domain and range.  (b) State what your answer to part (a) tells you about the function \\( f \\).", marks: 4, examStyle: false, yearCreated: 2026, tags: ["inverse", "linear", "self-inverse", "domain", "range"], workedSolution: { steps: [ { stepNumber: 1, description: "Set the output equal to \\(y\\).", workingLatex: "y = 4 - x", explanation: "Writing \\(y = f(x)\\) gives an equation we can rearrange to make \\(x\\) the subject." }, { stepNumber: 2, description: "Add \\(x\\) to both sides.", workingLatex: "y + x = 4", explanation: "The variable \\(x\\) currently appears with a minus sign, so adding \\(x\\) to both sides moves it to the positive side ready to be isolated." }, { stepNumber: 3, description: "Subtract \\(y\\) to isolate \\(x\\).", workingLatex: "x = 4 - y", explanation: "Subtracting \\(y\\) leaves \\(x\\) alone on one side, expressed in terms of \\(y\\)." }, { stepNumber: 4, description: "Swap variables to write \\(f^{-1}(x)\\).", workingLatex: "f^{-1}(x) = 4 - x", explanation: "Relabelling \\(y \\to x\\) expresses the inverse as a function of \\(x\\)." }, { stepNumber: 5, description: "State the domain and range of \\(f^{-1}\\).", workingLatex: "\\text{domain: } x \\in \\mathbb{R}, \\qquad \\text{range: } f^{-1}(x) \\in \\mathbb{R}", explanation: "Since \\(f\\) has domain and range \\(\\mathbb{R}\\), inverting swaps them, so \\(f^{-1}\\) also has domain \\(\\mathbb{R}\\) and range \\(\\mathbb{R}\\)." }, { stepNumber: 6, description: "Compare \\(f^{-1}\\) with \\(f\\) for part (b).", workingLatex: "f^{-1}(x) = 4 - x = f(x)", explanation: "The inverse has exactly the same formula as \\(f\\), so \\(f\\) is self-inverse: applying \\(f\\) twice returns the original input. Geometrically, the graph \\(y = 4 - x\\) is its own reflection in the line \\(y = x\\)." } ], finalAnswer: "(a) \\( f^{-1}(x) = 4 - x \\), domain \\( x \\in \\mathbb{R} \\), range \\( f^{-1}(x) \\in \\mathbb{R} \\).  (b) Since \\( f^{-1}(x) = f(x) \\), the function \\( f \\) is self-inverse." } },
  { id: "y2fg4-005", topicRef: "y2fg4", topicTitle: "Inverse Functions 05", difficulty: "Challenge", answerType: "expression", questionText: "The functions \\( f \\) and \\( g \\) are defined by \\( f(x) = 3x - 2, \\; x \\in \\mathbb{R} \\) and \\( g(x) = \\tfrac{1}{2}x + 5, \\; x \\in \\mathbb{R} \\).  (a) Find the composite function \\( gf(x) \\), simplifying your answer.  (b) Find \\( (gf)^{-1}(x) \\), stating its domain and range.  (c) Verify that \\( (gf)^{-1}(x) = f^{-1}g^{-1}(x) \\).", marks: 8, examStyle: true, yearCreated: 2026, tags: ["inverse", "linear", "composite", "domain", "range"], workedSolution: { steps: [ { stepNumber: 1, description: "Substitute \\(f(x)\\) into \\(g\\).", workingLatex: "gf(x) = g(3x - 2) = \\tfrac{1}{2}(3x - 2) + 5", explanation: "The notation \\(gf\\) means apply \\(f\\) first, then \\(g\\). The output \\(3x - 2\\) of \\(f\\) becomes the input of \\(g\\)." }, { stepNumber: 2, description: "Expand the bracket.", workingLatex: "gf(x) = \\tfrac{3}{2}x - 1 + 5", explanation: "Multiply each term inside the bracket by \\(\\tfrac{1}{2}\\): \\(\\tfrac{1}{2}(3x) = \\tfrac{3}{2}x\\) and \\(\\tfrac{1}{2}(-2) = -1\\)." }, { stepNumber: 3, description: "Collect the constant terms.", workingLatex: "gf(x) = \\tfrac{3}{2}x + 4", explanation: "Combining \\(-1 + 5 = 4\\) gives the simplified composite, which is linear." }, { stepNumber: 4, description: "Set \\(y = gf(x)\\) to begin inverting.", workingLatex: "y = \\tfrac{3}{2}x + 4", explanation: "For part (b), write the output as \\(y\\) so the formula can be rearranged for \\(x\\)." }, { stepNumber: 5, description: "Subtract 4, then multiply by \\(\\tfrac{2}{3}\\).", workingLatex: "y - 4 = \\tfrac{3}{2}x \\Rightarrow x = \\tfrac{2(y - 4)}{3}", explanation: "Undo \\(gf\\) in reverse: subtract 4 to cancel the constant, then multiply by the reciprocal \\(\\tfrac{2}{3}\\) to cancel the \\(\\tfrac{3}{2}\\)." }, { stepNumber: 6, description: "Swap variables and state domain and range.", workingLatex: "(gf)^{-1}(x) = \\tfrac{2(x - 4)}{3}, \\quad \\text{domain } x \\in \\mathbb{R}, \\;\\text{range } (gf)^{-1}(x) \\in \\mathbb{R}", explanation: "Relabel \\(y \\to x\\). Since \\(gf\\) is linear with domain and range \\(\\mathbb{R}\\), inverting swaps them, so the inverse also has domain and range \\(\\mathbb{R}\\)." }, { stepNumber: 7, description: "Find \\(f^{-1}(x)\\) for part (c).", workingLatex: "y = 3x - 2 \\Rightarrow x = \\tfrac{y + 2}{3} \\Rightarrow f^{-1}(x) = \\tfrac{x + 2}{3}", explanation: "Invert \\(f\\) on its own by adding 2 and dividing by 3, then swapping variables." }, { stepNumber: 8, description: "Find \\(g^{-1}(x)\\) for part (c).", workingLatex: "y = \\tfrac{1}{2}x + 5 \\Rightarrow x = 2(y - 5) \\Rightarrow g^{-1}(x) = 2x - 10", explanation: "Invert \\(g\\) by subtracting 5 and multiplying by 2, then swapping variables." }, { stepNumber: 9, description: "Form \\(f^{-1}g^{-1}(x)\\) by composing the inverses.", workingLatex: "f^{-1}g^{-1}(x) = f^{-1}(2x - 10) = \\tfrac{(2x - 10) + 2}{3}", explanation: "The reversal rule applies \\(g^{-1}\\) first, then \\(f^{-1}\\). Substitute \\(2x - 10\\) as the input of \\(f^{-1}\\)." }, { stepNumber: 10, description: "Simplify and compare with part (b).", workingLatex: "f^{-1}g^{-1}(x) = \\tfrac{2x - 8}{3} = \\tfrac{2(x - 4)}{3}", explanation: "Combining \\(-10 + 2 = -8\\) and factoring gives exactly \\((gf)^{-1}(x)\\) from step 6, confirming the reversal rule \\((gf)^{-1} = f^{-1}g^{-1}\\)." } ], finalAnswer: "(a) \\( gf(x) = \\tfrac{3}{2}x + 4 \\).  (b) \\( (gf)^{-1}(x) = \\tfrac{2(x - 4)}{3} \\), domain \\( x \\in \\mathbb{R} \\), range \\( (gf)^{-1}(x) \\in \\mathbb{R} \\).  (c) \\( f^{-1}g^{-1}(x) = \\tfrac{2(x-4)}{3} = (gf)^{-1}(x) \\), as required." } },
  { id: "y2fg4-006", topicRef: "y2fg4", topicTitle: "Inverse Functions 06", difficulty: "Foundation", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = \\tfrac{x}{2} - 3, \\; x \\in \\mathbb{R} \\).  (a) Find \\( f^{-1}(x) \\), stating its domain and range.  (b) Evaluate \\( f^{-1}(0) \\).", marks: 4, examStyle: false, yearCreated: 2026, tags: ["inverse", "linear", "domain", "range", "evaluate"], workedSolution: { steps: [ { stepNumber: 1, description: "Set the output equal to \\(y\\).", workingLatex: "y = \\tfrac{x}{2} - 3", explanation: "Writing \\(y = f(x)\\) gives an equation we can rearrange to make \\(x\\) the subject." }, { stepNumber: 2, description: "Add 3 to both sides.", workingLatex: "y + 3 = \\tfrac{x}{2}", explanation: "Undo \\(f\\) in reverse order. The last operation \\(f\\) applied was subtracting 3, so the first inverting step is adding 3." }, { stepNumber: 3, description: "Multiply both sides by 2.", workingLatex: "x = 2(y + 3) = 2y + 6", explanation: "Multiplying by 2 undoes the division by 2, leaving \\(x\\) isolated. Expanding the bracket gives the tidy form \\(2y + 6\\)." }, { stepNumber: 4, description: "Swap variables to write \\(f^{-1}(x)\\).", workingLatex: "f^{-1}(x) = 2x + 6", explanation: "Relabelling \\(y \\to x\\) expresses the inverse as a function of \\(x\\)." }, { stepNumber: 5, description: "State the domain and range of \\(f^{-1}\\).", workingLatex: "\\text{domain: } x \\in \\mathbb{R}, \\qquad \\text{range: } f^{-1}(x) \\in \\mathbb{R}", explanation: "Since \\(f\\) has domain and range \\(\\mathbb{R}\\), inverting swaps them, so \\(f^{-1}\\) also has domain \\(\\mathbb{R}\\) and range \\(\\mathbb{R}\\)." }, { stepNumber: 6, description: "Substitute \\(x = 0\\) for part (b).", workingLatex: "f^{-1}(0) = 2(0) + 6 = 6", explanation: "Substitute \\(x = 0\\) into the inverse. Check: \\(f(6) = \\tfrac{6}{2} - 3 = 0\\), confirming the value." } ], finalAnswer: "(a) \\( f^{-1}(x) = 2x + 6 \\), domain \\( x \\in \\mathbb{R} \\), range \\( f^{-1}(x) \\in \\mathbb{R} \\).  (b) \\( f^{-1}(0) = 6 \\)." } },
  { id: "y2fg4-007", topicRef: "y2fg4", topicTitle: "Inverse Functions 07", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = 7 - 3x, \\; x \\in \\mathbb{R} \\).  (a) Find \\( f^{-1}(x) \\), stating its domain and range.  (b) Solve the equation \\( f(x) = f^{-1}(x) \\).  (c) Hence write down the coordinates of the point where the graphs of \\( y = f(x) \\) and \\( y = f^{-1}(x) \\) intersect, and explain why this point lies on the line \\( y = x \\).", marks: 7, examStyle: true, yearCreated: 2026, tags: ["inverse", "linear", "domain", "range", "intersection"], workedSolution: { steps: [ { stepNumber: 1, description: "Set the output equal to \\(y\\).", workingLatex: "y = 7 - 3x", explanation: "Writing \\(y = f(x)\\) gives an equation we can rearrange to make \\(x\\) the subject." }, { stepNumber: 2, description: "Add \\(3x\\) and subtract \\(y\\).", workingLatex: "3x = 7 - y", explanation: "The term \\(3x\\) appears with a minus sign, so add \\(3x\\) to both sides and subtract \\(y\\) to isolate \\(3x\\) on one side." }, { stepNumber: 3, description: "Divide both sides by 3.", workingLatex: "x = \\tfrac{7 - y}{3}", explanation: "Dividing by 3 leaves \\(x\\) on its own, expressed in terms of \\(y\\)." }, { stepNumber: 4, description: "Swap variables and state domain and range.", workingLatex: "f^{-1}(x) = \\tfrac{7 - x}{3}, \\quad \\text{domain } x \\in \\mathbb{R}, \\;\\text{range } f^{-1}(x) \\in \\mathbb{R}", explanation: "Relabel \\(y \\to x\\). Since \\(f\\) has domain and range \\(\\mathbb{R}\\), inverting swaps them, so \\(f^{-1}\\) also has domain and range \\(\\mathbb{R}\\)." }, { stepNumber: 5, description: "Set up the equation \\(f(x) = f^{-1}(x)\\).", workingLatex: "7 - 3x = \\tfrac{7 - x}{3}", explanation: "Part (b) asks where the two functions give equal outputs; equate the two expressions." }, { stepNumber: 6, description: "Multiply both sides by 3 to clear the fraction.", workingLatex: "21 - 9x = 7 - x", explanation: "Clearing the denominator avoids fraction errors. Multiply every term on the left by 3: \\(3(7 - 3x) = 21 - 9x\\)." }, { stepNumber: 7, description: "Collect like terms.", workingLatex: "21 - 7 = 9x - x \\Rightarrow 14 = 8x", explanation: "Gather constants on one side and \\(x\\)-terms on the other to isolate a single \\(x\\)-term." }, { stepNumber: 8, description: "Solve for \\(x\\) and simplify.", workingLatex: "x = \\tfrac{14}{8} = \\tfrac{7}{4}", explanation: "Dividing by 8 and cancelling the factor 2 gives \\(x = \\tfrac{7}{4}\\)." }, { stepNumber: 9, description: "Find the corresponding \\(y\\)-value.", workingLatex: "f\\left(\\tfrac{7}{4}\\right) = 7 - 3 \\cdot \\tfrac{7}{4} = 7 - \\tfrac{21}{4} = \\tfrac{7}{4}", explanation: "Substituting \\(x = \\tfrac{7}{4}\\) into \\(f\\) gives output \\(\\tfrac{7}{4}\\): the input equals the output, so the point sits on \\(y = x\\)." }, { stepNumber: 10, description: "State the intersection point and justify for part (c).", workingLatex: "\\left(\\tfrac{7}{4}, \\tfrac{7}{4}\\right)", explanation: "The graph of \\(y = f^{-1}(x)\\) is the reflection of \\(y = f(x)\\) in the line \\(y = x\\). Any point common to both graphs is unchanged by that reflection, so it must lie on the mirror line \\(y = x\\) — its coordinates have equal \\(x\\)- and \\(y\\)-values." } ], finalAnswer: "(a) \\( f^{-1}(x) = \\tfrac{7 - x}{3} \\), domain \\( x \\in \\mathbb{R} \\), range \\( f^{-1}(x) \\in \\mathbb{R} \\).  (b) \\( x = \\tfrac{7}{4} \\).  (c) The graphs intersect at \\( \\left(\\tfrac{7}{4}, \\tfrac{7}{4}\\right) \\); since \\( y = f^{-1}(x) \\) is the reflection of \\( y = f(x) \\) in \\( y = x \\), any common point is unchanged by the reflection and therefore lies on \\( y = x \\)." } },
  { id: "y2fg4-008", topicRef: "y2fg4", topicTitle: "Inverse Functions 08", difficulty: "Foundation", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = \\tfrac{2x + 1}{3}, \\; x \\in \\mathbb{R} \\). Find \\( f^{-1}(x) \\), stating its domain and range.", marks: 3, examStyle: false, yearCreated: 2026, tags: ["inverse", "linear", "domain", "range"], workedSolution: { steps: [ { stepNumber: 1, description: "Set the output equal to \\(y\\).", workingLatex: "y = \\tfrac{2x + 1}{3}", explanation: "Writing \\(y = f(x)\\) gives an equation we can rearrange to make \\(x\\) the subject." }, { stepNumber: 2, description: "Multiply both sides by 3.", workingLatex: "3y = 2x + 1", explanation: "Clearing the denominator first removes the fraction, making the rearrangement straightforward." }, { stepNumber: 3, description: "Subtract 1 from both sides.", workingLatex: "3y - 1 = 2x", explanation: "This isolates the term in \\(x\\) on one side of the equation." }, { stepNumber: 4, description: "Divide both sides by 2.", workingLatex: "x = \\tfrac{3y - 1}{2}", explanation: "Dividing by 2 leaves \\(x\\) on its own, expressed in terms of \\(y\\)." }, { stepNumber: 5, description: "Swap variables and state domain and range.", workingLatex: "f^{-1}(x) = \\tfrac{3x - 1}{2}, \\quad \\text{domain } x \\in \\mathbb{R}, \\;\\text{range } f^{-1}(x) \\in \\mathbb{R}", explanation: "Relabel \\(y \\to x\\). Since \\(f\\) has domain and range \\(\\mathbb{R}\\), inverting swaps them, so \\(f^{-1}\\) also has domain \\(\\mathbb{R}\\) and range \\(\\mathbb{R}\\)." } ], finalAnswer: "\\( f^{-1}(x) = \\tfrac{3x - 1}{2} \\), domain \\( x \\in \\mathbb{R} \\), range \\( f^{-1}(x) \\in \\mathbb{R} \\)." } },
  { id: "y2fg4-009", topicRef: "y2fg4", topicTitle: "Inverse Functions 09", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = 6 - 2x, \\; x \\in \\mathbb{R}, \\; 1 \\le x \\le 4 \\).  (a) Find the range of \\( f \\).  (b) Find \\( f^{-1}(x) \\), stating its domain and range.  (c) Explain why \\( f^{-1} \\) exists for this function.", marks: 7, examStyle: true, yearCreated: 2026, tags: ["inverse", "linear", "domain", "range", "restricted-domain"], workedSolution: { steps: [ { stepNumber: 1, description: "Evaluate \\(f\\) at the left endpoint.", workingLatex: "f(1) = 6 - 2(1) = 4", explanation: "For part (a), the range of a linear function on a closed interval is found from its endpoint values; start with \\(x = 1\\)." }, { stepNumber: 2, description: "Evaluate \\(f\\) at the right endpoint.", workingLatex: "f(4) = 6 - 2(4) = -2", explanation: "Now evaluate at \\(x = 4\\). The two endpoint values bound the range." }, { stepNumber: 3, description: "State the range using monotonicity.", workingLatex: "\\text{range of } f: \\; -2 \\le f(x) \\le 4", explanation: "\\(f\\) has gradient \\(-2\\), so it is strictly decreasing: the greatest output is at \\(x = 1\\) and the least at \\(x = 4\\). The range runs continuously between them." }, { stepNumber: 4, description: "Set \\(y = f(x)\\) to begin inverting.", workingLatex: "y = 6 - 2x", explanation: "For part (b), write the output as \\(y\\) so the formula can be rearranged for \\(x\\)." }, { stepNumber: 5, description: "Isolate the term \\(2x\\).", workingLatex: "2x = 6 - y", explanation: "Add \\(2x\\) to both sides and subtract \\(y\\), since \\(2x\\) currently carries a minus sign." }, { stepNumber: 6, description: "Divide by 2 and swap variables.", workingLatex: "x = \\tfrac{6 - y}{2} \\Rightarrow f^{-1}(x) = \\tfrac{6 - x}{2}", explanation: "Dividing by 2 isolates \\(x\\); relabelling \\(y \\to x\\) gives the inverse in standard form." }, { stepNumber: 7, description: "State the domain and range of \\(f^{-1}\\).", workingLatex: "\\text{domain: } -2 \\le x \\le 4, \\qquad \\text{range: } 1 \\le f^{-1}(x) \\le 4", explanation: "The domain of \\(f^{-1}\\) equals the range of \\(f\\) found in part (a), \\([-2, 4]\\); the range of \\(f^{-1}\\) equals the domain of \\(f\\), \\([1, 4]\\). Inverting always swaps domain and range." }, { stepNumber: 8, description: "Explain why \\(f^{-1}\\) exists for part (c).", workingLatex: "f \\text{ strictly decreasing on } [1, 4] \\;\\Rightarrow\\; f \\text{ is one-to-one}", explanation: "\\(f\\) is a strictly decreasing linear function on \\([1, 4]\\), so each output comes from exactly one input — it passes the horizontal-line test. A one-to-one function has a well-defined inverse, so \\(f^{-1}\\) exists." } ], finalAnswer: "(a) Range of \\( f \\) is \\( -2 \\le f(x) \\le 4 \\).  (b) \\( f^{-1}(x) = \\tfrac{6 - x}{2} \\), domain \\( -2 \\le x \\le 4 \\), range \\( 1 \\le f^{-1}(x) \\le 4 \\).  (c) \\( f \\) is strictly decreasing and therefore one-to-one on \\( [1, 4] \\), so an inverse exists." } },
  { id: "y2fg4-010", topicRef: "y2fg4", topicTitle: "Inverse Functions 10", difficulty: "Foundation", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = \\tfrac{1}{2}x + 4, \\; x \\in \\mathbb{R} \\).  (a) Find \\( f^{-1}(x) \\), stating its domain and range.  (b) Evaluate \\( f^{-1}(10) \\).", marks: 4, examStyle: false, yearCreated: 2026, tags: ["inverse", "linear", "domain", "range", "evaluate"], workedSolution: { steps: [ { stepNumber: 1, description: "Set the output equal to \\(y\\).", workingLatex: "y = \\tfrac{x}{2} + 4", explanation: "Writing \\(y = f(x)\\) gives an equation we can rearrange to make \\(x\\) the subject." }, { stepNumber: 2, description: "Subtract 4 from both sides.", workingLatex: "y - 4 = \\tfrac{x}{2}", explanation: "Undo \\(f\\) in reverse order. The last operation \\(f\\) applied was adding 4, so the first inverting step is subtracting 4." }, { stepNumber: 3, description: "Multiply both sides by 2.", workingLatex: "x = 2(y - 4) = 2y - 8", explanation: "Multiplying by 2 undoes the division by 2. Expanding the bracket gives the tidy form \\(2y - 8\\)." }, { stepNumber: 4, description: "Swap variables to write \\(f^{-1}(x)\\).", workingLatex: "f^{-1}(x) = 2x - 8", explanation: "Relabelling \\(y \\to x\\) expresses the inverse as a function of \\(x\\)." }, { stepNumber: 5, description: "State the domain and range of \\(f^{-1}\\).", workingLatex: "\\text{domain: } x \\in \\mathbb{R}, \\qquad \\text{range: } f^{-1}(x) \\in \\mathbb{R}", explanation: "Since \\(f\\) has domain and range \\(\\mathbb{R}\\), inverting swaps them, so \\(f^{-1}\\) also has domain \\(\\mathbb{R}\\) and range \\(\\mathbb{R}\\)." }, { stepNumber: 6, description: "Substitute \\(x = 10\\) for part (b).", workingLatex: "f^{-1}(10) = 2(10) - 8 = 12", explanation: "Substitute \\(x = 10\\) into the inverse. Check: \\(f(12) = \\tfrac{12}{2} + 4 = 10\\), confirming the value." } ], finalAnswer: "(a) \\( f^{-1}(x) = 2x - 8 \\), domain \\( x \\in \\mathbb{R} \\), range \\( f^{-1}(x) \\in \\mathbb{R} \\).  (b) \\( f^{-1}(10) = 12 \\)." } },
  // ── Quadratic inverses with restricted domain ────
  { id: "y2fg4-011", topicRef: "y2fg4", topicTitle: "Inverse Functions 11", difficulty: "Foundation", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = x^2, \\; x \\in \\mathbb{R}, \\; x \\ge 0 \\). Find \\( f^{-1}(x) \\), stating its domain and range.", marks: 3, examStyle: false, yearCreated: 2026, tags: ["inverse", "quadratic", "domain", "range", "restricted-domain"], workedSolution: { steps: [ { stepNumber: 1, description: "Set the output equal to \\(y\\).", workingLatex: "y = x^2", explanation: "Writing \\(y = f(x)\\) gives an equation we can rearrange to make \\(x\\) the subject." }, { stepNumber: 2, description: "Take square roots, choosing the positive branch.", workingLatex: "x = \\sqrt{y}", explanation: "Square-rooting gives \\(x = \\pm\\sqrt{y}\\), but the stated domain \\(x \\ge 0\\) selects only the positive root. Dropping the restriction would make the inverse non-unique." }, { stepNumber: 3, description: "Swap variables to write \\(f^{-1}(x)\\).", workingLatex: "f^{-1}(x) = \\sqrt{x}", explanation: "Relabelling \\(y \\to x\\) expresses the inverse as a function of \\(x\\)." }, { stepNumber: 4, description: "State the domain and range of \\(f^{-1}\\).", workingLatex: "\\text{domain: } x \\ge 0, \\qquad \\text{range: } f^{-1}(x) \\ge 0", explanation: "On \\(x \\ge 0\\), \\(f\\) is strictly increasing with range \\([0, \\infty)\\), so the domain of \\(f^{-1}\\) is \\(x \\ge 0\\). The range of \\(f^{-1}\\) equals the domain of \\(f\\), giving \\(f^{-1}(x) \\ge 0\\)." } ], finalAnswer: "\\( f^{-1}(x) = \\sqrt{x} \\), domain \\( x \\ge 0 \\), range \\( f^{-1}(x) \\ge 0 \\)." } },
  { id: "y2fg4-012", topicRef: "y2fg4", topicTitle: "Inverse Functions 12", difficulty: "Standard", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = x^2 + 3 \\), \\( x \\ge 0 \\). Find \\( f^{-1}(x) \\), stating its domain and range.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["inverse", "quadratic", "domain", "range"], workedSolution: { steps: [ { stepNumber: 1, description: "Write \\(y = f(x)\\) to start the inversion.", workingLatex: "y = x^2 + 3", explanation: "Setting \\(y\\) equal to the rule lets us treat the inverse as 'rearrange to make \\(x\\) the subject'. This is the standard opening move for finding an inverse." }, { stepNumber: 2, description: "Subtract 3 to isolate \\(x^2\\).", workingLatex: "x^2 = y - 3", explanation: "We undo the \\(+3\\) first because it is the outermost operation applied to \\(x\\); peeling operations off in reverse order is the key to making \\(x\\) the subject." }, { stepNumber: 3, description: "Take the square root, choosing the correct branch.", workingLatex: "x = \\sqrt{y - 3}", explanation: "Square-rooting normally gives \\(\\pm\\), but the stated domain \\(x \\ge 0\\) forces \\(x\\) to be non-negative, so only the positive root is valid. Dropping this restriction and keeping \\(\\pm\\) is a common slip." }, { stepNumber: 4, description: "Swap variables to write the inverse.", workingLatex: "f^{-1}(x) = \\sqrt{x - 3}", explanation: "Relabelling \\(y\\) as \\(x\\) expresses the inverse as a function of its own input, in the standard form expected in the answer." }, { stepNumber: 5, description: "Find the range of \\(f\\) to get the domain of \\(f^{-1}\\).", workingLatex: "\\text{domain of } f^{-1} = \\text{range of } f = [3, \\infty),\\;\\; x \\ge 3", explanation: "On \\(x \\ge 0\\), \\(f\\) is strictly increasing with minimum \\(f(0) = 3\\), so its range is \\(y \\ge 3\\). The domain of the inverse is exactly the range of the original function." }, { stepNumber: 6, description: "State the range of \\(f^{-1}\\).", workingLatex: "\\text{range of } f^{-1} = \\text{domain of } f = [0, \\infty),\\;\\; f^{-1}(x) \\ge 0", explanation: "The range of an inverse equals the domain of the original function, namely \\(f^{-1}(x) \\ge 0\\). This is consistent with \\(\\sqrt{\\;}\\) only producing non-negative outputs." } ], finalAnswer: "\\( f^{-1}(x) = \\sqrt{x - 3} \\), with domain \\( x \\ge 3 \\) and range \\( f^{-1}(x) \\ge 0 \\)." } },
  { id: "y2fg4-013", topicRef: "y2fg4", topicTitle: "Inverse Functions 13", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = x^2 - 8x + 22 \\), \\( x \\ge 4 \\).  (a) Express \\( f(x) \\) in the form \\( (x - a)^2 + b \\).  (b) Find \\( f^{-1}(x) \\), stating its domain and range.  (c) Solve the equation \\( f^{-1}(x) = 9 \\).", marks: 8, examStyle: true, yearCreated: 2026, tags: ["inverse", "quadratic", "complete-the-square", "domain", "range", "evaluate"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): form the square term from the \\(x\\)-coefficient.", workingLatex: "x^2 - 8x = (x - 4)^2 - 16", explanation: "Half of the \\(x\\)-coefficient \\(-8\\) is \\(-4\\), so \\((x-4)^2 = x^2 - 8x + 16\\). We subtract 16 to cancel the unwanted \\(+16\\) this introduces." }, { stepNumber: 2, description: "Combine the constants to finish completing the square.", workingLatex: "x^2 - 8x + 22 = (x - 4)^2 - 16 + 22 = (x - 4)^2 + 6", explanation: "Adding the original \\(+22\\) and simplifying \\(-16 + 22 = 6\\) gives the completed-square form with \\(a = 4,\\; b = 6\\), so the vertex is \\((4, 6)\\)." }, { stepNumber: 3, description: "Part (b): write \\(y = f(x)\\) and subtract 6.", workingLatex: "y = (x - 4)^2 + 6 \\Rightarrow (x - 4)^2 = y - 6", explanation: "Working from the completed-square form is easier than from \\(x^2 - 8x + 22\\); subtracting 6 isolates the squared bracket ready for rooting." }, { stepNumber: 4, description: "Take the square root on the correct branch.", workingLatex: "x - 4 = \\sqrt{y - 6}", explanation: "The domain \\(x \\ge 4\\) means \\(x - 4 \\ge 0\\), so the bracket is non-negative and only the positive root is taken. Choosing the negative root would give the wrong half of the parabola." }, { stepNumber: 5, description: "Add 4 to make \\(x\\) the subject.", workingLatex: "x = 4 + \\sqrt{y - 6}", explanation: "Undoing the \\(-4\\) inside the bracket completes the rearrangement, expressing \\(x\\) purely in terms of \\(y\\)." }, { stepNumber: 6, description: "Swap variables to write the inverse.", workingLatex: "f^{-1}(x) = 4 + \\sqrt{x - 6}", explanation: "Relabelling \\(y\\) as \\(x\\) gives the inverse in standard function form." }, { stepNumber: 7, description: "State the domain and range of \\(f^{-1}\\).", workingLatex: "\\text{domain: } x \\ge 6,\\qquad \\text{range: } f^{-1}(x) \\ge 4", explanation: "On \\(x \\ge 4\\), \\(f\\) is strictly increasing with minimum \\(f(4) = 6\\), so the range of \\(f\\) is \\(y \\ge 6\\), which becomes the domain of \\(f^{-1}\\). The range of \\(f^{-1}\\) equals the domain of \\(f\\), namely \\(f^{-1}(x) \\ge 4\\)." }, { stepNumber: 8, description: "Part (c): set up the equation \\(f^{-1}(x) = 9\\).", workingLatex: "4 + \\sqrt{x - 6} = 9", explanation: "Substituting the inverse rule turns the requirement into an equation in \\(x\\) that can be solved by isolating the surd." }, { stepNumber: 9, description: "Isolate the square root.", workingLatex: "\\sqrt{x - 6} = 5", explanation: "Subtracting 4 from both sides leaves the surd alone, so the next step can remove it cleanly by squaring." }, { stepNumber: 10, description: "Square both sides and solve for \\(x\\).", workingLatex: "x - 6 = 25 \\Rightarrow x = 31", explanation: "Squaring removes the root and adding 6 gives \\(x = 31\\). Check: \\(x = 31 \\ge 6\\) lies in the domain of \\(f^{-1}\\), and \\(f(9) = (9-4)^2 + 6 = 31\\) confirms it." } ], finalAnswer: "(a) \\( f(x) = (x - 4)^2 + 6 \\). (b) \\( f^{-1}(x) = 4 + \\sqrt{x - 6} \\), with domain \\( x \\ge 6 \\) and range \\( f^{-1}(x) \\ge 4 \\). (c) \\( x = 31 \\)." } },
  { id: "y2fg4-014", topicRef: "y2fg4", topicTitle: "Inverse Functions 14", difficulty: "Standard", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = (x + 2)^2 - 5 \\), \\( x \\ge -2 \\).  (a) Find \\( f^{-1}(x) \\), stating its domain and range.  (b) Evaluate \\( f^{-1}(11) \\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["inverse", "quadratic", "domain", "range", "evaluate"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): write \\(y = f(x)\\) and add 5.", workingLatex: "y = (x + 2)^2 - 5 \\Rightarrow (x + 2)^2 = y + 5", explanation: "Setting \\(y = f(x)\\) starts the inversion; adding 5 to both sides isolates the squared bracket, which is the part we need to undo." }, { stepNumber: 2, description: "Take the square root on the correct branch.", workingLatex: "x + 2 = \\sqrt{y + 5}", explanation: "The domain \\(x \\ge -2\\) gives \\(x + 2 \\ge 0\\), so the bracket is non-negative and only the positive root applies. Keeping a \\(\\pm\\) here would wrongly include the discarded half of the parabola." }, { stepNumber: 3, description: "Subtract 2 to make \\(x\\) the subject.", workingLatex: "x = -2 + \\sqrt{y + 5}", explanation: "Undoing the \\(+2\\) inside the bracket isolates \\(x\\) completely in terms of \\(y\\)." }, { stepNumber: 4, description: "Swap variables to write the inverse.", workingLatex: "f^{-1}(x) = \\sqrt{x + 5} - 2", explanation: "Relabelling \\(y\\) as \\(x\\) expresses the inverse in standard form." }, { stepNumber: 5, description: "State the domain and range of \\(f^{-1}\\).", workingLatex: "\\text{domain: } x \\ge -5,\\qquad \\text{range: } f^{-1}(x) \\ge -2", explanation: "On \\(x \\ge -2\\), \\(f\\) is strictly increasing with minimum \\(f(-2) = -5\\), so the range of \\(f\\) is \\(y \\ge -5\\), which becomes the domain of \\(f^{-1}\\). The range of \\(f^{-1}\\) equals the domain of \\(f\\), namely \\(f^{-1}(x) \\ge -2\\)." }, { stepNumber: 6, description: "Part (b): substitute \\(x = 11\\) into the inverse.", workingLatex: "f^{-1}(11) = \\sqrt{11 + 5} - 2", explanation: "Since \\(11 \\ge -5\\), the input lies in the domain of \\(f^{-1}\\), so the evaluation is valid." }, { stepNumber: 7, description: "Simplify the surd and finish the arithmetic.", workingLatex: "\\sqrt{16} - 2 = 4 - 2 = 2", explanation: "Since \\(11 + 5 = 16\\) is a perfect square, \\(\\sqrt{16} = 4\\) and \\(4 - 2 = 2\\). Check: \\(f(2) = (2+2)^2 - 5 = 11\\)." } ], finalAnswer: "(a) \\( f^{-1}(x) = \\sqrt{x + 5} - 2 \\), with domain \\( x \\ge -5 \\) and range \\( f^{-1}(x) \\ge -2 \\). (b) \\( f^{-1}(11) = 2 \\)." } },
  { id: "y2fg4-015", topicRef: "y2fg4", topicTitle: "Inverse Functions 15", difficulty: "Standard", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = 3x^2 + 1 \\), \\( x \\ge 0 \\). Find \\( f^{-1}(x) \\), stating its domain and range.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["inverse", "quadratic", "domain", "range"], workedSolution: { steps: [ { stepNumber: 1, description: "Write \\(y = f(x)\\) and subtract 1.", workingLatex: "y = 3x^2 + 1 \\Rightarrow 3x^2 = y - 1", explanation: "Setting \\(y = f(x)\\) begins the inversion; subtracting 1 undoes the outermost operation, leaving the term containing \\(x\\)." }, { stepNumber: 2, description: "Divide by 3 to isolate \\(x^2\\).", workingLatex: "x^2 = \\tfrac{y - 1}{3}", explanation: "Dividing by the coefficient 3 isolates \\(x^2\\). A common slip is to take the root before dividing, which mishandles the factor of 3." }, { stepNumber: 3, description: "Take the square root on the correct branch.", workingLatex: "x = \\sqrt{\\tfrac{y - 1}{3}}", explanation: "The domain \\(x \\ge 0\\) means \\(x\\) is non-negative, so only the positive square root is taken." }, { stepNumber: 4, description: "Swap variables to write the inverse.", workingLatex: "f^{-1}(x) = \\sqrt{\\tfrac{x - 1}{3}}", explanation: "Relabelling \\(y\\) as \\(x\\) gives the inverse in standard function form." }, { stepNumber: 5, description: "Find the range of \\(f\\) to get the domain of \\(f^{-1}\\).", workingLatex: "\\text{domain of } f^{-1} = \\text{range of } f,\\;\\; x \\ge 1", explanation: "On \\(x \\ge 0\\), \\(f\\) is strictly increasing with minimum \\(f(0) = 1\\), so the range of \\(f\\) is \\(y \\ge 1\\). The domain of the inverse equals this range." }, { stepNumber: 6, description: "State the range of \\(f^{-1}\\).", workingLatex: "\\text{range of } f^{-1} = \\text{domain of } f,\\;\\; f^{-1}(x) \\ge 0", explanation: "The range of an inverse equals the domain of the original function, namely \\(f^{-1}(x) \\ge 0\\), consistent with the surd producing only non-negative values." } ], finalAnswer: "\\( f^{-1}(x) = \\sqrt{\\tfrac{x - 1}{3}} \\), with domain \\( x \\ge 1 \\) and range \\( f^{-1}(x) \\ge 0 \\)." } },
  { id: "y2fg4-016", topicRef: "y2fg4", topicTitle: "Inverse Functions 16", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = x^2 - 4x + 5 \\), \\( x \\ge 2 \\).  (a) Find \\( f^{-1}(x) \\), stating its domain and range.  (b) Evaluate \\( f^{-1}(10) \\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["inverse", "complete-the-square", "quadratic", "domain", "range", "evaluate"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): form the square term.", workingLatex: "x^2 - 4x = (x - 2)^2 - 4", explanation: "Half of the \\(x\\)-coefficient \\(-4\\) is \\(-2\\), so \\((x-2)^2 = x^2 - 4x + 4\\); subtract 4 to cancel the unwanted constant it introduces." }, { stepNumber: 2, description: "Combine constants to complete the square.", workingLatex: "f(x) = (x - 2)^2 - 4 + 5 = (x - 2)^2 + 1", explanation: "Including the original \\(+5\\) and simplifying \\(-4 + 5 = 1\\) gives the completed-square form with vertex \\((2, 1)\\)." }, { stepNumber: 3, description: "Write \\(y = f(x)\\) and subtract 1.", workingLatex: "y = (x - 2)^2 + 1 \\Rightarrow (x - 2)^2 = y - 1", explanation: "Working from the completed-square form, subtracting 1 isolates the squared bracket ready for rooting." }, { stepNumber: 4, description: "Take the square root on the correct branch.", workingLatex: "x - 2 = \\sqrt{y - 1}", explanation: "The domain \\(x \\ge 2\\) gives \\(x - 2 \\ge 0\\), so the bracket is non-negative and only the positive root is valid." }, { stepNumber: 5, description: "Add 2 and swap variables.", workingLatex: "x = 2 + \\sqrt{y - 1} \\Rightarrow f^{-1}(x) = 2 + \\sqrt{x - 1}", explanation: "Adding 2 makes \\(x\\) the subject; relabelling \\(y\\) as \\(x\\) gives the inverse in standard form." }, { stepNumber: 6, description: "State the domain and range of \\(f^{-1}\\).", workingLatex: "\\text{domain: } x \\ge 1,\\qquad \\text{range: } f^{-1}(x) \\ge 2", explanation: "On \\(x \\ge 2\\), \\(f\\) is strictly increasing with minimum value 1 at the vertex, so the range of \\(f\\) is \\(y \\ge 1\\), which becomes the domain of \\(f^{-1}\\). The range of \\(f^{-1}\\) equals the domain of \\(f\\), namely \\(f^{-1}(x) \\ge 2\\)." }, { stepNumber: 7, description: "Part (b): substitute \\(x = 10\\) into the inverse.", workingLatex: "f^{-1}(10) = 2 + \\sqrt{10 - 1}", explanation: "Since \\(10 \\ge 1\\), the input lies in the domain of \\(f^{-1}\\), so the evaluation is valid." }, { stepNumber: 8, description: "Simplify the surd and finish the arithmetic.", workingLatex: "2 + \\sqrt{9} = 2 + 3 = 5", explanation: "Since \\(10 - 1 = 9\\) is a perfect square, \\(\\sqrt{9} = 3\\) and \\(2 + 3 = 5\\). Check: \\(f(5) = (5-2)^2 + 1 = 10\\)." } ], finalAnswer: "(a) \\( f^{-1}(x) = 2 + \\sqrt{x - 1} \\), with domain \\( x \\ge 1 \\) and range \\( f^{-1}(x) \\ge 2 \\). (b) \\( f^{-1}(10) = 5 \\)." } },
  { id: "y2fg4-017", topicRef: "y2fg4", topicTitle: "Inverse Functions 17", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = 2x^2 + 4x + 3 \\), \\( x \\ge -1 \\).  (a) Express \\( f(x) \\) in the form \\( a(x + b)^2 + c \\).  (b) Find \\( f^{-1}(x) \\), stating its domain and range.", marks: 7, examStyle: true, yearCreated: 2026, tags: ["inverse", "complete-the-square", "quadratic", "domain", "range"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): factor the leading coefficient from the \\(x\\)-terms.", workingLatex: "2x^2 + 4x + 3 = 2(x^2 + 2x) + 3", explanation: "Completing the square needs a unit coefficient on \\(x^2\\), so factor 2 out of the \\(x\\)-terms only, leaving the constant 3 outside." }, { stepNumber: 2, description: "Complete the square inside the bracket.", workingLatex: "x^2 + 2x = (x + 1)^2 - 1", explanation: "Half of the inner \\(x\\)-coefficient 2 is 1, so \\((x+1)^2 = x^2 + 2x + 1\\); subtract 1 inside to compensate." }, { stepNumber: 3, description: "Distribute the factor of 2 and simplify.", workingLatex: "2[(x + 1)^2 - 1] + 3 = 2(x + 1)^2 + 1", explanation: "Multiplying out gives \\(2(x+1)^2 - 2 + 3 = 2(x+1)^2 + 1\\), so \\(a = 2,\\; b = 1,\\; c = 1\\), with vertex \\((-1, 1)\\). Forgetting to multiply the \\(-1\\) by 2 is a common error here." }, { stepNumber: 4, description: "Part (b): write \\(y = f(x)\\) and subtract 1.", workingLatex: "y = 2(x + 1)^2 + 1 \\Rightarrow 2(x + 1)^2 = y - 1", explanation: "Setting \\(y = f(x)\\) starts the inversion; subtracting 1 removes the outer constant." }, { stepNumber: 5, description: "Divide by 2 to isolate the squared bracket.", workingLatex: "(x + 1)^2 = \\tfrac{y - 1}{2}", explanation: "Dividing by the leading coefficient 2 leaves the bracket alone. The division must happen before rooting, or the factor of 2 is mishandled." }, { stepNumber: 6, description: "Take the square root on the correct branch.", workingLatex: "x + 1 = \\sqrt{\\tfrac{y - 1}{2}}", explanation: "The domain \\(x \\ge -1\\) gives \\(x + 1 \\ge 0\\), so the bracket is non-negative and only the positive root is taken." }, { stepNumber: 7, description: "Subtract 1 and swap variables.", workingLatex: "x = \\sqrt{\\tfrac{y - 1}{2}} - 1 \\Rightarrow f^{-1}(x) = \\sqrt{\\tfrac{x - 1}{2}} - 1", explanation: "Subtracting 1 makes \\(x\\) the subject; relabelling \\(y\\) as \\(x\\) gives the inverse in standard form." }, { stepNumber: 8, description: "State the domain and range of \\(f^{-1}\\).", workingLatex: "\\text{domain: } x \\ge 1,\\qquad \\text{range: } f^{-1}(x) \\ge -1", explanation: "On \\(x \\ge -1\\), \\(f\\) is strictly increasing with minimum value 1 at the vertex, so the range of \\(f\\) is \\(y \\ge 1\\), which becomes the domain of \\(f^{-1}\\). The range of \\(f^{-1}\\) equals the domain of \\(f\\), namely \\(f^{-1}(x) \\ge -1\\)." } ], finalAnswer: "(a) \\( f(x) = 2(x + 1)^2 + 1 \\). (b) \\( f^{-1}(x) = \\sqrt{\\tfrac{x - 1}{2}} - 1 \\), with domain \\( x \\ge 1 \\) and range \\( f^{-1}(x) \\ge -1 \\)." } },
  { id: "y2fg4-018", topicRef: "y2fg4", topicTitle: "Inverse Functions 18", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = x^2 - 6x + 10 \\), \\( x \\ge 3 \\).  (a) Find \\( f^{-1}(x) \\), stating its domain and range.  (b) Evaluate \\( f^{-1}(5) \\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["inverse", "complete-the-square", "quadratic", "domain", "range", "evaluate"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): form the square term.", workingLatex: "x^2 - 6x = (x - 3)^2 - 9", explanation: "Half of the \\(x\\)-coefficient \\(-6\\) is \\(-3\\), so \\((x-3)^2 = x^2 - 6x + 9\\); subtract 9 to cancel the constant it introduces." }, { stepNumber: 2, description: "Combine constants to complete the square.", workingLatex: "f(x) = (x - 3)^2 - 9 + 10 = (x - 3)^2 + 1", explanation: "Including the original \\(+10\\) and simplifying \\(-9 + 10 = 1\\) gives the completed-square form with vertex \\((3, 1)\\)." }, { stepNumber: 3, description: "Write \\(y = f(x)\\) and subtract 1.", workingLatex: "y = (x - 3)^2 + 1 \\Rightarrow (x - 3)^2 = y - 1", explanation: "Setting \\(y = f(x)\\) starts the inversion; subtracting 1 isolates the squared bracket ready for rooting." }, { stepNumber: 4, description: "Take the square root on the correct branch.", workingLatex: "x - 3 = \\sqrt{y - 1}", explanation: "The domain \\(x \\ge 3\\) gives \\(x - 3 \\ge 0\\), so the bracket is non-negative and only the positive root is valid." }, { stepNumber: 5, description: "Add 3 and swap variables.", workingLatex: "x = 3 + \\sqrt{y - 1} \\Rightarrow f^{-1}(x) = 3 + \\sqrt{x - 1}", explanation: "Adding 3 makes \\(x\\) the subject; relabelling \\(y\\) as \\(x\\) gives the inverse in standard form." }, { stepNumber: 6, description: "State the domain and range of \\(f^{-1}\\).", workingLatex: "\\text{domain: } x \\ge 1,\\qquad \\text{range: } f^{-1}(x) \\ge 3", explanation: "On \\(x \\ge 3\\), \\(f\\) is strictly increasing with minimum value 1 at the vertex, so the range of \\(f\\) is \\(y \\ge 1\\), which becomes the domain of \\(f^{-1}\\). The range of \\(f^{-1}\\) equals the domain of \\(f\\), namely \\(f^{-1}(x) \\ge 3\\)." }, { stepNumber: 7, description: "Part (b): substitute \\(x = 5\\) into the inverse.", workingLatex: "f^{-1}(5) = 3 + \\sqrt{5 - 1}", explanation: "Since \\(5 \\ge 1\\), the input lies in the domain of \\(f^{-1}\\), so the evaluation is valid." }, { stepNumber: 8, description: "Simplify the surd and finish the arithmetic.", workingLatex: "3 + \\sqrt{4} = 3 + 2 = 5", explanation: "Since \\(5 - 1 = 4\\) is a perfect square, \\(\\sqrt{4} = 2\\) and \\(3 + 2 = 5\\). Check: \\(f(5) = (5-3)^2 + 1 = 5\\)." } ], finalAnswer: "(a) \\( f^{-1}(x) = 3 + \\sqrt{x - 1} \\), with domain \\( x \\ge 1 \\) and range \\( f^{-1}(x) \\ge 3 \\). (b) \\( f^{-1}(5) = 5 \\)." } },
  { id: "y2fg4-019", topicRef: "y2fg4", topicTitle: "Inverse Functions 19", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = 20 - x^2 - 6x \\), \\( x \\ge -3 \\).  (a) Express \\( f(x) \\) in the form \\( a - (x + b)^2 \\).  (b) Explain why \\( f \\) has an inverse on this domain.  (c) Find \\( f^{-1}(x) \\), stating its domain and range.  (d) Evaluate \\( f^{-1}(4) \\).", marks: 8, examStyle: true, yearCreated: 2026, tags: ["inverse", "complete-the-square", "quadratic", "domain", "range", "evaluate"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): factor \\(-1\\) from the \\(x\\)-terms.", workingLatex: "20 - x^2 - 6x = 20 - (x^2 + 6x)", explanation: "To complete the square we need a positive unit coefficient on \\(x^2\\), so pull \\(-1\\) out of the two \\(x\\)-terms, leaving the constant 20 outside." }, { stepNumber: 2, description: "Complete the square inside the bracket.", workingLatex: "x^2 + 6x = (x + 3)^2 - 9", explanation: "Half of the inner coefficient 6 is 3, so \\((x+3)^2 = x^2 + 6x + 9\\); subtract 9 inside to compensate." }, { stepNumber: 3, description: "Substitute back and simplify the constants.", workingLatex: "20 - [(x + 3)^2 - 9] = 29 - (x + 3)^2", explanation: "Distributing the \\(-1\\) gives \\(20 - (x+3)^2 + 9 = 29 - (x+3)^2\\), so \\(a = 29,\\; b = 3\\), with a maximum vertex at \\((-3, 29)\\). The sign change on the \\(-9\\) is a frequent slip." }, { stepNumber: 4, description: "Part (b): justify that \\(f\\) is one-to-one.", workingLatex: "x \\ge -3 \\Rightarrow f \\text{ strictly decreasing}", explanation: "The vertex is at \\(x = -3\\), and to its right a downward parabola is strictly decreasing. A strictly monotonic function is one-to-one and so passes the horizontal-line test, guaranteeing an inverse exists." }, { stepNumber: 5, description: "Part (c): write \\(y = f(x)\\) and isolate the square.", workingLatex: "y = 29 - (x + 3)^2 \\Rightarrow (x + 3)^2 = 29 - y", explanation: "Rearranging moves the squared bracket onto its own side; here it equals \\(29 - y\\) rather than \\(y - 29\\) because the parabola opens downward." }, { stepNumber: 6, description: "Take the square root on the correct branch.", workingLatex: "x + 3 = \\sqrt{29 - y}", explanation: "The domain \\(x \\ge -3\\) gives \\(x + 3 \\ge 0\\), so the bracket is non-negative and only the positive root is taken." }, { stepNumber: 7, description: "Subtract 3 and swap variables.", workingLatex: "x = \\sqrt{29 - y} - 3 \\Rightarrow f^{-1}(x) = \\sqrt{29 - x} - 3", explanation: "Subtracting 3 makes \\(x\\) the subject; relabelling \\(y\\) as \\(x\\) gives the inverse in standard form." }, { stepNumber: 8, description: "State the domain and range of \\(f^{-1}\\).", workingLatex: "\\text{domain: } x \\le 29,\\qquad \\text{range: } f^{-1}(x) \\ge -3", explanation: "On \\(x \\ge -3\\), \\(f\\) decreases from its maximum \\(f(-3) = 29\\) towards \\(-\\infty\\), so the range of \\(f\\) is \\(y \\le 29\\), which becomes the domain of \\(f^{-1}\\). The range of \\(f^{-1}\\) equals the domain of \\(f\\), namely \\(f^{-1}(x) \\ge -3\\)." }, { stepNumber: 9, description: "Part (d): substitute \\(x = 4\\) into the inverse.", workingLatex: "f^{-1}(4) = \\sqrt{29 - 4} - 3", explanation: "Since \\(4 \\le 29\\), the input lies in the domain of \\(f^{-1}\\), so the evaluation is valid." }, { stepNumber: 10, description: "Simplify the surd and finish the arithmetic.", workingLatex: "\\sqrt{25} - 3 = 5 - 3 = 2", explanation: "Since \\(29 - 4 = 25\\) is a perfect square, \\(\\sqrt{25} = 5\\) and \\(5 - 3 = 2\\). Check: \\(f(2) = 29 - (2+3)^2 = 4\\)." } ], finalAnswer: "(a) \\( f(x) = 29 - (x + 3)^2 \\). (b) \\( f \\) is strictly decreasing on \\( x \\ge -3 \\), hence one-to-one, so an inverse exists. (c) \\( f^{-1}(x) = \\sqrt{29 - x} - 3 \\), with domain \\( x \\le 29 \\) and range \\( f^{-1}(x) \\ge -3 \\). (d) \\( f^{-1}(4) = 2 \\)." } },
  { id: "y2fg4-020", topicRef: "y2fg4", topicTitle: "Inverse Functions 20", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = x^2 - kx + 12 \\), \\( x \\ge 3 \\), where \\( k \\) is a constant. Given that the graph of \\( y = f(x) \\) has its minimum point at \\( x = 3 \\):  (a) Show that \\( k = 6 \\), and write \\( f(x) \\) in completed-square form.  (b) Find \\( f^{-1}(x) \\), stating its domain and range.  (c) Solve the equation \\( f^{-1}(x) = 7 \\).", marks: 8, examStyle: true, yearCreated: 2026, tags: ["inverse", "complete-the-square", "quadratic", "unknown-coefficient", "domain", "range", "evaluate"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): locate the vertex of the quadratic.", workingLatex: "x_{\\min} = \\tfrac{k}{2}", explanation: "Since the \\(x^2\\) coefficient is positive, \\(x^2 - kx + 12\\) has a minimum at the vertex \\(x = \\tfrac{k}{2}\\), the value where the symmetric quadratic turns." }, { stepNumber: 2, description: "Apply the minimum-point condition to find \\(k\\).", workingLatex: "\\tfrac{k}{2} = 3 \\Rightarrow k = 6", explanation: "The minimum is given as \\(x = 3\\), so equating \\(\\tfrac{k}{2} = 3\\) and multiplying by 2 gives \\(k = 6\\), as required." }, { stepNumber: 3, description: "Substitute \\(k = 6\\) and complete the square.", workingLatex: "f(x) = x^2 - 6x + 12 = (x - 3)^2 + 3", explanation: "Half of \\(-6\\) is \\(-3\\), so \\((x-3)^2 = x^2 - 6x + 9\\); adding 3 recovers \\(+12\\). The vertex \\((3, 3)\\) confirms the minimum at \\(x = 3\\)." }, { stepNumber: 4, description: "Part (b): write \\(y = f(x)\\) and subtract 3.", workingLatex: "y = (x - 3)^2 + 3 \\Rightarrow (x - 3)^2 = y - 3", explanation: "Setting \\(y = f(x)\\) starts the inversion; subtracting 3 isolates the squared bracket ready for rooting." }, { stepNumber: 5, description: "Take the square root on the correct branch.", workingLatex: "x - 3 = \\sqrt{y - 3}", explanation: "The domain \\(x \\ge 3\\) gives \\(x - 3 \\ge 0\\), so the bracket is non-negative and only the positive root is valid." }, { stepNumber: 6, description: "Add 3 and swap variables.", workingLatex: "x = 3 + \\sqrt{y - 3} \\Rightarrow f^{-1}(x) = 3 + \\sqrt{x - 3}", explanation: "Adding 3 makes \\(x\\) the subject; relabelling \\(y\\) as \\(x\\) gives the inverse in standard form." }, { stepNumber: 7, description: "State the domain and range of \\(f^{-1}\\).", workingLatex: "\\text{domain: } x \\ge 3,\\qquad \\text{range: } f^{-1}(x) \\ge 3", explanation: "On \\(x \\ge 3\\), \\(f\\) is strictly increasing with minimum value 3 at the vertex, so the range of \\(f\\) is \\(y \\ge 3\\), which becomes the domain of \\(f^{-1}\\). The range of \\(f^{-1}\\) equals the domain of \\(f\\), namely \\(f^{-1}(x) \\ge 3\\)." }, { stepNumber: 8, description: "Part (c): set up the equation \\(f^{-1}(x) = 7\\).", workingLatex: "3 + \\sqrt{x - 3} = 7", explanation: "Substituting the inverse rule turns the requirement into an equation in \\(x\\) that can be solved by isolating the surd." }, { stepNumber: 9, description: "Isolate the square root.", workingLatex: "\\sqrt{x - 3} = 4", explanation: "Subtracting 3 from both sides leaves the surd alone, so it can be removed cleanly by squaring." }, { stepNumber: 10, description: "Square both sides and solve for \\(x\\).", workingLatex: "x - 3 = 16 \\Rightarrow x = 19", explanation: "Squaring removes the root and adding 3 gives \\(x = 19\\). Check: \\(x = 19 \\ge 3\\) lies in the domain, and \\(f(7) = (7-3)^2 + 3 = 19\\) confirms it." } ], finalAnswer: "(a) \\( k = 6 \\) and \\( f(x) = (x - 3)^2 + 3 \\). (b) \\( f^{-1}(x) = 3 + \\sqrt{x - 3} \\), with domain \\( x \\ge 3 \\) and range \\( f^{-1}(x) \\ge 3 \\). (c) \\( x = 19 \\)." } },
  { id: "y2fg4-021", topicRef: "y2fg4", topicTitle: "Inverse Functions 21", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = 1 - (x - 3)^2 \\), \\( x \\ge 3 \\).  (a) Find \\( f^{-1}(x) \\), stating its domain and range.  (b) Evaluate \\( f^{-1}(-8) \\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["inverse", "quadratic", "complete-the-square", "domain", "range", "evaluate"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): write \\(y = f(x)\\) and isolate the square.", workingLatex: "y = 1 - (x - 3)^2 \\Rightarrow (x - 3)^2 = 1 - y", explanation: "Setting \\(y = f(x)\\) starts the inversion. Because the parabola opens downward, the squared bracket equals \\(1 - y\\) rather than \\(y - 1\\)." }, { stepNumber: 2, description: "Take the square root on the correct branch.", workingLatex: "x - 3 = \\sqrt{1 - y}", explanation: "The domain \\(x \\ge 3\\) gives \\(x - 3 \\ge 0\\), so the bracket is non-negative and only the positive root is taken." }, { stepNumber: 3, description: "Add 3 and swap variables.", workingLatex: "x = 3 + \\sqrt{1 - y} \\Rightarrow f^{-1}(x) = 3 + \\sqrt{1 - x}", explanation: "Adding 3 makes \\(x\\) the subject; relabelling \\(y\\) as \\(x\\) gives the inverse in standard form." }, { stepNumber: 4, description: "State the domain and range of \\(f^{-1}\\).", workingLatex: "\\text{domain: } x \\le 1,\\qquad \\text{range: } f^{-1}(x) \\ge 3", explanation: "This is a downward parabola with maximum vertex \\((3, 1)\\). On \\(x \\ge 3\\), \\(f\\) decreases from \\(f(3) = 1\\) towards \\(-\\infty\\), so the range of \\(f\\) is \\(y \\le 1\\), which becomes the domain of \\(f^{-1}\\). The range of \\(f^{-1}\\) equals the domain of \\(f\\), namely \\(f^{-1}(x) \\ge 3\\)." }, { stepNumber: 5, description: "Part (b): substitute \\(x = -8\\) into the inverse.", workingLatex: "f^{-1}(-8) = 3 + \\sqrt{1 - (-8)}", explanation: "Since \\(-8 \\le 1\\), the input lies in the domain of \\(f^{-1}\\), so the evaluation is valid. Note \\(1 - (-8) = 1 + 8\\)." }, { stepNumber: 6, description: "Simplify the surd and finish the arithmetic.", workingLatex: "3 + \\sqrt{9} = 3 + 3 = 6", explanation: "Since \\(1 - (-8) = 9\\) is a perfect square, \\(\\sqrt{9} = 3\\) and \\(3 + 3 = 6\\). Check: \\(f(6) = 1 - (6-3)^2 = -8\\)." } ], finalAnswer: "(a) \\( f^{-1}(x) = 3 + \\sqrt{1 - x} \\), with domain \\( x \\le 1 \\) and range \\( f^{-1}(x) \\ge 3 \\). (b) \\( f^{-1}(-8) = 6 \\)." } },
  // ── Rational (ax+b)/(cx+d) inverses ────
  { id: "y2fg4-022", topicRef: "y2fg4", topicTitle: "Inverse Functions 22", difficulty: "Foundation", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = \\tfrac{1}{x} \\), \\( x \\ne 0 \\). (a) Find \\( f^{-1}(x) \\), stating its domain and range. (b) Hence explain what is special about the function \\( f \\).", marks: 4, examStyle: false, yearCreated: 2026, tags: ["inverse", "self-inverse", "domain", "range"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): set \\(y = f(x)\\).", workingLatex: "y = \\tfrac{1}{x}", explanation: "The standard way to find an inverse is to write \\(y\\) for the output of \\(f\\), then rearrange to make \\(x\\) the subject." }, { stepNumber: 2, description: "Multiply both sides by \\(x\\).", workingLatex: "xy = 1", explanation: "Clearing the denominator removes the fraction and turns the equation into a simple product. This is valid because \\(x \\ne 0\\)." }, { stepNumber: 3, description: "Divide both sides by \\(y\\) to isolate \\(x\\).", workingLatex: "x = \\tfrac{1}{y}", explanation: "Dividing by \\(y\\) is allowed since \\(f\\) can never output \\(0\\) (a \\(1\\) over any value is never zero), so \\(y \\ne 0\\)." }, { stepNumber: 4, description: "Swap variables to write the inverse.", workingLatex: "f^{-1}(x) = \\tfrac{1}{x}", explanation: "Replacing \\(y\\) with \\(x\\) expresses the inverse as a function of its own input, completing the standard procedure." }, { stepNumber: 5, description: "State the domain and range of the inverse.", workingLatex: "\\text{domain: } x \\ne 0, \\quad \\text{range: } f^{-1}(x) \\ne 0", explanation: "The domain of \\(f^{-1}\\) equals the range of \\(f\\) (all reals except \\(0\\)); the range of \\(f^{-1}\\) equals the domain of \\(f\\) (all reals except \\(0\\)). A common slip is to forget that \\(0\\) is excluded at both ends." }, { stepNumber: 6, description: "Part (b): compare the inverse with the original.", workingLatex: "f^{-1}(x) = \\tfrac{1}{x} = f(x)", explanation: "The inverse has exactly the same rule as \\(f\\), so \\(f\\) is self-inverse: applying it twice returns the original input, and its graph (a hyperbola) is symmetric in the line \\(y = x\\)." } ], finalAnswer: "(a) \\( f^{-1}(x) = \\tfrac{1}{x} \\), domain \\( x \\ne 0 \\), range \\( f^{-1}(x) \\ne 0 \\). (b) \\( f^{-1} = f \\), so \\( f \\) is self-inverse." } },
  { id: "y2fg4-023", topicRef: "y2fg4", topicTitle: "Inverse Functions 23", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = \\tfrac{3x + 2}{x - 4} \\), \\( x \\ne 4 \\). (a) Find \\( f^{-1}(x) \\), stating its domain and range. (b) Evaluate \\( f^{-1}(5) \\). (c) Solve the equation \\( f(x) = f^{-1}(x) \\).", marks: 8, examStyle: true, yearCreated: 2026, tags: ["inverse", "rational", "domain", "range", "evaluate"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): set \\(y = f(x)\\).", workingLatex: "y = \\tfrac{3x + 2}{x - 4}", explanation: "Write \\(y\\) for the output of \\(f\\); the goal is to rearrange this equation to make \\(x\\) the subject." }, { stepNumber: 2, description: "Cross-multiply to clear the fraction.", workingLatex: "y(x - 4) = 3x + 2", explanation: "Multiplying both sides by \\(x - 4\\) removes the denominator. This is valid because \\(x \\ne 4\\)." }, { stepNumber: 3, description: "Expand the bracket on the left.", workingLatex: "yx - 4y = 3x + 2", explanation: "Distribute \\(y\\) across \\(x - 4\\) so that every term is written out and the \\(x\\)-terms can be collected next." }, { stepNumber: 4, description: "Gather all \\(x\\)-terms on one side.", workingLatex: "yx - 3x = 4y + 2", explanation: "Move the \\(3x\\) term left and the \\(-4y\\) term right so that every term containing \\(x\\) is together — the essential step for isolating \\(x\\)." }, { stepNumber: 5, description: "Factor out \\(x\\).", workingLatex: "x(y - 3) = 4y + 2", explanation: "Taking \\(x\\) outside a bracket collects it into a single factor, ready to divide." }, { stepNumber: 6, description: "Divide to make \\(x\\) the subject.", workingLatex: "x = \\tfrac{4y + 2}{y - 3}", explanation: "Dividing both sides by \\(y - 3\\) isolates \\(x\\) completely." }, { stepNumber: 7, description: "Swap variables to write the inverse.", workingLatex: "f^{-1}(x) = \\tfrac{4x + 2}{x - 3}", explanation: "Replace \\(y\\) with \\(x\\) so the inverse is expressed as a function of its own input." }, { stepNumber: 8, description: "State the domain and range of the inverse.", workingLatex: "x \\ne 3, \\quad f^{-1}(x) \\ne 4", explanation: "The horizontal asymptote of \\(f\\) is \\(y = 3\\) (ratio of leading coefficients \\(3/1\\)), so the range of \\(f\\) excludes \\(3\\); hence the domain of \\(f^{-1}\\) is \\(x \\ne 3\\). The range of \\(f^{-1}\\) excludes \\(4\\), the value barred from the domain of \\(f\\)." }, { stepNumber: 9, description: "Part (b): substitute \\(x = 5\\) into \\(f^{-1}\\).", workingLatex: "f^{-1}(5) = \\tfrac{4(5) + 2}{5 - 3} = \\tfrac{22}{2} = 11", explanation: "Putting \\(x = 5\\) into the inverse rule gives the required value." }, { stepNumber: 10, description: "Verify the evaluation by substituting back.", workingLatex: "f(11) = \\tfrac{3(11) + 2}{11 - 4} = \\tfrac{35}{7} = 5", explanation: "Since \\(f(11) = 5\\), the result \\(f^{-1}(5) = 11\\) is confirmed." }, { stepNumber: 11, description: "Part (c): replace \\(f^{-1}(x)\\) with \\(x\\) and clear the fraction.", workingLatex: "\\tfrac{3x + 2}{x - 4} = x \\;\\Rightarrow\\; 3x + 2 = x(x - 4)", explanation: "Any point fixed by \\(f\\) lies on the line \\(y = x\\) and is therefore also fixed by \\(f^{-1}\\), so solving \\(f(x) = x\\) captures every solution of \\(f(x) = f^{-1}(x)\\)." }, { stepNumber: 12, description: "Expand and rearrange to a quadratic.", workingLatex: "3x + 2 = x^2 - 4x \\;\\Rightarrow\\; x^2 - 7x - 2 = 0", explanation: "Multiply out the right side, then move all terms to one side so the equation equals zero." }, { stepNumber: 13, description: "Apply the quadratic formula.", workingLatex: "x = \\tfrac{7 \\pm \\sqrt{(-7)^2 - 4(1)(-2)}}{2} = \\tfrac{7 \\pm \\sqrt{57}}{2}", explanation: "The quadratic does not factorise, so use the formula; the discriminant \\(49 + 8 = 57\\) is positive, giving two distinct real solutions." } ], finalAnswer: "(a) \\( f^{-1}(x) = \\tfrac{4x + 2}{x - 3} \\), domain \\( x \\ne 3 \\), range \\( f^{-1}(x) \\ne 4 \\). (b) \\( f^{-1}(5) = 11 \\). (c) \\( x = \\tfrac{7 \\pm \\sqrt{57}}{2} \\)." } },
  { id: "y2fg4-024", topicRef: "y2fg4", topicTitle: "Inverse Functions 24", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = \\tfrac{ax + 1}{x - 2} \\), \\( x \\ne 2 \\), where \\( a \\) is a constant. Given that \\( f^{-1}(3) = 7 \\): (a) show that \\( a = 2 \\). (b) Find \\( f^{-1}(x) \\), stating its domain and range. (c) Evaluate \\( f^{-1}(0) \\).", marks: 8, examStyle: true, yearCreated: 2026, tags: ["inverse", "rational", "domain", "range", "evaluate", "unknown-constant"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): re-express the inverse condition.", workingLatex: "f^{-1}(3) = 7 \\;\\Longleftrightarrow\\; f(7) = 3", explanation: "The statement \\(f^{-1}(3) = 7\\) means \\(f\\) maps \\(7\\) to \\(3\\); rewriting it in terms of \\(f\\) gives an equation we can solve for \\(a\\)." }, { stepNumber: 2, description: "Substitute \\(x = 7\\) into \\(f\\) and set equal to \\(3\\).", workingLatex: "\\tfrac{a(7) + 1}{7 - 2} = 3 \\;\\Rightarrow\\; \\tfrac{7a + 1}{5} = 3", explanation: "Use the defining rule of \\(f\\) with \\(x = 7\\) and simplify the denominator \\(7 - 2 = 5\\)." }, { stepNumber: 3, description: "Multiply both sides by \\(5\\).", workingLatex: "7a + 1 = 15", explanation: "Clearing the denominator turns the equation into a simple linear equation in \\(a\\)." }, { stepNumber: 4, description: "Solve the linear equation for \\(a\\).", workingLatex: "7a = 14 \\;\\Rightarrow\\; a = 2", explanation: "Subtract \\(1\\) then divide by \\(7\\); this gives \\(a = 2\\) as required." }, { stepNumber: 5, description: "Part (b): substitute \\(a = 2\\) and set \\(y = f(x)\\).", workingLatex: "y = \\tfrac{2x + 1}{x - 2}", explanation: "With \\(a\\) now known, write \\(y\\) for the output so the equation can be rearranged for \\(x\\)." }, { stepNumber: 6, description: "Cross-multiply to clear the fraction.", workingLatex: "y(x - 2) = 2x + 1", explanation: "Multiplying both sides by \\(x - 2\\) removes the denominator. This is valid because \\(x \\ne 2\\)." }, { stepNumber: 7, description: "Expand and gather all \\(x\\)-terms.", workingLatex: "yx - 2y = 2x + 1 \\;\\Rightarrow\\; yx - 2x = 2y + 1", explanation: "Distribute \\(y\\), then move the \\(2x\\) term left and the constant right so every \\(x\\)-term is together." }, { stepNumber: 8, description: "Factor out \\(x\\) and divide.", workingLatex: "x(y - 2) = 2y + 1 \\;\\Rightarrow\\; x = \\tfrac{2y + 1}{y - 2}", explanation: "Take \\(x\\) outside a bracket, then divide both sides by \\(y - 2\\) to isolate \\(x\\)." }, { stepNumber: 9, description: "Swap variables and state the domain and range.", workingLatex: "f^{-1}(x) = \\tfrac{2x + 1}{x - 2}, \\quad x \\ne 2, \\quad f^{-1}(x) \\ne 2", explanation: "The horizontal asymptote of \\(f\\) is \\(y = 2\\), so the range of \\(f\\) excludes \\(2\\) and the domain of \\(f^{-1}\\) is \\(x \\ne 2\\). The range of \\(f^{-1}\\) excludes \\(2\\), the value barred from the domain of \\(f\\). Note \\(f\\) happens to be self-inverse here." }, { stepNumber: 10, description: "Part (c): substitute \\(x = 0\\) into \\(f^{-1}\\).", workingLatex: "f^{-1}(0) = \\tfrac{2(0) + 1}{0 - 2} = \\tfrac{1}{-2} = -\\tfrac{1}{2}", explanation: "Putting \\(x = 0\\) into the inverse rule gives the required value." }, { stepNumber: 11, description: "Verify the evaluation by substituting back.", workingLatex: "f\\!\\left(-\\tfrac{1}{2}\\right) = \\tfrac{2(-\\frac{1}{2}) + 1}{-\\frac{1}{2} - 2} = \\tfrac{0}{-5/2} = 0", explanation: "Since \\(f(-\\tfrac{1}{2}) = 0\\), the result \\(f^{-1}(0) = -\\tfrac{1}{2}\\) is confirmed." } ], finalAnswer: "(a) \\( a = 2 \\) (shown). (b) \\( f^{-1}(x) = \\tfrac{2x + 1}{x - 2} \\), domain \\( x \\ne 2 \\), range \\( f^{-1}(x) \\ne 2 \\). (c) \\( f^{-1}(0) = -\\tfrac{1}{2} \\)." } },
  { id: "y2fg4-025", topicRef: "y2fg4", topicTitle: "Inverse Functions 25", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = \\tfrac{x + 1}{x - 2} \\), \\( x \\ne 2 \\). (a) Find \\( f^{-1}(x) \\), stating its domain and range. (b) Evaluate \\( f^{-1}(3) \\). (c) Evaluate \\( f^{-1}(-1) \\).", marks: 7, examStyle: true, yearCreated: 2026, tags: ["inverse", "rational", "domain", "range", "evaluate"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): set \\(y = f(x)\\).", workingLatex: "y = \\tfrac{x + 1}{x - 2}", explanation: "Write \\(y\\) for the output of \\(f\\) so the equation can be rearranged to make \\(x\\) the subject." }, { stepNumber: 2, description: "Cross-multiply to clear the fraction.", workingLatex: "y(x - 2) = x + 1", explanation: "Multiplying both sides by \\(x - 2\\) removes the denominator. This is valid because \\(x \\ne 2\\)." }, { stepNumber: 3, description: "Expand the bracket on the left.", workingLatex: "yx - 2y = x + 1", explanation: "Distribute \\(y\\) across \\(x - 2\\) so the \\(x\\)-terms can be collected." }, { stepNumber: 4, description: "Gather all \\(x\\)-terms on one side.", workingLatex: "yx - x = 2y + 1", explanation: "Subtract \\(x\\) from both sides and add \\(2y\\) so every term containing \\(x\\) is on the left." }, { stepNumber: 5, description: "Factor out \\(x\\).", workingLatex: "x(y - 1) = 2y + 1", explanation: "Taking \\(x\\) outside a bracket collects it into a single factor, ready to divide." }, { stepNumber: 6, description: "Divide and swap variables.", workingLatex: "x = \\tfrac{2y + 1}{y - 1} \\;\\Rightarrow\\; f^{-1}(x) = \\tfrac{2x + 1}{x - 1}", explanation: "Divide by \\(y - 1\\) to isolate \\(x\\), then replace \\(y\\) with \\(x\\) to obtain the inverse rule." }, { stepNumber: 7, description: "State the domain and range.", workingLatex: "x \\ne 1, \\quad f^{-1}(x) \\ne 2", explanation: "The horizontal asymptote of \\(f\\) is \\(y = 1\\), so the range of \\(f\\) excludes \\(1\\) and the domain of \\(f^{-1}\\) is \\(x \\ne 1\\). The range of \\(f^{-1}\\) excludes \\(2\\), the value barred from the domain of \\(f\\)." }, { stepNumber: 8, description: "Part (b): substitute \\(x = 3\\) into \\(f^{-1}\\).", workingLatex: "f^{-1}(3) = \\tfrac{2(3) + 1}{3 - 1} = \\tfrac{7}{2}", explanation: "Putting \\(x = 3\\) into the inverse rule gives the required value." }, { stepNumber: 9, description: "Verify part (b) by substituting back.", workingLatex: "f\\!\\left(\\tfrac{7}{2}\\right) = \\tfrac{7/2 + 1}{7/2 - 2} = \\tfrac{9/2}{3/2} = 3", explanation: "Since \\(f(\\tfrac{7}{2}) = 3\\), the result \\(f^{-1}(3) = \\tfrac{7}{2}\\) is confirmed." }, { stepNumber: 10, description: "Part (c): substitute \\(x = -1\\) into \\(f^{-1}\\).", workingLatex: "f^{-1}(-1) = \\tfrac{2(-1) + 1}{-1 - 1} = \\tfrac{-1}{-2} = \\tfrac{1}{2}", explanation: "Putting \\(x = -1\\) into the inverse rule gives the required value; two negatives divide to a positive." }, { stepNumber: 11, description: "Verify part (c) by substituting back.", workingLatex: "f\\!\\left(\\tfrac{1}{2}\\right) = \\tfrac{1/2 + 1}{1/2 - 2} = \\tfrac{3/2}{-3/2} = -1", explanation: "Since \\(f(\\tfrac{1}{2}) = -1\\), the result \\(f^{-1}(-1) = \\tfrac{1}{2}\\) is confirmed." } ], finalAnswer: "(a) \\( f^{-1}(x) = \\tfrac{2x + 1}{x - 1} \\), domain \\( x \\ne 1 \\), range \\( f^{-1}(x) \\ne 2 \\). (b) \\( f^{-1}(3) = \\tfrac{7}{2} \\). (c) \\( f^{-1}(-1) = \\tfrac{1}{2} \\)." } },
  { id: "y2fg4-026", topicRef: "y2fg4", topicTitle: "Inverse Functions 26", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = \\tfrac{3x}{x - 1} \\), \\( x \\ne 1 \\). (a) Find \\( f^{-1}(x) \\), stating its domain and range. (b) Evaluate \\( f^{-1}(6) \\). (c) Evaluate \\( f^{-1}(2) \\).", marks: 7, examStyle: true, yearCreated: 2026, tags: ["inverse", "rational", "domain", "range", "evaluate"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): set \\(y = f(x)\\).", workingLatex: "y = \\tfrac{3x}{x - 1}", explanation: "Write \\(y\\) for the output of \\(f\\) so the equation can be rearranged to make \\(x\\) the subject." }, { stepNumber: 2, description: "Cross-multiply to clear the fraction.", workingLatex: "y(x - 1) = 3x", explanation: "Multiplying both sides by \\(x - 1\\) removes the denominator. This is valid because \\(x \\ne 1\\)." }, { stepNumber: 3, description: "Expand the bracket on the left.", workingLatex: "yx - y = 3x", explanation: "Distribute \\(y\\) across \\(x - 1\\) so the \\(x\\)-terms can be collected." }, { stepNumber: 4, description: "Gather all \\(x\\)-terms on one side.", workingLatex: "yx - 3x = y", explanation: "Move the \\(3x\\) term to the left so every term containing \\(x\\) is together, leaving the lone \\(y\\) on the right." }, { stepNumber: 5, description: "Factor out \\(x\\).", workingLatex: "x(y - 3) = y", explanation: "Taking \\(x\\) outside a bracket collects it into a single factor, ready to divide." }, { stepNumber: 6, description: "Divide and swap variables.", workingLatex: "x = \\tfrac{y}{y - 3} \\;\\Rightarrow\\; f^{-1}(x) = \\tfrac{x}{x - 3}", explanation: "Divide by \\(y - 3\\) to isolate \\(x\\), then replace \\(y\\) with \\(x\\) to obtain the inverse rule." }, { stepNumber: 7, description: "State the domain and range.", workingLatex: "x \\ne 3, \\quad f^{-1}(x) \\ne 1", explanation: "The horizontal asymptote of \\(f\\) is \\(y = 3\\) (ratio of leading coefficients), so the range of \\(f\\) excludes \\(3\\) and the domain of \\(f^{-1}\\) is \\(x \\ne 3\\). The range of \\(f^{-1}\\) excludes \\(1\\), the value barred from the domain of \\(f\\)." }, { stepNumber: 8, description: "Part (b): substitute \\(x = 6\\) into \\(f^{-1}\\).", workingLatex: "f^{-1}(6) = \\tfrac{6}{6 - 3} = \\tfrac{6}{3} = 2", explanation: "Putting \\(x = 6\\) into the inverse rule gives the required value." }, { stepNumber: 9, description: "Verify part (b) by substituting back.", workingLatex: "f(2) = \\tfrac{3(2)}{2 - 1} = \\tfrac{6}{1} = 6", explanation: "Since \\(f(2) = 6\\), the result \\(f^{-1}(6) = 2\\) is confirmed." }, { stepNumber: 10, description: "Part (c): substitute \\(x = 2\\) into \\(f^{-1}\\).", workingLatex: "f^{-1}(2) = \\tfrac{2}{2 - 3} = \\tfrac{2}{-1} = -2", explanation: "Putting \\(x = 2\\) into the inverse rule gives the required value." }, { stepNumber: 11, description: "Verify part (c) by substituting back.", workingLatex: "f(-2) = \\tfrac{3(-2)}{-2 - 1} = \\tfrac{-6}{-3} = 2", explanation: "Since \\(f(-2) = 2\\), the result \\(f^{-1}(2) = -2\\) is confirmed." } ], finalAnswer: "(a) \\( f^{-1}(x) = \\tfrac{x}{x - 3} \\), domain \\( x \\ne 3 \\), range \\( f^{-1}(x) \\ne 1 \\). (b) \\( f^{-1}(6) = 2 \\). (c) \\( f^{-1}(2) = -2 \\)." } },
  { id: "y2fg4-027", topicRef: "y2fg4", topicTitle: "Inverse Functions 27", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = \\tfrac{2x - 1}{x + 3} \\), \\( x \\ne -3 \\). (a) Find \\( f^{-1}(x) \\), stating its domain and range. (b) Evaluate \\( f^{-1}(1) \\). (c) Evaluate \\( f^{-1}(0) \\).", marks: 7, examStyle: true, yearCreated: 2026, tags: ["inverse", "rational", "domain", "range", "evaluate"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): set \\(y = f(x)\\).", workingLatex: "y = \\tfrac{2x - 1}{x + 3}", explanation: "Write \\(y\\) for the output of \\(f\\) so the equation can be rearranged to make \\(x\\) the subject." }, { stepNumber: 2, description: "Cross-multiply to clear the fraction.", workingLatex: "y(x + 3) = 2x - 1", explanation: "Multiplying both sides by \\(x + 3\\) removes the denominator. This is valid because \\(x \\ne -3\\)." }, { stepNumber: 3, description: "Expand the bracket on the left.", workingLatex: "yx + 3y = 2x - 1", explanation: "Distribute \\(y\\) across \\(x + 3\\) so the \\(x\\)-terms can be collected." }, { stepNumber: 4, description: "Gather \\(x\\)-terms on one side, constants on the other.", workingLatex: "yx - 2x = -1 - 3y", explanation: "Move the \\(2x\\) term left and the \\(3y\\) term right so every term containing \\(x\\) is together." }, { stepNumber: 5, description: "Factor out \\(x\\).", workingLatex: "x(y - 2) = -(3y + 1)", explanation: "Take \\(x\\) outside a bracket; the right side is written as a single negated bracket ready for the sign tidy-up." }, { stepNumber: 6, description: "Divide, then flip signs for a tidier form.", workingLatex: "x = \\tfrac{-(3y + 1)}{y - 2} = \\tfrac{3y + 1}{2 - y}", explanation: "Divide by \\(y - 2\\); multiplying numerator and denominator by \\(-1\\) removes the leading minus sign without changing the value." }, { stepNumber: 7, description: "Swap variables to write the inverse.", workingLatex: "f^{-1}(x) = \\tfrac{3x + 1}{2 - x}", explanation: "Replace \\(y\\) with \\(x\\) so the inverse is expressed as a function of its own input." }, { stepNumber: 8, description: "State the domain and range.", workingLatex: "x \\ne 2, \\quad f^{-1}(x) \\ne -3", explanation: "The horizontal asymptote of \\(f\\) is \\(y = 2\\), so the range of \\(f\\) excludes \\(2\\) and the domain of \\(f^{-1}\\) is \\(x \\ne 2\\). The range of \\(f^{-1}\\) excludes \\(-3\\), the value barred from the domain of \\(f\\)." }, { stepNumber: 9, description: "Part (b): substitute \\(x = 1\\) into \\(f^{-1}\\).", workingLatex: "f^{-1}(1) = \\tfrac{3(1) + 1}{2 - 1} = \\tfrac{4}{1} = 4", explanation: "Putting \\(x = 1\\) into the inverse rule gives the required value." }, { stepNumber: 10, description: "Verify part (b) by substituting back.", workingLatex: "f(4) = \\tfrac{2(4) - 1}{4 + 3} = \\tfrac{7}{7} = 1", explanation: "Since \\(f(4) = 1\\), the result \\(f^{-1}(1) = 4\\) is confirmed." }, { stepNumber: 11, description: "Part (c): substitute \\(x = 0\\) into \\(f^{-1}\\).", workingLatex: "f^{-1}(0) = \\tfrac{3(0) + 1}{2 - 0} = \\tfrac{1}{2}", explanation: "Putting \\(x = 0\\) into the inverse rule gives the required value." }, { stepNumber: 12, description: "Verify part (c) by substituting back.", workingLatex: "f\\!\\left(\\tfrac{1}{2}\\right) = \\tfrac{2(1/2) - 1}{1/2 + 3} = \\tfrac{0}{7/2} = 0", explanation: "Since \\(f(\\tfrac{1}{2}) = 0\\), the result \\(f^{-1}(0) = \\tfrac{1}{2}\\) is confirmed." } ], finalAnswer: "(a) \\( f^{-1}(x) = \\tfrac{3x + 1}{2 - x} \\), domain \\( x \\ne 2 \\), range \\( f^{-1}(x) \\ne -3 \\). (b) \\( f^{-1}(1) = 4 \\). (c) \\( f^{-1}(0) = \\tfrac{1}{2} \\)." } },
  { id: "y2fg4-028", topicRef: "y2fg4", topicTitle: "Inverse Functions 28", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = \\tfrac{x}{x + 2} \\), \\( x \\ne -2 \\). (a) Find \\( f^{-1}(x) \\), stating its domain and range. (b) Evaluate \\( f^{-1}\\!\\left(\\tfrac{1}{3}\\right) \\). (c) Evaluate \\( f^{-1}(2) \\).", marks: 7, examStyle: true, yearCreated: 2026, tags: ["inverse", "rational", "domain", "range", "evaluate"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): set \\(y = f(x)\\).", workingLatex: "y = \\tfrac{x}{x + 2}", explanation: "Write \\(y\\) for the output of \\(f\\) so the equation can be rearranged to make \\(x\\) the subject." }, { stepNumber: 2, description: "Cross-multiply to clear the fraction.", workingLatex: "y(x + 2) = x", explanation: "Multiplying both sides by \\(x + 2\\) removes the denominator. This is valid because \\(x \\ne -2\\)." }, { stepNumber: 3, description: "Expand the bracket on the left.", workingLatex: "yx + 2y = x", explanation: "Distribute \\(y\\) across \\(x + 2\\) so the \\(x\\)-terms can be collected." }, { stepNumber: 4, description: "Gather all \\(x\\)-terms on one side.", workingLatex: "yx - x = -2y", explanation: "Subtract \\(x\\) and \\(2y\\) from both sides so every term containing \\(x\\) is on the left." }, { stepNumber: 5, description: "Factor out \\(x\\).", workingLatex: "x(y - 1) = -2y", explanation: "Taking \\(x\\) outside a bracket collects it into a single factor, ready to divide." }, { stepNumber: 6, description: "Divide, then flip signs for a tidier form.", workingLatex: "x = \\tfrac{-2y}{y - 1} = \\tfrac{2y}{1 - y}", explanation: "Divide by \\(y - 1\\); multiplying numerator and denominator by \\(-1\\) removes the leading minus sign without changing the value." }, { stepNumber: 7, description: "Swap variables to write the inverse.", workingLatex: "f^{-1}(x) = \\tfrac{2x}{1 - x}", explanation: "Replace \\(y\\) with \\(x\\) so the inverse is expressed as a function of its own input." }, { stepNumber: 8, description: "State the domain and range.", workingLatex: "x \\ne 1, \\quad f^{-1}(x) \\ne -2", explanation: "The horizontal asymptote of \\(f\\) is \\(y = 1\\), so the range of \\(f\\) excludes \\(1\\) and the domain of \\(f^{-1}\\) is \\(x \\ne 1\\). The range of \\(f^{-1}\\) excludes \\(-2\\), the value barred from the domain of \\(f\\)." }, { stepNumber: 9, description: "Part (b): substitute \\(x = \\tfrac{1}{3}\\) into \\(f^{-1}\\).", workingLatex: "f^{-1}\\!\\left(\\tfrac{1}{3}\\right) = \\tfrac{2 \\cdot \\frac{1}{3}}{1 - \\frac{1}{3}} = \\tfrac{2/3}{2/3} = 1", explanation: "Putting \\(x = \\tfrac{1}{3}\\) into the inverse rule: numerator and denominator are both \\(\\tfrac{2}{3}\\), so the value is \\(1\\)." }, { stepNumber: 10, description: "Verify part (b) by substituting back.", workingLatex: "f(1) = \\tfrac{1}{1 + 2} = \\tfrac{1}{3}", explanation: "Since \\(f(1) = \\tfrac{1}{3}\\), the result \\(f^{-1}(\\tfrac{1}{3}) = 1\\) is confirmed." }, { stepNumber: 11, description: "Part (c): substitute \\(x = 2\\) into \\(f^{-1}\\).", workingLatex: "f^{-1}(2) = \\tfrac{2(2)}{1 - 2} = \\tfrac{4}{-1} = -4", explanation: "Putting \\(x = 2\\) into the inverse rule gives the required value." }, { stepNumber: 12, description: "Verify part (c) by substituting back.", workingLatex: "f(-4) = \\tfrac{-4}{-4 + 2} = \\tfrac{-4}{-2} = 2", explanation: "Since \\(f(-4) = 2\\), the result \\(f^{-1}(2) = -4\\) is confirmed." } ], finalAnswer: "(a) \\( f^{-1}(x) = \\tfrac{2x}{1 - x} \\), domain \\( x \\ne 1 \\), range \\( f^{-1}(x) \\ne -2 \\). (b) \\( f^{-1}\\!\\left(\\tfrac{1}{3}\\right) = 1 \\). (c) \\( f^{-1}(2) = -4 \\)." } },
  { id: "y2fg4-029", topicRef: "y2fg4", topicTitle: "Inverse Functions 29", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = \\tfrac{5 - x}{x} \\), \\( x \\ne 0 \\). (a) Find \\( f^{-1}(x) \\), stating its domain and range. (b) Evaluate \\( f^{-1}(4) \\). (c) Evaluate \\( f^{-1}(0) \\).", marks: 7, examStyle: true, yearCreated: 2026, tags: ["inverse", "rational", "domain", "range", "evaluate"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): set \\(y = f(x)\\).", workingLatex: "y = \\tfrac{5 - x}{x}", explanation: "Write \\(y\\) for the output of \\(f\\) so the equation can be rearranged to make \\(x\\) the subject." }, { stepNumber: 2, description: "Multiply both sides by \\(x\\).", workingLatex: "yx = 5 - x", explanation: "Clearing the single denominator \\(x\\) removes the fraction. This is valid because \\(x \\ne 0\\)." }, { stepNumber: 3, description: "Gather all \\(x\\)-terms on one side.", workingLatex: "yx + x = 5", explanation: "Add \\(x\\) to both sides so every term containing \\(x\\) is on the left, leaving the constant on the right." }, { stepNumber: 4, description: "Factor out \\(x\\).", workingLatex: "x(y + 1) = 5", explanation: "Taking \\(x\\) outside a bracket collects it into a single factor, ready to divide." }, { stepNumber: 5, description: "Divide and swap variables.", workingLatex: "x = \\tfrac{5}{y + 1} \\;\\Rightarrow\\; f^{-1}(x) = \\tfrac{5}{x + 1}", explanation: "Divide by \\(y + 1\\) to isolate \\(x\\), then replace \\(y\\) with \\(x\\) to obtain the inverse rule." }, { stepNumber: 6, description: "State the domain and range.", workingLatex: "x \\ne -1, \\quad f^{-1}(x) \\ne 0", explanation: "Rewriting \\(f(x) = \\tfrac{5}{x} - 1\\) shows the horizontal asymptote of \\(f\\) is \\(y = -1\\), so the range of \\(f\\) excludes \\(-1\\) and the domain of \\(f^{-1}\\) is \\(x \\ne -1\\). The range of \\(f^{-1}\\) excludes \\(0\\), the value barred from the domain of \\(f\\)." }, { stepNumber: 7, description: "Part (b): substitute \\(x = 4\\) into \\(f^{-1}\\).", workingLatex: "f^{-1}(4) = \\tfrac{5}{4 + 1} = \\tfrac{5}{5} = 1", explanation: "Putting \\(x = 4\\) into the inverse rule gives the required value." }, { stepNumber: 8, description: "Verify part (b) by substituting back.", workingLatex: "f(1) = \\tfrac{5 - 1}{1} = 4", explanation: "Since \\(f(1) = 4\\), the result \\(f^{-1}(4) = 1\\) is confirmed." }, { stepNumber: 9, description: "Part (c): substitute \\(x = 0\\) into \\(f^{-1}\\).", workingLatex: "f^{-1}(0) = \\tfrac{5}{0 + 1} = 5", explanation: "Putting \\(x = 0\\) into the inverse rule gives the required value; \\(0\\) is in the domain of \\(f^{-1}\\) (only \\(-1\\) is barred)." }, { stepNumber: 10, description: "Verify part (c) by substituting back.", workingLatex: "f(5) = \\tfrac{5 - 5}{5} = \\tfrac{0}{5} = 0", explanation: "Since \\(f(5) = 0\\), the result \\(f^{-1}(0) = 5\\) is confirmed." } ], finalAnswer: "(a) \\( f^{-1}(x) = \\tfrac{5}{x + 1} \\), domain \\( x \\ne -1 \\), range \\( f^{-1}(x) \\ne 0 \\). (b) \\( f^{-1}(4) = 1 \\). (c) \\( f^{-1}(0) = 5 \\)." } },
  { id: "y2fg4-030", topicRef: "y2fg4", topicTitle: "Inverse Functions 30", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = \\tfrac{4x + 5}{x - 2} \\), \\( x \\ne 2 \\). (a) Find \\( f^{-1}(x) \\), stating its domain and range. (b) Evaluate \\( f^{-1}(9) \\). (c) Evaluate \\( f^{-1}(5) \\).", marks: 7, examStyle: true, yearCreated: 2026, tags: ["inverse", "rational", "domain", "range", "evaluate"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): set \\(y = f(x)\\).", workingLatex: "y = \\tfrac{4x + 5}{x - 2}", explanation: "Write \\(y\\) for the output of \\(f\\) so the equation can be rearranged to make \\(x\\) the subject." }, { stepNumber: 2, description: "Cross-multiply to clear the fraction.", workingLatex: "y(x - 2) = 4x + 5", explanation: "Multiplying both sides by \\(x - 2\\) removes the denominator. This is valid because \\(x \\ne 2\\)." }, { stepNumber: 3, description: "Expand the bracket on the left.", workingLatex: "yx - 2y = 4x + 5", explanation: "Distribute \\(y\\) across \\(x - 2\\) so the \\(x\\)-terms can be collected." }, { stepNumber: 4, description: "Gather all \\(x\\)-terms on one side.", workingLatex: "yx - 4x = 2y + 5", explanation: "Move the \\(4x\\) term left and the \\(-2y\\) term right so every term containing \\(x\\) is together." }, { stepNumber: 5, description: "Factor out \\(x\\).", workingLatex: "x(y - 4) = 2y + 5", explanation: "Taking \\(x\\) outside a bracket collects it into a single factor, ready to divide." }, { stepNumber: 6, description: "Divide and swap variables.", workingLatex: "x = \\tfrac{2y + 5}{y - 4} \\;\\Rightarrow\\; f^{-1}(x) = \\tfrac{2x + 5}{x - 4}", explanation: "Divide by \\(y - 4\\) to isolate \\(x\\), then replace \\(y\\) with \\(x\\) to obtain the inverse rule." }, { stepNumber: 7, description: "State the domain and range.", workingLatex: "x \\ne 4, \\quad f^{-1}(x) \\ne 2", explanation: "The horizontal asymptote of \\(f\\) is \\(y = 4\\) (ratio of leading coefficients \\(4/1\\)), so the range of \\(f\\) excludes \\(4\\) and the domain of \\(f^{-1}\\) is \\(x \\ne 4\\). The range of \\(f^{-1}\\) excludes \\(2\\), the value barred from the domain of \\(f\\)." }, { stepNumber: 8, description: "Part (b): substitute \\(x = 9\\) into \\(f^{-1}\\).", workingLatex: "f^{-1}(9) = \\tfrac{2(9) + 5}{9 - 4} = \\tfrac{23}{5}", explanation: "Putting \\(x = 9\\) into the inverse rule gives the required value." }, { stepNumber: 9, description: "Verify part (b) by substituting back.", workingLatex: "f\\!\\left(\\tfrac{23}{5}\\right) = \\tfrac{4(23/5) + 5}{23/5 - 2} = \\tfrac{117/5}{13/5} = 9", explanation: "Since \\(f(\\tfrac{23}{5}) = 9\\), the result \\(f^{-1}(9) = \\tfrac{23}{5}\\) is confirmed." }, { stepNumber: 10, description: "Part (c): substitute \\(x = 5\\) into \\(f^{-1}\\).", workingLatex: "f^{-1}(5) = \\tfrac{2(5) + 5}{5 - 4} = \\tfrac{15}{1} = 15", explanation: "Putting \\(x = 5\\) into the inverse rule gives the required value." }, { stepNumber: 11, description: "Verify part (c) by substituting back.", workingLatex: "f(15) = \\tfrac{4(15) + 5}{15 - 2} = \\tfrac{65}{13} = 5", explanation: "Since \\(f(15) = 5\\), the result \\(f^{-1}(5) = 15\\) is confirmed." } ], finalAnswer: "(a) \\( f^{-1}(x) = \\tfrac{2x + 5}{x - 4} \\), domain \\( x \\ne 4 \\), range \\( f^{-1}(x) \\ne 2 \\). (b) \\( f^{-1}(9) = \\tfrac{23}{5} \\). (c) \\( f^{-1}(5) = 15 \\)." } },
  { id: "y2fg4-031", topicRef: "y2fg4", topicTitle: "Inverse Functions 31", difficulty: "Challenge", answerType: "expression", questionText: "The functions \\( f \\) and \\( g \\) are defined by \\( f(x) = \\tfrac{3}{2x - 1} \\), \\( x \\ne \\tfrac{1}{2} \\), and \\( g(x) = x + 1 \\). (a) Find \\( f^{-1}(x) \\), stating its domain and range. (b) Evaluate \\( f^{-1}(3) \\). (c) Solve the equation \\( f^{-1}(x) = g(x) \\).", marks: 8, examStyle: true, yearCreated: 2026, tags: ["inverse", "rational", "domain", "range", "evaluate", "composite"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): set \\(y = f(x)\\).", workingLatex: "y = \\tfrac{3}{2x - 1}", explanation: "Write \\(y\\) for the output of \\(f\\) so the equation can be rearranged to make \\(x\\) the subject." }, { stepNumber: 2, description: "Cross-multiply to clear the fraction.", workingLatex: "y(2x - 1) = 3", explanation: "Multiplying both sides by \\(2x - 1\\) removes the denominator. This is valid because \\(x \\ne \\tfrac{1}{2}\\)." }, { stepNumber: 3, description: "Divide by \\(y\\) to isolate \\(2x - 1\\).", workingLatex: "2x - 1 = \\tfrac{3}{y}", explanation: "Dividing by \\(y\\) is allowed because \\(f\\) never outputs \\(0\\) (a \\(3\\) over any value is never zero), so \\(y \\ne 0\\)." }, { stepNumber: 4, description: "Add 1 and combine over a common denominator.", workingLatex: "2x = \\tfrac{3}{y} + 1 = \\tfrac{3 + y}{y}", explanation: "Add \\(1\\) to both sides and write the right side as a single fraction so the next division is clean." }, { stepNumber: 5, description: "Divide by 2 and swap variables.", workingLatex: "x = \\tfrac{3 + y}{2y} \\;\\Rightarrow\\; f^{-1}(x) = \\tfrac{x + 3}{2x}", explanation: "Divide both sides by \\(2\\) to isolate \\(x\\), then replace \\(y\\) with \\(x\\) to obtain the inverse rule." }, { stepNumber: 6, description: "State the domain and range.", workingLatex: "x \\ne 0, \\quad f^{-1}(x) \\ne \\tfrac{1}{2}", explanation: "The range of \\(f\\) excludes \\(0\\) (a \\(3\\) over a non-zero denominator is never \\(0\\)), so the domain of \\(f^{-1}\\) is \\(x \\ne 0\\). The range of \\(f^{-1}\\) excludes \\(\\tfrac{1}{2}\\), the value barred from the domain of \\(f\\)." }, { stepNumber: 7, description: "Part (b): substitute \\(x = 3\\) into \\(f^{-1}\\).", workingLatex: "f^{-1}(3) = \\tfrac{3 + 3}{2(3)} = \\tfrac{6}{6} = 1", explanation: "Putting \\(x = 3\\) into the inverse rule gives the required value." }, { stepNumber: 8, description: "Verify part (b) by substituting back.", workingLatex: "f(1) = \\tfrac{3}{2(1) - 1} = \\tfrac{3}{1} = 3", explanation: "Since \\(f(1) = 3\\), the result \\(f^{-1}(3) = 1\\) is confirmed." }, { stepNumber: 9, description: "Part (c): set \\(f^{-1}(x) = g(x)\\) and clear the fraction.", workingLatex: "\\tfrac{x + 3}{2x} = x + 1 \\;\\Rightarrow\\; x + 3 = 2x(x + 1)", explanation: "Multiply both sides by \\(2x\\) to remove the denominator; this is valid since \\(x \\ne 0\\), which is also outside the domain of \\(f^{-1}\\)." }, { stepNumber: 10, description: "Expand and rearrange to a quadratic.", workingLatex: "x + 3 = 2x^2 + 2x \\;\\Rightarrow\\; 2x^2 + x - 3 = 0", explanation: "Multiply out the right side, then move all terms to one side so the equation equals zero." }, { stepNumber: 11, description: "Factorise the quadratic.", workingLatex: "(2x + 3)(x - 1) = 0", explanation: "The quadratic factorises; checking, \\((2x + 3)(x - 1) = 2x^2 - 2x + 3x - 3 = 2x^2 + x - 3\\) as required." }, { stepNumber: 12, description: "State the solutions.", workingLatex: "x = -\\tfrac{3}{2} \\quad \\text{or} \\quad x = 1", explanation: "Set each factor to zero. Both values are non-zero, so both lie in the domain of \\(f^{-1}\\) and are valid solutions." } ], finalAnswer: "(a) \\( f^{-1}(x) = \\tfrac{x + 3}{2x} \\), domain \\( x \\ne 0 \\), range \\( f^{-1}(x) \\ne \\tfrac{1}{2} \\). (b) \\( f^{-1}(3) = 1 \\). (c) \\( x = -\\tfrac{3}{2} \\) or \\( x = 1 \\)." } },
  { id: "y2fg4-032", topicRef: "y2fg4", topicTitle: "Inverse Functions 32", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = \\tfrac{x + 4}{x - 1} \\), \\( x \\ne 1 \\). (a) Find \\( f^{-1}(x) \\), stating its domain and range. (b) Hence state what is special about \\( f \\). (c) Evaluate \\( f^{-1}(3) \\).", marks: 7, examStyle: true, yearCreated: 2026, tags: ["inverse", "rational", "self-inverse", "domain", "range", "evaluate"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): set \\(y = f(x)\\).", workingLatex: "y = \\tfrac{x + 4}{x - 1}", explanation: "Write \\(y\\) for the output of \\(f\\) so the equation can be rearranged to make \\(x\\) the subject." }, { stepNumber: 2, description: "Cross-multiply to clear the fraction.", workingLatex: "y(x - 1) = x + 4", explanation: "Multiplying both sides by \\(x - 1\\) removes the denominator. This is valid because \\(x \\ne 1\\)." }, { stepNumber: 3, description: "Expand the bracket on the left.", workingLatex: "yx - y = x + 4", explanation: "Distribute \\(y\\) across \\(x - 1\\) so the \\(x\\)-terms can be collected." }, { stepNumber: 4, description: "Gather all \\(x\\)-terms on one side.", workingLatex: "yx - x = y + 4", explanation: "Move the \\(x\\) term left and the \\(-y\\) term right so every term containing \\(x\\) is together." }, { stepNumber: 5, description: "Factor out \\(x\\).", workingLatex: "x(y - 1) = y + 4", explanation: "Taking \\(x\\) outside a bracket collects it into a single factor, ready to divide." }, { stepNumber: 6, description: "Divide and swap variables.", workingLatex: "x = \\tfrac{y + 4}{y - 1} \\;\\Rightarrow\\; f^{-1}(x) = \\tfrac{x + 4}{x - 1}", explanation: "Divide by \\(y - 1\\) to isolate \\(x\\), then replace \\(y\\) with \\(x\\) to obtain the inverse rule." }, { stepNumber: 7, description: "State the domain and range.", workingLatex: "x \\ne 1, \\quad f^{-1}(x) \\ne 1", explanation: "The horizontal asymptote of \\(f\\) is \\(y = 1\\), so the range of \\(f\\) excludes \\(1\\) and the domain of \\(f^{-1}\\) is \\(x \\ne 1\\). The range of \\(f^{-1}\\) excludes \\(1\\), the value barred from the domain of \\(f\\)." }, { stepNumber: 8, description: "Part (b): compare the inverse with the original.", workingLatex: "f^{-1}(x) = \\tfrac{x + 4}{x - 1} = f(x)", explanation: "The inverse has exactly the same rule as \\(f\\), so \\(f\\) is self-inverse. Fractions of the form \\(\\tfrac{ax + b}{cx - a}\\) are always self-inverse, and the graph is symmetric in the line \\(y = x\\)." }, { stepNumber: 9, description: "Part (c): substitute \\(x = 3\\) into \\(f^{-1}\\).", workingLatex: "f^{-1}(3) = \\tfrac{3 + 4}{3 - 1} = \\tfrac{7}{2}", explanation: "Putting \\(x = 3\\) into the inverse rule gives the required value." }, { stepNumber: 10, description: "Verify part (c) by substituting back.", workingLatex: "f\\!\\left(\\tfrac{7}{2}\\right) = \\tfrac{7/2 + 4}{7/2 - 1} = \\tfrac{15/2}{5/2} = 3", explanation: "Since \\(f(\\tfrac{7}{2}) = 3\\), the result \\(f^{-1}(3) = \\tfrac{7}{2}\\) is confirmed." } ], finalAnswer: "(a) \\( f^{-1}(x) = \\tfrac{x + 4}{x - 1} \\), domain \\( x \\ne 1 \\), range \\( f^{-1}(x) \\ne 1 \\). (b) \\( f^{-1} = f \\), so \\( f \\) is self-inverse. (c) \\( f^{-1}(3) = \\tfrac{7}{2} \\)." } },
  { id: "y2fg4-033", topicRef: "y2fg4", topicTitle: "Inverse Functions 33", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = \\tfrac{1 - x}{1 + x} \\), \\( x \\ne -1 \\). (a) Find \\( f^{-1}(x) \\), stating its domain and range. (b) Hence state what is special about \\( f \\). (c) Evaluate \\( f^{-1}(2) \\).", marks: 7, examStyle: true, yearCreated: 2026, tags: ["inverse", "rational", "self-inverse", "domain", "range", "evaluate"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): set \\(y = f(x)\\).", workingLatex: "y = \\tfrac{1 - x}{1 + x}", explanation: "Write \\(y\\) for the output of \\(f\\) so the equation can be rearranged to make \\(x\\) the subject." }, { stepNumber: 2, description: "Cross-multiply to clear the fraction.", workingLatex: "y(1 + x) = 1 - x", explanation: "Multiplying both sides by \\(1 + x\\) removes the denominator. This is valid because \\(x \\ne -1\\)." }, { stepNumber: 3, description: "Expand the bracket on the left.", workingLatex: "y + yx = 1 - x", explanation: "Distribute \\(y\\) across \\(1 + x\\) so the \\(x\\)-terms can be collected." }, { stepNumber: 4, description: "Gather all \\(x\\)-terms on one side.", workingLatex: "yx + x = 1 - y", explanation: "Add \\(x\\) to both sides and subtract \\(y\\) so every term containing \\(x\\) is on the left." }, { stepNumber: 5, description: "Factor out \\(x\\).", workingLatex: "x(y + 1) = 1 - y", explanation: "Taking \\(x\\) outside a bracket collects it into a single factor, ready to divide." }, { stepNumber: 6, description: "Divide and swap variables.", workingLatex: "x = \\tfrac{1 - y}{1 + y} \\;\\Rightarrow\\; f^{-1}(x) = \\tfrac{1 - x}{1 + x}", explanation: "Divide by \\(y + 1\\) to isolate \\(x\\), then replace \\(y\\) with \\(x\\) to obtain the inverse rule." }, { stepNumber: 7, description: "State the domain and range.", workingLatex: "x \\ne -1, \\quad f^{-1}(x) \\ne -1", explanation: "The horizontal asymptote of \\(f\\) is \\(y = -1\\) (ratio of leading coefficients \\(-1/1\\)), so the range of \\(f\\) excludes \\(-1\\) and the domain of \\(f^{-1}\\) is \\(x \\ne -1\\). The range of \\(f^{-1}\\) excludes \\(-1\\), the value barred from the domain of \\(f\\)." }, { stepNumber: 8, description: "Part (b): compare the inverse with the original.", workingLatex: "f^{-1}(x) = \\tfrac{1 - x}{1 + x} = f(x)", explanation: "The inverse has exactly the same rule as \\(f\\), so \\(f\\) is self-inverse: applying it twice returns the original input, and its graph is symmetric in the line \\(y = x\\)." }, { stepNumber: 9, description: "Part (c): substitute \\(x = 2\\) into \\(f^{-1}\\).", workingLatex: "f^{-1}(2) = \\tfrac{1 - 2}{1 + 2} = \\tfrac{-1}{3} = -\\tfrac{1}{3}", explanation: "Putting \\(x = 2\\) into the inverse rule gives the required value." }, { stepNumber: 10, description: "Verify part (c) by substituting back.", workingLatex: "f\\!\\left(-\\tfrac{1}{3}\\right) = \\tfrac{1 - (-1/3)}{1 + (-1/3)} = \\tfrac{4/3}{2/3} = 2", explanation: "Since \\(f(-\\tfrac{1}{3}) = 2\\), the result \\(f^{-1}(2) = -\\tfrac{1}{3}\\) is confirmed." } ], finalAnswer: "(a) \\( f^{-1}(x) = \\tfrac{1 - x}{1 + x} \\), domain \\( x \\ne -1 \\), range \\( f^{-1}(x) \\ne -1 \\). (b) \\( f^{-1} = f \\), so \\( f \\) is self-inverse. (c) \\( f^{-1}(2) = -\\tfrac{1}{3} \\)." } },
  { id: "y2fg4-034", topicRef: "y2fg4", topicTitle: "Inverse Functions 34", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = \\tfrac{2x}{3 - x} \\), \\( x \\ne 3 \\). (a) Find \\( f^{-1}(x) \\), stating its domain and range. (b) Evaluate \\( f^{-1}(4) \\). (c) Evaluate \\( f^{-1}(-6) \\).", marks: 7, examStyle: true, yearCreated: 2026, tags: ["inverse", "rational", "domain", "range", "evaluate"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): set \\(y = f(x)\\).", workingLatex: "y = \\tfrac{2x}{3 - x}", explanation: "Write \\(y\\) for the output of \\(f\\) so the equation can be rearranged to make \\(x\\) the subject." }, { stepNumber: 2, description: "Cross-multiply to clear the fraction.", workingLatex: "y(3 - x) = 2x", explanation: "Multiplying both sides by \\(3 - x\\) removes the denominator. This is valid because \\(x \\ne 3\\)." }, { stepNumber: 3, description: "Expand the bracket on the left.", workingLatex: "3y - yx = 2x", explanation: "Distribute \\(y\\) across \\(3 - x\\) so the \\(x\\)-terms can be collected." }, { stepNumber: 4, description: "Gather all \\(x\\)-terms on one side.", workingLatex: "3y = 2x + yx", explanation: "Add \\(yx\\) to both sides so both \\(x\\)-terms sit together on the right, leaving \\(3y\\) alone on the left." }, { stepNumber: 5, description: "Factor out \\(x\\).", workingLatex: "3y = x(y + 2)", explanation: "Take \\(x\\) outside a bracket on the right; this collects it into a single factor, ready to divide." }, { stepNumber: 6, description: "Divide and swap variables.", workingLatex: "x = \\tfrac{3y}{y + 2} \\;\\Rightarrow\\; f^{-1}(x) = \\tfrac{3x}{x + 2}", explanation: "Divide by \\(y + 2\\) to isolate \\(x\\), then replace \\(y\\) with \\(x\\) to obtain the inverse rule." }, { stepNumber: 7, description: "State the domain and range.", workingLatex: "x \\ne -2, \\quad f^{-1}(x) \\ne 3", explanation: "As \\(x \\to \\infty\\), \\(\\tfrac{2x}{3 - x} \\to -2\\), so the horizontal asymptote of \\(f\\) is \\(y = -2\\) and the range of \\(f\\) excludes \\(-2\\); hence the domain of \\(f^{-1}\\) is \\(x \\ne -2\\). The range of \\(f^{-1}\\) excludes \\(3\\), the value barred from the domain of \\(f\\)." }, { stepNumber: 8, description: "Part (b): substitute \\(x = 4\\) into \\(f^{-1}\\).", workingLatex: "f^{-1}(4) = \\tfrac{3(4)}{4 + 2} = \\tfrac{12}{6} = 2", explanation: "Putting \\(x = 4\\) into the inverse rule gives the required value." }, { stepNumber: 9, description: "Verify part (b) by substituting back.", workingLatex: "f(2) = \\tfrac{2(2)}{3 - 2} = \\tfrac{4}{1} = 4", explanation: "Since \\(f(2) = 4\\), the result \\(f^{-1}(4) = 2\\) is confirmed." }, { stepNumber: 10, description: "Part (c): substitute \\(x = -6\\) into \\(f^{-1}\\).", workingLatex: "f^{-1}(-6) = \\tfrac{3(-6)}{-6 + 2} = \\tfrac{-18}{-4} = \\tfrac{9}{2}", explanation: "Putting \\(x = -6\\) into the inverse rule gives the required value; two negatives divide to a positive." }, { stepNumber: 11, description: "Verify part (c) by substituting back.", workingLatex: "f\\!\\left(\\tfrac{9}{2}\\right) = \\tfrac{2(9/2)}{3 - 9/2} = \\tfrac{9}{-3/2} = -6", explanation: "Since \\(f(\\tfrac{9}{2}) = -6\\), the result \\(f^{-1}(-6) = \\tfrac{9}{2}\\) is confirmed." } ], finalAnswer: "(a) \\( f^{-1}(x) = \\tfrac{3x}{x + 2} \\), domain \\( x \\ne -2 \\), range \\( f^{-1}(x) \\ne 3 \\). (b) \\( f^{-1}(4) = 2 \\). (c) \\( f^{-1}(-6) = \\tfrac{9}{2} \\)." } },
  { id: "y2fg4-035", topicRef: "y2fg4", topicTitle: "Inverse Functions 35", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = \\tfrac{x - 3}{2x + 1} \\), \\( x \\ne -\\tfrac{1}{2} \\). (a) Find \\( f^{-1}(x) \\), stating its domain and range. (b) Evaluate \\( f^{-1}(-3) \\). (c) Evaluate \\( f^{-1}(0) \\).", marks: 7, examStyle: true, yearCreated: 2026, tags: ["inverse", "rational", "domain", "range", "evaluate"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): set \\(y = f(x)\\).", workingLatex: "y = \\tfrac{x - 3}{2x + 1}", explanation: "Write \\(y\\) for the output of \\(f\\) so the equation can be rearranged to make \\(x\\) the subject." }, { stepNumber: 2, description: "Cross-multiply to clear the fraction.", workingLatex: "y(2x + 1) = x - 3", explanation: "Multiplying both sides by \\(2x + 1\\) removes the denominator. This is valid because \\(x \\ne -\\tfrac{1}{2}\\)." }, { stepNumber: 3, description: "Expand the bracket on the left.", workingLatex: "2yx + y = x - 3", explanation: "Distribute \\(y\\) across \\(2x + 1\\) so the \\(x\\)-terms can be collected." }, { stepNumber: 4, description: "Gather \\(x\\)-terms on one side, constants on the other.", workingLatex: "2yx - x = -y - 3", explanation: "Move the \\(x\\) term left and the \\(y\\) term right so every term containing \\(x\\) is together." }, { stepNumber: 5, description: "Factor out \\(x\\).", workingLatex: "x(2y - 1) = -(y + 3)", explanation: "Take \\(x\\) outside a bracket; the right side is written as a single negated bracket ready for the sign tidy-up." }, { stepNumber: 6, description: "Divide, then flip signs for a tidier form.", workingLatex: "x = \\tfrac{-(y + 3)}{2y - 1} = \\tfrac{y + 3}{1 - 2y}", explanation: "Divide by \\(2y - 1\\); multiplying numerator and denominator by \\(-1\\) removes the leading minus sign without changing the value." }, { stepNumber: 7, description: "Swap variables to write the inverse.", workingLatex: "f^{-1}(x) = \\tfrac{x + 3}{1 - 2x}", explanation: "Replace \\(y\\) with \\(x\\) so the inverse is expressed as a function of its own input." }, { stepNumber: 8, description: "State the domain and range.", workingLatex: "x \\ne \\tfrac{1}{2}, \\quad f^{-1}(x) \\ne -\\tfrac{1}{2}", explanation: "The horizontal asymptote of \\(f\\) is \\(y = \\tfrac{1}{2}\\) (ratio of leading coefficients \\(1/2\\)), so the range of \\(f\\) excludes \\(\\tfrac{1}{2}\\) and the domain of \\(f^{-1}\\) is \\(x \\ne \\tfrac{1}{2}\\). The range of \\(f^{-1}\\) excludes \\(-\\tfrac{1}{2}\\), the value barred from the domain of \\(f\\)." }, { stepNumber: 9, description: "Part (b): substitute \\(x = -3\\) into \\(f^{-1}\\).", workingLatex: "f^{-1}(-3) = \\tfrac{-3 + 3}{1 - 2(-3)} = \\tfrac{0}{7} = 0", explanation: "Putting \\(x = -3\\) into the inverse rule gives a numerator of \\(0\\), so the value is \\(0\\)." }, { stepNumber: 10, description: "Verify part (b) by substituting back.", workingLatex: "f(0) = \\tfrac{0 - 3}{2(0) + 1} = \\tfrac{-3}{1} = -3", explanation: "Since \\(f(0) = -3\\), the result \\(f^{-1}(-3) = 0\\) is confirmed." }, { stepNumber: 11, description: "Part (c): substitute \\(x = 0\\) into \\(f^{-1}\\).", workingLatex: "f^{-1}(0) = \\tfrac{0 + 3}{1 - 2(0)} = \\tfrac{3}{1} = 3", explanation: "Putting \\(x = 0\\) into the inverse rule gives the required value." }, { stepNumber: 12, description: "Verify part (c) by substituting back.", workingLatex: "f(3) = \\tfrac{3 - 3}{2(3) + 1} = \\tfrac{0}{7} = 0", explanation: "Since \\(f(3) = 0\\), the result \\(f^{-1}(0) = 3\\) is confirmed." } ], finalAnswer: "(a) \\( f^{-1}(x) = \\tfrac{x + 3}{1 - 2x} \\), domain \\( x \\ne \\tfrac{1}{2} \\), range \\( f^{-1}(x) \\ne -\\tfrac{1}{2} \\). (b) \\( f^{-1}(-3) = 0 \\). (c) \\( f^{-1}(0) = 3 \\)." } },
  // ── Exp / log / sqrt inverses ────
  { id: "y2fg4-036", topicRef: "y2fg4", topicTitle: "Inverse Functions 36", difficulty: "Foundation", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = e^x \\), \\( x \\in \\mathbb{R} \\). Find \\( f^{-1}(x) \\), stating its domain and range.", marks: 3, examStyle: false, yearCreated: 2026, tags: ["inverse", "exp", "domain", "range"], workedSolution: { steps: [ { stepNumber: 1, description: "Set \\(y\\) equal to the output of \\(f\\).", workingLatex: "y = e^x", explanation: "Writing the output as a single variable \\(y\\) is the standard first move for finding an inverse: we now aim to make \\(x\\) the subject." }, { stepNumber: 2, description: "Take the natural logarithm of both sides.", workingLatex: "\\ln y = \\ln(e^x)", explanation: "The natural logarithm is the inverse operation of the exponential \\(e^{(\\cdot)}\\), so applying \\(\\ln\\) to both sides is exactly what undoes the \\(e^x\\)." }, { stepNumber: 3, description: "Simplify the right-hand side.", workingLatex: "\\ln y = x", explanation: "Use the identity \\(\\ln(e^a) = a\\); the logarithm and exponential cancel, leaving \\(x\\) isolated." }, { stepNumber: 4, description: "Swap \\(x\\) and \\(y\\) to write the inverse rule.", workingLatex: "f^{-1}(x) = \\ln x", explanation: "Relabelling \\(y \\to x\\) expresses the inverse as a function of its own input, which is the conventional way to present \\(f^{-1}\\)." }, { stepNumber: 5, description: "Find the domain of \\(f^{-1}\\) from the range of \\(f\\).", workingLatex: "\\text{range of } f:\\; e^x > 0 \\;\\Rightarrow\\; \\text{domain of } f^{-1}:\\; x > 0", explanation: "The exponential \\(e^x\\) is strictly positive for every real \\(x\\), so the range of \\(f\\) is \\((0, \\infty)\\). The domain of \\(f^{-1}\\) equals the range of \\(f\\); the strict inequality \\(x > 0\\) matters because \\(\\ln 0\\) is undefined." }, { stepNumber: 6, description: "State the range of \\(f^{-1}\\).", workingLatex: "\\text{range of } f^{-1}:\\; f^{-1}(x) \\in \\mathbb{R}", explanation: "The range of \\(f^{-1}\\) equals the domain of \\(f\\), which is all real numbers." } ], finalAnswer: "\\( f^{-1}(x) = \\ln x \\), with domain \\(x > 0\\) and range \\(f^{-1}(x) \\in \\mathbb{R}\\)." } },
  { id: "y2fg4-037", topicRef: "y2fg4", topicTitle: "Inverse Functions 37", difficulty: "Standard", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = e^{2x} \\), \\( x \\in \\mathbb{R} \\). (a) Find \\( f^{-1}(x) \\), stating its domain and range. (b) Evaluate \\( f^{-1}(1) \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["inverse", "exp", "domain", "range", "evaluate"], workedSolution: { steps: [ { stepNumber: 1, description: "(a) Set \\(y\\) equal to the output of \\(f\\).", workingLatex: "y = e^{2x}", explanation: "Writing the output as \\(y\\) starts the inverse procedure; the goal is now to make \\(x\\) the subject." }, { stepNumber: 2, description: "(a) Take the natural logarithm of both sides.", workingLatex: "\\ln y = \\ln(e^{2x})", explanation: "The natural logarithm undoes the exponential, so applying \\(\\ln\\) to both sides is the move that frees the exponent." }, { stepNumber: 3, description: "(a) Simplify using \\(\\ln(e^a) = a\\).", workingLatex: "\\ln y = 2x", explanation: "The exponent here is \\(2x\\), so the identity \\(\\ln(e^{2x}) = 2x\\) brings the whole exponent down." }, { stepNumber: 4, description: "(a) Divide by 2 to isolate \\(x\\).", workingLatex: "x = \\tfrac{1}{2}\\ln y", explanation: "Dividing both sides by 2 undoes the multiplication and leaves \\(x\\) as the subject." }, { stepNumber: 5, description: "(a) Swap \\(x\\) and \\(y\\) to write the inverse rule.", workingLatex: "f^{-1}(x) = \\tfrac{1}{2}\\ln x", explanation: "Relabelling \\(y \\to x\\) presents the inverse as a function of its own input." }, { stepNumber: 6, description: "(a) State the domain and range of \\(f^{-1}\\).", workingLatex: "\\text{domain: } x > 0,\\quad \\text{range: } f^{-1}(x) \\in \\mathbb{R}", explanation: "The range of \\(e^{2x}\\) is \\((0, \\infty)\\) since the exponential is always positive, so the domain of \\(f^{-1}\\) is the strict inequality \\(x > 0\\). The range of \\(f^{-1}\\) equals the domain of \\(f\\), all of \\(\\mathbb{R}\\)." }, { stepNumber: 7, description: "(b) Substitute \\(x = 1\\) into \\(f^{-1}\\).", workingLatex: "f^{-1}(1) = \\tfrac{1}{2}\\ln 1", explanation: "Part (b) asks for a numerical value, so substitute the given input directly into the inverse rule found in part (a)." }, { stepNumber: 8, description: "(b) Evaluate using \\(\\ln 1 = 0\\).", workingLatex: "f^{-1}(1) = \\tfrac{1}{2}(0) = 0", explanation: "Since \\(e^0 = 1\\), we have \\(\\ln 1 = 0\\); a common slip is to write \\(\\ln 1 = 1\\), so it is worth noting the logarithm of 1 is always zero." } ], finalAnswer: "(a) \\( f^{-1}(x) = \\tfrac{1}{2}\\ln x \\), with domain \\(x > 0\\) and range \\(f^{-1}(x) \\in \\mathbb{R}\\). (b) \\( f^{-1}(1) = 0 \\)." } },
  { id: "y2fg4-038", topicRef: "y2fg4", topicTitle: "Inverse Functions 38", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = 4e^{3x} - 5 \\), \\( x \\in \\mathbb{R} \\). (a) State the range of \\( f \\). (b) Find \\( f^{-1}(x) \\), stating its domain and range. (c) Solve the equation \\( f^{-1}(x) = 0 \\), giving your answer exactly.", marks: 8, examStyle: true, yearCreated: 2026, tags: ["inverse", "exp", "domain", "range", "evaluate"], workedSolution: { steps: [ { stepNumber: 1, description: "(a) Start from the sign of the exponential.", workingLatex: "e^{3x} > 0 \\text{ for all real } x", explanation: "The exponential function is strictly positive everywhere; this fact is the key to bounding \\(f\\)." }, { stepNumber: 2, description: "(a) Multiply by 4 and subtract 5 to bound \\(f\\).", workingLatex: "4e^{3x} > 0 \\;\\Rightarrow\\; 4e^{3x} - 5 > -5", explanation: "Multiplying a positive quantity by 4 keeps it positive, and subtracting 5 shifts the bound down to \\(-5\\). This shows every output of \\(f\\) exceeds \\(-5\\)." }, { stepNumber: 3, description: "(a) State the range of \\(f\\).", workingLatex: "\\text{range of } f:\\; f(x) > -5", explanation: "As \\(x \\to \\infty\\) the term \\(4e^{3x}\\) grows without bound, so \\(f\\) takes every value above \\(-5\\); the value \\(-5\\) itself is never attained." }, { stepNumber: 4, description: "(b) Set \\(y\\) equal to the output of \\(f\\).", workingLatex: "y = 4e^{3x} - 5", explanation: "Writing the output as \\(y\\) begins the inverse procedure; we now make \\(x\\) the subject." }, { stepNumber: 5, description: "(b) Add 5 to both sides.", workingLatex: "y + 5 = 4e^{3x}", explanation: "Adding 5 undoes the constant term and isolates the term containing the exponential." }, { stepNumber: 6, description: "(b) Divide by 4 to isolate \\(e^{3x}\\).", workingLatex: "e^{3x} = \\tfrac{y + 5}{4}", explanation: "Dividing by 4 leaves the exponential alone on one side, ready for the logarithm." }, { stepNumber: 7, description: "(b) Take the natural logarithm of both sides.", workingLatex: "3x = \\ln\\!\\left(\\tfrac{y + 5}{4}\\right)", explanation: "Applying \\(\\ln\\) undoes the exponential. The logarithm requires \\(\\tfrac{y + 5}{4} > 0\\), i.e. \\(y > -5\\), which agrees with the range found in part (a)." }, { stepNumber: 8, description: "(b) Divide by 3 to solve for \\(x\\).", workingLatex: "x = \\tfrac{1}{3}\\ln\\!\\left(\\tfrac{y + 5}{4}\\right)", explanation: "Dividing by 3 makes \\(x\\) the subject." }, { stepNumber: 9, description: "(b) Swap variables and state domain and range.", workingLatex: "f^{-1}(x) = \\tfrac{1}{3}\\ln\\!\\left(\\tfrac{x + 5}{4}\\right),\\quad \\text{domain: } x > -5,\\quad \\text{range: } f^{-1}(x) \\in \\mathbb{R}", explanation: "Relabelling \\(y \\to x\\) gives the inverse rule. The domain of \\(f^{-1}\\) is the range of \\(f\\), so \\(x > -5\\); the range of \\(f^{-1}\\) is the domain of \\(f\\), all of \\(\\mathbb{R}\\)." }, { stepNumber: 10, description: "(c) Set \\(f^{-1}(x) = 0\\).", workingLatex: "\\tfrac{1}{3}\\ln\\!\\left(\\tfrac{x + 5}{4}\\right) = 0", explanation: "Part (c) asks for the input that the inverse maps to zero; substitute the rule from part (b) and solve." }, { stepNumber: 11, description: "(c) Multiply by 3 to clear the fraction.", workingLatex: "\\ln\\!\\left(\\tfrac{x + 5}{4}\\right) = 0", explanation: "Multiplying both sides by 3 removes the \\(\\tfrac{1}{3}\\) and leaves the logarithm alone." }, { stepNumber: 12, description: "(c) Exponentiate both sides.", workingLatex: "\\tfrac{x + 5}{4} = e^0 = 1", explanation: "If \\(\\ln(z) = 0\\) then \\(z = e^0 = 1\\); applying \\(e^{(\\cdot)}\\) removes the logarithm." }, { stepNumber: 13, description: "(c) Solve the resulting linear equation.", workingLatex: "x + 5 = 4 \\;\\Rightarrow\\; x = -1", explanation: "Multiply by 4 then subtract 5. The solution \\(x = -1\\) satisfies \\(x > -5\\), so it lies in the domain of \\(f^{-1}\\) and is valid." } ], finalAnswer: "(a) Range of \\(f\\): \\(f(x) > -5\\). (b) \\( f^{-1}(x) = \\tfrac{1}{3}\\ln\\!\\left(\\tfrac{x + 5}{4}\\right) \\), with domain \\(x > -5\\) and range \\(f^{-1}(x) \\in \\mathbb{R}\\). (c) \\( x = -1 \\)." } },
  { id: "y2fg4-039", topicRef: "y2fg4", topicTitle: "Inverse Functions 39", difficulty: "Standard", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = \\ln(x + 1) \\), \\( x > -1 \\). (a) Find \\( f^{-1}(x) \\), stating its domain and range. (b) Evaluate \\( f^{-1}(0) \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["inverse", "log", "domain", "range", "evaluate"], workedSolution: { steps: [ { stepNumber: 1, description: "(a) Set \\(y\\) equal to the output of \\(f\\).", workingLatex: "y = \\ln(x + 1)", explanation: "Writing the output as \\(y\\) begins the inverse procedure; we aim to make \\(x\\) the subject." }, { stepNumber: 2, description: "(a) Exponentiate both sides.", workingLatex: "e^y = e^{\\ln(x + 1)}", explanation: "The exponential \\(e^{(\\cdot)}\\) is the inverse of \\(\\ln\\), so applying it to both sides is the move that undoes the logarithm." }, { stepNumber: 3, description: "(a) Simplify using \\(e^{\\ln z} = z\\).", workingLatex: "e^y = x + 1", explanation: "Because \\(x > -1\\) we have \\(x + 1 > 0\\), so the identity \\(e^{\\ln z} = z\\) applies and the exponential and logarithm cancel." }, { stepNumber: 4, description: "(a) Subtract 1 to solve for \\(x\\).", workingLatex: "x = e^y - 1", explanation: "Subtracting 1 makes \\(x\\) the subject." }, { stepNumber: 5, description: "(a) Swap \\(x\\) and \\(y\\) to write the inverse rule.", workingLatex: "f^{-1}(x) = e^x - 1", explanation: "Relabelling \\(y \\to x\\) presents the inverse as a function of its own input." }, { stepNumber: 6, description: "(a) State the domain and range of \\(f^{-1}\\).", workingLatex: "\\text{domain: } x \\in \\mathbb{R},\\quad \\text{range: } f^{-1}(x) > -1", explanation: "The logarithm \\(\\ln(x+1)\\) takes every real value as \\(x\\) ranges over \\((-1, \\infty)\\), so the range of \\(f\\) is all of \\(\\mathbb{R}\\); hence the domain of \\(f^{-1}\\) is \\(x \\in \\mathbb{R}\\). The range of \\(f^{-1}\\) equals the domain of \\(f\\), namely \\(f^{-1}(x) > -1\\)." }, { stepNumber: 7, description: "(b) Substitute \\(x = 0\\) into \\(f^{-1}\\).", workingLatex: "f^{-1}(0) = e^0 - 1", explanation: "Part (b) requests a numerical value, so substitute the given input into the inverse rule from part (a)." }, { stepNumber: 8, description: "(b) Evaluate using \\(e^0 = 1\\).", workingLatex: "f^{-1}(0) = 1 - 1 = 0", explanation: "Any nonzero base raised to the power 0 equals 1, so \\(e^0 = 1\\) and the value is \\(0\\)." } ], finalAnswer: "(a) \\( f^{-1}(x) = e^x - 1 \\), with domain \\(x \\in \\mathbb{R}\\) and range \\(f^{-1}(x) > -1\\). (b) \\( f^{-1}(0) = 0 \\)." } },
  { id: "y2fg4-040", topicRef: "y2fg4", topicTitle: "Inverse Functions 40", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = 3\\ln(2x - 1) + 4 \\), \\( x > \\tfrac{1}{2} \\). (a) Find \\( f^{-1}(x) \\), stating its domain and range. (b) Evaluate \\( f^{-1}(4) \\). (c) State, with a reason, the value of \\( ff^{-1}(10) \\).", marks: 8, examStyle: true, yearCreated: 2026, tags: ["inverse", "log", "domain", "range", "evaluate"], workedSolution: { steps: [ { stepNumber: 1, description: "(a) Set \\(y\\) equal to the output of \\(f\\).", workingLatex: "y = 3\\ln(2x - 1) + 4", explanation: "Writing the output as \\(y\\) begins the inverse procedure; we now make \\(x\\) the subject by peeling off operations in reverse order." }, { stepNumber: 2, description: "(a) Subtract 4 from both sides.", workingLatex: "y - 4 = 3\\ln(2x - 1)", explanation: "Subtracting the constant 4 is the first reverse step, isolating the term that contains the logarithm." }, { stepNumber: 3, description: "(a) Divide by 3 to isolate the logarithm.", workingLatex: "\\tfrac{y - 4}{3} = \\ln(2x - 1)", explanation: "Dividing by 3 leaves the logarithm alone on one side, ready to be undone by exponentiating." }, { stepNumber: 4, description: "(a) Exponentiate both sides.", workingLatex: "e^{(y - 4)/3} = 2x - 1", explanation: "Applying \\(e^{(\\cdot)}\\) undoes the natural logarithm, since \\(e^{\\ln(2x - 1)} = 2x - 1\\) for \\(2x - 1 > 0\\)." }, { stepNumber: 5, description: "(a) Add 1 to both sides.", workingLatex: "2x = e^{(y - 4)/3} + 1", explanation: "Adding 1 removes the constant inside the former logarithm argument." }, { stepNumber: 6, description: "(a) Divide by 2 to solve for \\(x\\).", workingLatex: "x = \\tfrac{1}{2}\\left(e^{(y - 4)/3} + 1\\right)", explanation: "Dividing by 2 makes \\(x\\) the subject and completes the rearrangement." }, { stepNumber: 7, description: "(a) Swap variables and state domain and range.", workingLatex: "f^{-1}(x) = \\tfrac{1}{2}\\left(e^{(x - 4)/3} + 1\\right),\\quad \\text{domain: } x \\in \\mathbb{R},\\quad \\text{range: } f^{-1}(x) > \\tfrac{1}{2}", explanation: "As \\(x \\to \\tfrac{1}{2}^+\\) the term \\(\\ln(2x-1) \\to -\\infty\\), and as \\(x \\to \\infty\\) it \\(\\to \\infty\\), so the range of \\(f\\) is all of \\(\\mathbb{R}\\); hence the domain of \\(f^{-1}\\) is \\(x \\in \\mathbb{R}\\). The range of \\(f^{-1}\\) equals the domain of \\(f\\), namely \\(f^{-1}(x) > \\tfrac{1}{2}\\)." }, { stepNumber: 8, description: "(b) Substitute \\(x = 4\\) into \\(f^{-1}\\).", workingLatex: "f^{-1}(4) = \\tfrac{1}{2}\\left(e^{(4 - 4)/3} + 1\\right)", explanation: "Part (b) asks for a numerical value, so substitute the given input into the inverse rule from part (a)." }, { stepNumber: 9, description: "(b) Simplify the exponent and evaluate.", workingLatex: "f^{-1}(4) = \\tfrac{1}{2}\\left(e^0 + 1\\right) = \\tfrac{1}{2}(2) = 1", explanation: "The exponent \\((4-4)/3\\) is \\(0\\), so \\(e^0 = 1\\); the bracket becomes \\(2\\) and halving gives \\(1\\)." }, { stepNumber: 10, description: "(c) Apply the inverse-function property.", workingLatex: "ff^{-1}(10) = 10", explanation: "Applying \\(f\\) immediately after \\(f^{-1}\\) undoes it, so \\(ff^{-1}(x) = x\\) for every \\(x\\) in the domain of \\(f^{-1}\\). Since the domain of \\(f^{-1}\\) is all of \\(\\mathbb{R}\\), the value \\(10\\) is in it and no substitution into the formula is needed; the result is simply \\(10\\)." } ], finalAnswer: "(a) \\( f^{-1}(x) = \\tfrac{1}{2}\\left(e^{(x - 4)/3} + 1\\right) \\), with domain \\(x \\in \\mathbb{R}\\) and range \\(f^{-1}(x) > \\tfrac{1}{2}\\). (b) \\( f^{-1}(4) = 1 \\). (c) \\( ff^{-1}(10) = 10 \\), since \\(f\\) and \\(f^{-1}\\) are inverses." } },
  { id: "y2fg4-041", topicRef: "y2fg4", topicTitle: "Inverse Functions 41", difficulty: "Standard", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = \\sqrt{x} + 3 \\), \\( x \\ge 0 \\). (a) Find \\( f^{-1}(x) \\), stating its domain and range. (b) Evaluate \\( f^{-1}(7) \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["inverse", "sqrt", "domain", "range", "evaluate"], workedSolution: { steps: [ { stepNumber: 1, description: "(a) Set \\(y\\) equal to the output of \\(f\\).", workingLatex: "y = \\sqrt{x} + 3", explanation: "Writing the output as \\(y\\) begins the inverse procedure; we now make \\(x\\) the subject." }, { stepNumber: 2, description: "(a) Subtract 3 to isolate the square root.", workingLatex: "\\sqrt{x} = y - 3", explanation: "Subtracting the constant 3 leaves the square-root term alone, ready to be removed by squaring." }, { stepNumber: 3, description: "(a) Square both sides.", workingLatex: "x = (y - 3)^2", explanation: "Squaring undoes the square root. Note \\(\\sqrt{x}\\) only ever outputs values \\(\\ge 0\\), so this step is valid provided \\(y - 3 \\ge 0\\), i.e. \\(y \\ge 3\\) — this restriction will fix the domain of the inverse." }, { stepNumber: 4, description: "(a) Swap \\(x\\) and \\(y\\) to write the inverse rule.", workingLatex: "f^{-1}(x) = (x - 3)^2", explanation: "Relabelling \\(y \\to x\\) presents the inverse as a function of its own input." }, { stepNumber: 5, description: "(a) State the domain and range of \\(f^{-1}\\).", workingLatex: "\\text{domain: } x \\ge 3,\\quad \\text{range: } f^{-1}(x) \\ge 0", explanation: "On \\(x \\ge 0\\), \\(f\\) has minimum value \\(3\\) at \\(x = 0\\) and increases without bound, so the range of \\(f\\) is \\(f(x) \\ge 3\\); hence the domain of \\(f^{-1}\\) is \\(x \\ge 3\\). The range of \\(f^{-1}\\) equals the domain of \\(f\\), namely \\(f^{-1}(x) \\ge 0\\) — without this restriction \\((x-3)^2\\) would wrongly appear to be defined for all \\(x\\)." }, { stepNumber: 6, description: "(b) Substitute \\(x = 7\\) into \\(f^{-1}\\).", workingLatex: "f^{-1}(7) = (7 - 3)^2", explanation: "Part (b) asks for a numerical value; first confirm \\(7 \\ge 3\\) so the input lies in the domain, then substitute." }, { stepNumber: 7, description: "(b) Evaluate the expression.", workingLatex: "f^{-1}(7) = 4^2 = 16", explanation: "Compute the bracket first, then square: \\((7-3) = 4\\) and \\(4^2 = 16\\)." } ], finalAnswer: "(a) \\( f^{-1}(x) = (x - 3)^2 \\), with domain \\(x \\ge 3\\) and range \\(f^{-1}(x) \\ge 0\\). (b) \\( f^{-1}(7) = 16 \\)." } },
  { id: "y2fg4-042", topicRef: "y2fg4", topicTitle: "Inverse Functions 42", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = \\sqrt{3x - 6} + 2 \\), \\( x \\ge 2 \\). (a) Find \\( f^{-1}(x) \\), stating its domain and range. (b) Hence solve the equation \\( f(x) = f^{-1}(x) \\).", marks: 8, examStyle: true, yearCreated: 2026, tags: ["inverse", "sqrt", "domain", "range", "evaluate"], workedSolution: { steps: [ { stepNumber: 1, description: "(a) Set \\(y\\) equal to the output of \\(f\\).", workingLatex: "y = \\sqrt{3x - 6} + 2", explanation: "Writing the output as \\(y\\) begins the inverse procedure; we now make \\(x\\) the subject." }, { stepNumber: 2, description: "(a) Subtract 2 to isolate the square root.", workingLatex: "\\sqrt{3x - 6} = y - 2", explanation: "Subtracting the constant 2 leaves the square-root term alone, ready to be removed by squaring." }, { stepNumber: 3, description: "(a) Square both sides.", workingLatex: "3x - 6 = (y - 2)^2", explanation: "Squaring undoes the square root. Since \\(\\sqrt{3x-6} \\ge 0\\), this step requires \\(y - 2 \\ge 0\\), i.e. \\(y \\ge 2\\), which will determine the domain of the inverse." }, { stepNumber: 4, description: "(a) Add 6 and divide by 3 to solve for \\(x\\).", workingLatex: "3x = (y - 2)^2 + 6 \\;\\Rightarrow\\; x = \\tfrac{(y - 2)^2 + 6}{3}", explanation: "Add 6 to undo the constant inside, then divide by 3 to make \\(x\\) the subject." }, { stepNumber: 5, description: "(a) Swap variables and state domain and range.", workingLatex: "f^{-1}(x) = \\tfrac{(x - 2)^2 + 6}{3},\\quad \\text{domain: } x \\ge 2,\\quad \\text{range: } f^{-1}(x) \\ge 2", explanation: "On \\(x \\ge 2\\), \\(f\\) has minimum value \\(2\\) at \\(x = 2\\) (where the root is 0) and increases without bound, so the range of \\(f\\) is \\(f(x) \\ge 2\\); hence the domain of \\(f^{-1}\\) is \\(x \\ge 2\\). The range of \\(f^{-1}\\) equals the domain of \\(f\\), namely \\(f^{-1}(x) \\ge 2\\)." }, { stepNumber: 6, description: "(b) Replace \\(f(x) = f^{-1}(x)\\) with \\(f(x) = x\\).", workingLatex: "f(x) = f^{-1}(x) \\;\\Longrightarrow\\; f(x) = x", explanation: "\\(f\\) is strictly increasing, so the graphs of \\(f\\) and \\(f^{-1}\\) can only meet on the line \\(y = x\\); therefore any solution of \\(f(x) = f^{-1}(x)\\) also satisfies \\(f(x) = x\\), which is easier to solve." }, { stepNumber: 7, description: "(b) Write out the equation and isolate the root.", workingLatex: "\\sqrt{3x - 6} + 2 = x \\;\\Rightarrow\\; \\sqrt{3x - 6} = x - 2", explanation: "Subtracting 2 isolates the square root. Squaring next requires the right-hand side to be non-negative, so \\(x \\ge 2\\) is needed for any valid solution." }, { stepNumber: 8, description: "(b) Square both sides.", workingLatex: "3x - 6 = (x - 2)^2", explanation: "Squaring removes the square root, turning the equation into a polynomial one." }, { stepNumber: 9, description: "(b) Expand and collect all terms on one side.", workingLatex: "3x - 6 = x^2 - 4x + 4 \\;\\Rightarrow\\; x^2 - 7x + 10 = 0", explanation: "Expand \\((x-2)^2 = x^2 - 4x + 4\\), then move every term to one side to form a standard quadratic." }, { stepNumber: 10, description: "(b) Factorise the quadratic.", workingLatex: "(x - 2)(x - 5) = 0 \\;\\Rightarrow\\; x = 2 \\text{ or } x = 5", explanation: "The factor pair \\(-2\\) and \\(-5\\) multiply to \\(+10\\) and add to \\(-7\\), giving the two candidate roots." }, { stepNumber: 11, description: "(b) Check candidates against the domain and original equation.", workingLatex: "f(2) = \\sqrt{0} + 2 = 2,\\qquad f(5) = \\sqrt{9} + 2 = 5", explanation: "Both roots satisfy \\(x \\ge 2\\), and substituting back confirms \\(f(2) = 2\\) and \\(f(5) = 5\\); squaring can introduce false roots, so this check shows both are genuine solutions." } ], finalAnswer: "(a) \\( f^{-1}(x) = \\tfrac{(x - 2)^2 + 6}{3} \\), with domain \\(x \\ge 2\\) and range \\(f^{-1}(x) \\ge 2\\). (b) \\( x = 2 \\) or \\( x = 5 \\)." } },
  { id: "y2fg4-043", topicRef: "y2fg4", topicTitle: "Inverse Functions 43", difficulty: "Standard", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = 5^x \\), \\( x \\in \\mathbb{R} \\). (a) Find \\( f^{-1}(x) \\), stating its domain and range. (b) Evaluate \\( f^{-1}(25) \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["inverse", "exp", "log", "domain", "range", "evaluate"], workedSolution: { steps: [ { stepNumber: 1, description: "(a) Set \\(y\\) equal to the output of \\(f\\).", workingLatex: "y = 5^x", explanation: "Writing the output as \\(y\\) begins the inverse procedure; we now make \\(x\\) the subject." }, { stepNumber: 2, description: "(a) Take logarithm base 5 of both sides.", workingLatex: "\\log_5 y = \\log_5(5^x)", explanation: "The logarithm with base 5 is the inverse operation of raising 5 to a power, so it is exactly what undoes \\(5^x\\)." }, { stepNumber: 3, description: "(a) Simplify using \\(\\log_b(b^a) = a\\).", workingLatex: "\\log_5 y = x", explanation: "The identity \\(\\log_b(b^a) = a\\) collapses the right-hand side, leaving \\(x\\) isolated." }, { stepNumber: 4, description: "(a) Swap variables and state domain and range.", workingLatex: "f^{-1}(x) = \\log_5 x,\\quad \\text{domain: } x > 0,\\quad \\text{range: } f^{-1}(x) \\in \\mathbb{R}", explanation: "Relabelling \\(y \\to x\\) gives the inverse rule. The range of \\(5^x\\) is \\((0, \\infty)\\) since an exponential is always positive, so the domain of \\(f^{-1}\\) is the strict inequality \\(x > 0\\); the range of \\(f^{-1}\\) equals the domain of \\(f\\), all of \\(\\mathbb{R}\\)." }, { stepNumber: 5, description: "(b) Substitute \\(x = 25\\) into \\(f^{-1}\\).", workingLatex: "f^{-1}(25) = \\log_5 25", explanation: "Part (b) asks for a numerical value, so substitute the given input into the inverse rule from part (a)." }, { stepNumber: 6, description: "(b) Write 25 as a power of 5 and evaluate.", workingLatex: "f^{-1}(25) = \\log_5(5^2) = 2", explanation: "Recognising \\(25 = 5^2\\) lets the identity \\(\\log_5(5^2) = 2\\) finish the evaluation; the logarithm returns the power to which 5 must be raised." } ], finalAnswer: "(a) \\( f^{-1}(x) = \\log_5 x \\), with domain \\(x > 0\\) and range \\(f^{-1}(x) \\in \\mathbb{R}\\). (b) \\( f^{-1}(25) = 2 \\)." } },
  { id: "y2fg4-044", topicRef: "y2fg4", topicTitle: "Inverse Functions 44", difficulty: "Challenge", answerType: "expression", questionText: "The functions \\( f \\) and \\( g \\) are defined by \\( f(x) = e^{x} + 2 \\), \\( x \\in \\mathbb{R} \\), and \\( g(x) = \\ln(x - 1) \\), \\( x > 1 \\). (a) Find \\( f^{-1}(x) \\), stating its domain and range. (b) Find an expression for the composite function \\( gf(x) \\), and state its range. (c) Evaluate \\( f^{-1}(e^2 + 2) \\).", marks: 8, examStyle: true, yearCreated: 2026, tags: ["inverse", "exp", "log", "domain", "range", "evaluate", "composite"], workedSolution: { steps: [ { stepNumber: 1, description: "(a) Set \\(y\\) equal to the output of \\(f\\).", workingLatex: "y = e^x + 2", explanation: "Writing the output as \\(y\\) begins the inverse procedure; we now make \\(x\\) the subject." }, { stepNumber: 2, description: "(a) Subtract 2 to isolate \\(e^x\\).", workingLatex: "e^x = y - 2", explanation: "Subtracting the constant 2 leaves the exponential term alone, ready to be undone by the logarithm." }, { stepNumber: 3, description: "(a) Take the natural logarithm of both sides.", workingLatex: "x = \\ln(y - 2)", explanation: "Applying \\(\\ln\\) undoes the exponential. The logarithm requires its argument to be positive, i.e. \\(y - 2 > 0\\), so \\(y > 2\\) — this fixes the domain of the inverse." }, { stepNumber: 4, description: "(a) Swap variables and state domain and range.", workingLatex: "f^{-1}(x) = \\ln(x - 2),\\quad \\text{domain: } x > 2,\\quad \\text{range: } f^{-1}(x) \\in \\mathbb{R}", explanation: "Relabelling \\(y \\to x\\) gives the inverse rule. Since \\(e^x > 0\\) for all \\(x\\), the range of \\(f\\) is \\(f(x) > 2\\); hence the domain of \\(f^{-1}\\) is \\(x > 2\\). The range of \\(f^{-1}\\) equals the domain of \\(f\\), all of \\(\\mathbb{R}\\)." }, { stepNumber: 5, description: "(b) Substitute \\(f(x)\\) into \\(g\\) to form \\(gf(x)\\).", workingLatex: "gf(x) = g(e^x + 2) = \\ln\\!\\big((e^x + 2) - 1\\big)", explanation: "The composite \\(gf\\) means apply \\(f\\) first, then \\(g\\); replace the input of \\(g\\) with the formula for \\(f(x)\\). Since \\(e^x + 2 > 2 > 1\\), the input always lies in the domain of \\(g\\), so \\(gf\\) is defined for every real \\(x\\)." }, { stepNumber: 6, description: "(b) Simplify the argument of the logarithm.", workingLatex: "gf(x) = \\ln(e^x + 1)", explanation: "Combine the constants inside the bracket: \\(2 - 1 = 1\\)." }, { stepNumber: 7, description: "(b) Bound the argument to find the range of \\(gf\\).", workingLatex: "e^x > 0 \\;\\Rightarrow\\; e^x + 1 > 1", explanation: "Since the exponential is strictly positive, adding 1 makes the argument of the logarithm strictly greater than 1." }, { stepNumber: 8, description: "(b) Apply the logarithm to state the range.", workingLatex: "\\ln(e^x + 1) > \\ln 1 = 0 \\;\\Rightarrow\\; \\text{range of } gf:\\; gf(x) > 0", explanation: "The logarithm is increasing, so an argument greater than 1 gives an output greater than \\(\\ln 1 = 0\\). As \\(x \\to -\\infty\\) the value tends to 0 from above and as \\(x \\to \\infty\\) it grows without bound, so the range is \\(gf(x) > 0\\)." }, { stepNumber: 9, description: "(c) Substitute \\(x = e^2 + 2\\) into \\(f^{-1}\\).", workingLatex: "f^{-1}(e^2 + 2) = \\ln\\!\\big((e^2 + 2) - 2\\big)", explanation: "Part (c) asks for a numerical value; first note \\(e^2 + 2 > 2\\) so the input lies in the domain of \\(f^{-1}\\), then substitute into the rule from part (a)." }, { stepNumber: 10, description: "(c) Simplify and evaluate.", workingLatex: "f^{-1}(e^2 + 2) = \\ln(e^2) = 2", explanation: "The constant terms cancel to leave \\(\\ln(e^2)\\), and the identity \\(\\ln(e^a) = a\\) gives the exact value 2." } ], finalAnswer: "(a) \\( f^{-1}(x) = \\ln(x - 2) \\), with domain \\(x > 2\\) and range \\(f^{-1}(x) \\in \\mathbb{R}\\). (b) \\( gf(x) = \\ln(e^x + 1) \\), with range \\(gf(x) > 0\\). (c) \\( f^{-1}(e^2 + 2) = 2 \\)." } },
  // ── Domain and range of f^{-1} ────
  { id: "y2fg4-045", topicRef: "y2fg4", topicTitle: "Inverse Functions 45", difficulty: "Standard", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = 2x - 5 \\), \\( x \\ge 0 \\). (a) State the range of \\( f \\). (b) Hence state the domain and range of \\( f^{-1} \\), justifying your answer.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["inverse", "domain", "range"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): note that f is increasing.", workingLatex: "f(x) = 2x - 5,\\quad \\text{gradient} = 2 > 0", explanation: "The graph of \\(f\\) is a straight line with positive gradient \\(2\\), so \\(f\\) is strictly increasing across its whole domain — larger inputs always give larger outputs." }, { stepNumber: 2, description: "Evaluate f at the left endpoint of the domain.", workingLatex: "f(0) = 2(0) - 5 = -5", explanation: "Because \\(f\\) is increasing, its smallest value on \\(x \\ge 0\\) occurs at the smallest input, \\(x = 0\\); substituting gives the minimum output \\(-5\\)." }, { stepNumber: 3, description: "State the range of f.", workingLatex: "\\text{range}(f) = \\{y : y \\ge -5\\}", explanation: "As \\(x\\) increases without bound so does \\(f(x)\\), so there is no upper limit; the outputs fill every value from the minimum \\(-5\\) upwards." }, { stepNumber: 4, description: "Part (b): state the domain/range swap rule.", workingLatex: "\\text{dom}(f^{-1}) = \\text{range}(f),\\qquad \\text{range}(f^{-1}) = \\text{dom}(f)", explanation: "The inverse reverses the mapping, so the outputs of \\(f\\) become the inputs of \\(f^{-1}\\) and the inputs of \\(f\\) become the outputs of \\(f^{-1}\\). A common slip is to invert the formula but keep \\(f\\)'s own domain — always swap." }, { stepNumber: 5, description: "Read off the domain of f-inverse.", workingLatex: "\\text{dom}(f^{-1}) = \\text{range}(f) = \\{x : x \\ge -5\\}", explanation: "The domain of the inverse equals the range of \\(f\\) found in part (a)." }, { stepNumber: 6, description: "Read off the range of f-inverse.", workingLatex: "\\text{range}(f^{-1}) = \\text{dom}(f) = \\{y : y \\ge 0\\}", explanation: "The range of the inverse equals the original domain of \\(f\\), which was given as \\(x \\ge 0\\)." } ], finalAnswer: "(a) Range of \\( f \\): \\( f(x) \\ge -5 \\). (b) Domain of \\( f^{-1} \\): \\( x \\ge -5 \\); range of \\( f^{-1} \\): \\( f^{-1}(x) \\ge 0 \\)." } },
  { id: "y2fg4-046", topicRef: "y2fg4", topicTitle: "Inverse Functions 46", difficulty: "Standard", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = x^2 + 2 \\), \\( x \\ge 0 \\). State the domain and range of \\( f^{-1} \\), explaining your reasoning.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["inverse", "domain", "range"], workedSolution: { steps: [ { stepNumber: 1, description: "Find the smallest value of x squared on the domain.", workingLatex: "x \\ge 0 \\Rightarrow x^2 \\ge 0", explanation: "On the domain \\(x \\ge 0\\) the square \\(x^2\\) is never negative, and it attains its least value \\(0\\) when \\(x = 0\\)." }, { stepNumber: 2, description: "Deduce the smallest value of f.", workingLatex: "f(x) = x^2 + 2 \\ge 0 + 2 = 2", explanation: "Adding \\(2\\) to every value of \\(x^2\\) shifts the minimum up to \\(2\\); \\(f\\) increases without bound as \\(x\\) grows." }, { stepNumber: 3, description: "State the range of f.", workingLatex: "\\text{range}(f) = \\{y : y \\ge 2\\}", explanation: "The outputs of \\(f\\) cover every value from the minimum \\(2\\) upwards." }, { stepNumber: 4, description: "State the domain/range swap rule.", workingLatex: "\\text{dom}(f^{-1}) = \\text{range}(f),\\qquad \\text{range}(f^{-1}) = \\text{dom}(f)", explanation: "An inverse function interchanges the domain and range of \\(f\\): the outputs of \\(f\\) are exactly the inputs the inverse accepts." }, { stepNumber: 5, description: "Apply the rule to the domain of f-inverse.", workingLatex: "\\text{dom}(f^{-1}) = \\text{range}(f) = \\{x : x \\ge 2\\}", explanation: "The domain of \\(f^{-1}\\) is the range of \\(f\\), namely \\(x \\ge 2\\)." }, { stepNumber: 6, description: "Apply the rule to the range of f-inverse.", workingLatex: "\\text{range}(f^{-1}) = \\text{dom}(f) = \\{y : y \\ge 0\\}", explanation: "The range of \\(f^{-1}\\) is the original domain \\(x \\ge 0\\). This is consistent with \\(f^{-1}(x) = \\sqrt{x - 2} \\ge 0\\), the positive square root being taken." } ], finalAnswer: "Domain of \\( f^{-1} \\): \\( x \\ge 2 \\); range of \\( f^{-1} \\): \\( f^{-1}(x) \\ge 0 \\)." } },
  { id: "y2fg4-047", topicRef: "y2fg4", topicTitle: "Inverse Functions 47", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = x^2 - 6x + 11 \\), \\( x \\ge 3 \\). (a) Express \\( f(x) \\) in the form \\( (x - a)^2 + b \\). (b) State the range of \\( f \\). (c) Hence find \\( f^{-1}(x) \\), stating its domain and range.", marks: 7, examStyle: true, yearCreated: 2026, tags: ["inverse", "domain", "range", "completing-the-square"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): write the squared bracket.", workingLatex: "(x - 3)^2 = x^2 - 6x + 9", explanation: "Halve the coefficient of \\(x\\), which is \\(-6\\), to get \\(-3\\); the completed-square bracket is therefore \\((x-3)^2\\), expanding as shown." }, { stepNumber: 2, description: "Adjust the constant term.", workingLatex: "x^2 - 6x + 11 = (x - 3)^2 - 9 + 11 = (x - 3)^2 + 2", explanation: "The bracket supplies a constant \\(+9\\), but the function needs \\(+11\\), so add \\(11 - 9 = 2\\) to compensate." }, { stepNumber: 3, description: "Part (b): bound the squared term on the domain.", workingLatex: "x \\ge 3 \\Rightarrow x - 3 \\ge 0 \\Rightarrow (x - 3)^2 \\ge 0", explanation: "The vertex of the parabola is at \\(x = 3\\), which is the left endpoint of the domain, so the squared bracket is never negative on \\(x \\ge 3\\)." }, { stepNumber: 4, description: "State the range of f.", workingLatex: "f(x) = (x-3)^2 + 2 \\ge 2 \\Rightarrow \\text{range}(f) = \\{y : y \\ge 2\\}", explanation: "\\(f\\) attains its minimum value \\(2\\) at \\(x = 3\\) and increases thereafter, so the outputs run from \\(2\\) upwards." }, { stepNumber: 5, description: "Part (c): isolate the squared bracket.", workingLatex: "y = (x-3)^2 + 2 \\Rightarrow (x-3)^2 = y - 2", explanation: "Set \\(y = f(x)\\) and subtract \\(2\\) from both sides to leave the squared bracket alone." }, { stepNumber: 6, description: "Square-root and choose the correct sign.", workingLatex: "x - 3 = \\pm\\sqrt{y - 2}; \\quad x \\ge 3 \\Rightarrow x - 3 \\ge 0 \\Rightarrow x - 3 = +\\sqrt{y - 2}", explanation: "Square-rooting gives two signs, but the domain \\(x \\ge 3\\) forces \\(x - 3 \\ge 0\\), so only the positive root is valid — taking the negative root is a common error here." }, { stepNumber: 7, description: "Make x the subject and swap variables.", workingLatex: "x = 3 + \\sqrt{y - 2} \\Rightarrow f^{-1}(x) = 3 + \\sqrt{x - 2}", explanation: "Add \\(3\\) to both sides, then relabel \\(y \\to x\\) to express the inverse as a function of its own input." }, { stepNumber: 8, description: "State the domain and range of f-inverse.", workingLatex: "\\text{dom}(f^{-1}) = \\text{range}(f) = \\{x : x \\ge 2\\},\\quad \\text{range}(f^{-1}) = \\text{dom}(f) = \\{y : y \\ge 3\\}", explanation: "The domain of \\(f^{-1}\\) equals the range of \\(f\\) from part (b), and its range equals \\(f\\)'s domain \\(x \\ge 3\\) — consistent with \\(3 + \\sqrt{x-2} \\ge 3\\)." } ], finalAnswer: "(a) \\( f(x) = (x-3)^2 + 2 \\). (b) Range of \\( f \\): \\( f(x) \\ge 2 \\). (c) \\( f^{-1}(x) = 3 + \\sqrt{x - 2} \\), domain \\( x \\ge 2 \\), range \\( f^{-1}(x) \\ge 3 \\)." } },
  { id: "y2fg4-048", topicRef: "y2fg4", topicTitle: "Inverse Functions 48", difficulty: "Standard", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = \\ln x \\), \\( x > 0 \\). (a) State the range of \\( f \\). (b) Hence state the domain and range of \\( f^{-1} \\), and write down \\( f^{-1}(x) \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["inverse", "log", "domain", "range"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): examine the behaviour of ln x near 0.", workingLatex: "\\ln x \\to -\\infty \\text{ as } x \\to 0^+", explanation: "As the input approaches \\(0\\) from the positive side, the natural logarithm decreases without bound — there is no smallest output." }, { stepNumber: 2, description: "Examine the behaviour as x grows large.", workingLatex: "\\ln x \\to +\\infty \\text{ as } x \\to \\infty", explanation: "As the input grows without bound, the logarithm also increases without bound — there is no largest output." }, { stepNumber: 3, description: "State the range of f.", workingLatex: "\\text{range}(f) = \\mathbb{R}", explanation: "Being continuous and strictly increasing, \\(\\ln\\) takes every real value exactly once on \\((0, \\infty)\\), so its range is all of \\(\\mathbb{R}\\)." }, { stepNumber: 4, description: "Part (b): apply the domain/range swap rule.", workingLatex: "\\text{dom}(f^{-1}) = \\text{range}(f) = \\mathbb{R},\\qquad \\text{range}(f^{-1}) = \\text{dom}(f) = (0, \\infty)", explanation: "The inverse interchanges domain and range, so every real number is a valid input to \\(f^{-1}\\) and its outputs are strictly positive." }, { stepNumber: 5, description: "Write down the inverse by exponentiating.", workingLatex: "y = \\ln x \\iff x = e^y \\Rightarrow f^{-1}(x) = e^x", explanation: "Exponentiating both sides undoes the logarithm; \\(e^x\\) is defined for all real \\(x\\) and is always positive, confirming the domain and range stated above." } ], finalAnswer: "(a) Range of \\( f \\): all real values. (b) \\( f^{-1}(x) = e^x \\), with domain \\( x \\in \\mathbb{R} \\) and range \\( f^{-1}(x) > 0 \\)." } },
  { id: "y2fg4-049", topicRef: "y2fg4", topicTitle: "Inverse Functions 49", difficulty: "Standard", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = e^x + 1 \\), \\( x \\in \\mathbb{R} \\). State the domain and range of \\( f^{-1} \\), justifying your answer.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["inverse", "exp", "domain", "range"], workedSolution: { steps: [ { stepNumber: 1, description: "Bound the exponential term.", workingLatex: "e^x > 0 \\text{ for all } x \\in \\mathbb{R}", explanation: "The exponential function is strictly positive everywhere — it never reaches \\(0\\)." }, { stepNumber: 2, description: "Deduce a lower bound for f.", workingLatex: "f(x) = e^x + 1 > 0 + 1 = 1", explanation: "Adding \\(1\\) to a strictly positive quantity gives a value strictly greater than \\(1\\); as \\(x \\to -\\infty\\), \\(f\\) approaches \\(1\\) from above but never equals it." }, { stepNumber: 3, description: "State the range of f.", workingLatex: "\\text{range}(f) = (1, \\infty)", explanation: "As \\(x \\to \\infty\\), \\(f \\to \\infty\\); combined with the lower bound, \\(f\\) takes every value strictly above \\(1\\)." }, { stepNumber: 4, description: "State the domain/range swap rule.", workingLatex: "\\text{dom}(f^{-1}) = \\text{range}(f),\\qquad \\text{range}(f^{-1}) = \\text{dom}(f)", explanation: "The inverse function reverses the roles of inputs and outputs." }, { stepNumber: 5, description: "Read off the domain of f-inverse.", workingLatex: "\\text{dom}(f^{-1}) = \\text{range}(f) = (1, \\infty)", explanation: "The domain of the inverse equals the range of \\(f\\), namely \\(x > 1\\)." }, { stepNumber: 6, description: "Read off the range of f-inverse.", workingLatex: "\\text{range}(f^{-1}) = \\text{dom}(f) = \\mathbb{R}", explanation: "The range of the inverse equals the original domain, all of \\(\\mathbb{R}\\). This is consistent with \\(f^{-1}(x) = \\ln(x - 1)\\), which is defined precisely when \\(x > 1\\)." } ], finalAnswer: "Domain of \\( f^{-1} \\): \\( x > 1 \\); range of \\( f^{-1} \\): all real values." } },
  { id: "y2fg4-050", topicRef: "y2fg4", topicTitle: "Inverse Functions 50", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = \\dfrac{2x + 1}{x - 3} \\), \\( x > 3 \\). (a) Show that \\( f(x) \\) can be written as \\( 2 + \\dfrac{7}{x - 3} \\). (b) Hence determine the range of \\( f \\). (c) State the domain and range of \\( f^{-1} \\), giving full justification.", marks: 7, examStyle: true, yearCreated: 2026, tags: ["inverse", "domain", "range", "rational"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): split the numerator using the denominator.", workingLatex: "2x + 1 = 2(x - 3) + 7", explanation: "Write the numerator as a multiple of the denominator plus a remainder: \\(2(x-3) = 2x - 6\\), and \\(2x + 1 - (2x - 6) = 7\\)." }, { stepNumber: 2, description: "Rewrite the fraction term by term.", workingLatex: "\\frac{2x + 1}{x - 3} = \\frac{2(x - 3) + 7}{x - 3} = 2 + \\frac{7}{x - 3}", explanation: "Splitting the single fraction over the common denominator separates the constant part \\(2\\) from the proper fraction \\(\\tfrac{7}{x-3}\\)." }, { stepNumber: 3, description: "Part (b): sign of the fraction on the domain.", workingLatex: "x > 3 \\Rightarrow x - 3 > 0 \\Rightarrow \\frac{7}{x - 3} > 0", explanation: "On the domain \\(x > 3\\) the denominator is strictly positive, so the fraction \\(\\tfrac{7}{x-3}\\) is strictly positive." }, { stepNumber: 4, description: "Find the limiting values of the fraction.", workingLatex: "\\text{as } x \\to 3^+,\\ \\tfrac{7}{x-3} \\to +\\infty;\\qquad \\text{as } x \\to \\infty,\\ \\tfrac{7}{x-3} \\to 0^+", explanation: "Near \\(x = 3\\) the denominator is tiny and positive so the fraction is huge; for large \\(x\\) the fraction shrinks towards \\(0\\) but stays positive." }, { stepNumber: 5, description: "State the range of f.", workingLatex: "f(x) = 2 + \\tfrac{7}{x-3} > 2 \\Rightarrow \\text{range}(f) = (2, \\infty)", explanation: "The fraction ranges over \\((0, \\infty)\\), so \\(f = 2 + (\\text{that})\\) takes every value above \\(2\\) but never equals \\(2\\)." }, { stepNumber: 6, description: "Part (c): state the domain/range swap rule.", workingLatex: "\\text{dom}(f^{-1}) = \\text{range}(f),\\qquad \\text{range}(f^{-1}) = \\text{dom}(f)", explanation: "The inverse interchanges the domain and range of \\(f\\)." }, { stepNumber: 7, description: "Read off the domain of f-inverse.", workingLatex: "\\text{dom}(f^{-1}) = \\text{range}(f) = (2, \\infty)", explanation: "The domain of the inverse equals the range of \\(f\\) found in part (b), namely \\(x > 2\\)." }, { stepNumber: 8, description: "Read off the range of f-inverse and verify.", workingLatex: "\\text{range}(f^{-1}) = \\text{dom}(f) = (3, \\infty);\\quad y = 2 + \\tfrac{7}{x-3} \\Rightarrow x = 3 + \\tfrac{7}{y-2}", explanation: "The range of the inverse is the original domain \\(x > 3\\). Rearranging \\(y = f(x)\\) confirms \\(f^{-1}(x) = 3 + \\tfrac{7}{x-2}\\), whose values all exceed \\(3\\)." } ], finalAnswer: "(a) \\( f(x) = 2 + \\dfrac{7}{x-3} \\). (b) Range of \\( f \\): \\( f(x) > 2 \\). (c) Domain of \\( f^{-1} \\): \\( x > 2 \\); range of \\( f^{-1} \\): \\( f^{-1}(x) > 3 \\)." } },
  // ── Self-inverse proofs ────
  { id: "y2fg4-051", topicRef: "y2fg4", topicTitle: "Inverse Functions 51", difficulty: "Standard", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = 1 - x \\), \\( x \\in \\mathbb{R} \\). (a) Show that \\( f \\) is self-inverse. (b) State what this tells you about the graph of \\( y = f(x) \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["inverse", "self-inverse", "proof"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): state the self-inverse criterion.", workingLatex: "f \\text{ is self-inverse} \\iff ff(x) = x \\text{ for all } x", explanation: "If applying \\(f\\) twice returns the original input for every \\(x\\), then \\(f\\) is its own inverse — this is the condition we must verify." }, { stepNumber: 2, description: "Substitute the inner output into f.", workingLatex: "ff(x) = f(1 - x) = 1 - (1 - x)", explanation: "The inner application gives \\(f(x) = 1 - x\\); substituting this back into \\(f\\), which subtracts its input from \\(1\\), produces \\(1 - (1 - x)\\)." }, { stepNumber: 3, description: "Expand the bracket.", workingLatex: "1 - (1 - x) = 1 - 1 + x", explanation: "Distribute the minus sign across the bracket — a common slip is to forget that the \\(-x\\) becomes \\(+x\\)." }, { stepNumber: 4, description: "Simplify to x.", workingLatex: "1 - 1 + x = x", explanation: "The constants cancel, leaving exactly \\(x\\)." }, { stepNumber: 5, description: "Conclude part (a).", workingLatex: "ff(x) = x \\text{ for all } x \\Rightarrow f^{-1} = f", explanation: "The criterion holds for every real \\(x\\), so \\(f\\) is self-inverse." }, { stepNumber: 6, description: "Part (b): interpret geometrically.", workingLatex: "f^{-1} = f \\Rightarrow y = f(x) \\text{ symmetric in } y = x", explanation: "The graph of \\(f^{-1}\\) is the reflection of \\(y = f(x)\\) in the line \\(y = x\\). Since \\(f^{-1} = f\\), the graph is its own reflection, i.e. it is symmetrical about the line \\(y = x\\)." } ], finalAnswer: "(a) \\( ff(x) = x \\), so \\( f^{-1} = f \\). (b) The graph of \\( y = f(x) \\) is symmetrical about the line \\( y = x \\)." } },
  { id: "y2fg4-052", topicRef: "y2fg4", topicTitle: "Inverse Functions 52", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = \\dfrac{x}{x - 1} \\), \\( x \\ne 1 \\). (a) Show that \\( f \\) is self-inverse. (b) Hence write down the value of \\( f^{-1}(4) \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["inverse", "self-inverse", "proof"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): set up f(f(x)).", workingLatex: "ff(x) = f\\!\\left(\\frac{x}{x-1}\\right) = \\frac{\\frac{x}{x-1}}{\\frac{x}{x-1} - 1}", explanation: "Apply \\(f\\) to the inner output \\(\\tfrac{x}{x-1}\\) by substituting it into both the numerator slot and the denominator slot of \\(f\\)." }, { stepNumber: 2, description: "Combine the denominator over a common denominator.", workingLatex: "\\frac{x}{x-1} - 1 = \\frac{x - (x - 1)}{x - 1}", explanation: "Write \\(1\\) as \\(\\tfrac{x-1}{x-1}\\) so the two terms share the denominator \\(x - 1\\) and can be subtracted." }, { stepNumber: 3, description: "Simplify the denominator.", workingLatex: "\\frac{x - (x - 1)}{x - 1} = \\frac{1}{x - 1}", explanation: "The numerator simplifies as \\(x - x + 1 = 1\\), giving the compact form \\(\\tfrac{1}{x-1}\\)." }, { stepNumber: 4, description: "Divide the two fractions.", workingLatex: "ff(x) = \\frac{x/(x-1)}{1/(x-1)} = \\frac{x}{x-1} \\cdot (x - 1)", explanation: "Dividing by a fraction means multiplying by its reciprocal, so we multiply by \\(x - 1\\)." }, { stepNumber: 5, description: "Cancel and conclude part (a).", workingLatex: "\\frac{x}{x-1} \\cdot (x - 1) = x \\Rightarrow f^{-1} = f", explanation: "The \\((x-1)\\) factors cancel to leave \\(x\\); since \\(ff(x) = x\\) for all valid \\(x\\), \\(f\\) is self-inverse." }, { stepNumber: 6, description: "Part (b): evaluate f-inverse at 4.", workingLatex: "f^{-1}(4) = f(4) = \\frac{4}{4 - 1} = \\frac{4}{3}", explanation: "Since \\(f\\) is self-inverse, \\(f^{-1}\\) equals \\(f\\), so \\(f^{-1}(4)\\) is just \\(f(4)\\) — no separate inversion is needed." } ], finalAnswer: "(a) \\( ff(x) = x \\), so \\( f^{-1} = f \\). (b) \\( f^{-1}(4) = \\dfrac{4}{3} \\)." } },
  { id: "y2fg4-053", topicRef: "y2fg4", topicTitle: "Inverse Functions 53", difficulty: "Foundation", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = \\dfrac{1}{x} \\), \\( x \\ne 0 \\). Show that \\( f \\) is self-inverse.", marks: 2, examStyle: false, yearCreated: 2026, tags: ["inverse", "self-inverse", "proof"], workedSolution: { steps: [ { stepNumber: 1, description: "Substitute the inner output into f.", workingLatex: "ff(x) = f\\!\\left(\\frac{1}{x}\\right) = \\frac{1}{1/x}", explanation: "The inner application gives \\(f(x) = \\tfrac{1}{x}\\); substituting this back into \\(f\\), which takes the reciprocal of its input, produces \\(\\tfrac{1}{1/x}\\)." }, { stepNumber: 2, description: "Simplify the compound fraction.", workingLatex: "\\frac{1}{1/x} = 1 \\cdot \\frac{x}{1} = x", explanation: "Dividing \\(1\\) by \\(\\tfrac{1}{x}\\) is the same as multiplying by its reciprocal \\(x\\)." }, { stepNumber: 3, description: "Conclude.", workingLatex: "ff(x) = x \\Rightarrow f^{-1} = f", explanation: "Applying \\(f\\) twice returns the input for every \\(x \\ne 0\\), so \\(f\\) is self-inverse: reciprocation is undone by reciprocation." } ], finalAnswer: "\\( ff(x) = x \\), so \\( f^{-1} = f \\). \\( f \\) is self-inverse. \\( \\blacksquare \\)" } },
  { id: "y2fg4-054", topicRef: "y2fg4", topicTitle: "Inverse Functions 54", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = \\dfrac{x + 1}{x - 1} \\), \\( x \\ne 1 \\). (a) Determine whether \\( f \\) is self-inverse. (b) Hence, or otherwise, solve the equation \\( f(x) = x \\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["inverse", "self-inverse", "proof"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): set up f(f(x)).", workingLatex: "ff(x) = f\\!\\left(\\frac{x+1}{x-1}\\right) = \\frac{\\frac{x+1}{x-1} + 1}{\\frac{x+1}{x-1} - 1}", explanation: "Substitute the inner output \\(\\tfrac{x+1}{x-1}\\) into \\(f\\), replacing the \\(x\\) in both the numerator and the denominator." }, { stepNumber: 2, description: "Combine the numerator over a common denominator.", workingLatex: "\\frac{x+1}{x-1} + 1 = \\frac{(x+1) + (x-1)}{x-1}", explanation: "Write \\(1\\) as \\(\\tfrac{x-1}{x-1}\\) so both terms share the denominator \\(x - 1\\)." }, { stepNumber: 3, description: "Simplify the numerator.", workingLatex: "\\frac{(x+1) + (x-1)}{x-1} = \\frac{2x}{x-1}", explanation: "Adding the brackets: \\((x+1) + (x-1) = 2x\\)." }, { stepNumber: 4, description: "Combine the denominator over a common denominator.", workingLatex: "\\frac{x+1}{x-1} - 1 = \\frac{(x+1) - (x-1)}{x-1} = \\frac{2}{x-1}", explanation: "Subtracting the brackets: \\((x+1) - (x-1) = 2\\); take care with the minus sign across \\((x-1)\\)." }, { stepNumber: 5, description: "Divide and conclude part (a).", workingLatex: "ff(x) = \\frac{2x/(x-1)}{2/(x-1)} = \\frac{2x}{2} = x \\Rightarrow f^{-1} = f", explanation: "The \\((x-1)\\) factors cancel and \\(\\tfrac{2x}{2} = x\\), so \\(ff(x) = x\\) for all valid \\(x\\); hence \\(f\\) is self-inverse." }, { stepNumber: 6, description: "Part (b): clear the fraction in f(x) = x.", workingLatex: "\\frac{x+1}{x-1} = x \\Rightarrow x + 1 = x(x - 1)", explanation: "Multiply both sides by \\(x - 1\\), valid because \\(x \\ne 1\\), to remove the denominator." }, { stepNumber: 7, description: "Expand and rearrange into a quadratic.", workingLatex: "x + 1 = x^2 - x \\Rightarrow x^2 - 2x - 1 = 0", explanation: "Expand the right-hand side and bring every term to one side to obtain a quadratic in standard form." }, { stepNumber: 8, description: "Solve the quadratic with the formula.", workingLatex: "x = \\frac{2 \\pm \\sqrt{(-2)^2 - 4(1)(-1)}}{2} = \\frac{2 \\pm \\sqrt{8}}{2} = 1 \\pm \\sqrt{2}", explanation: "Apply the quadratic formula with \\(a = 1, b = -2, c = -1\\); \\(\\sqrt{8} = 2\\sqrt{2}\\), so the roots simplify to \\(1 \\pm \\sqrt{2}\\). These are the fixed points where the graph meets the line \\(y = x\\)." } ], finalAnswer: "(a) Yes — \\( ff(x) = x \\), so \\( f^{-1} = f \\). (b) \\( x = 1 + \\sqrt{2} \\) or \\( x = 1 - \\sqrt{2} \\)." } },
  { id: "y2fg4-055", topicRef: "y2fg4", topicTitle: "Inverse Functions 55", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = \\dfrac{ax + b}{cx - a} \\), where \\( a, b, c \\) are constants with \\( c \\ne 0 \\) and \\( a^2 + bc \\ne 0 \\). (a) Show that \\( f \\) is self-inverse for all such \\( a, b, c \\). (b) State, in terms of \\( a \\) and \\( c \\), the value of \\( x \\) that must be excluded from the domain.", marks: 7, examStyle: true, yearCreated: 2026, tags: ["inverse", "self-inverse", "proof"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): set up f(f(x)).", workingLatex: "ff(x) = f\\!\\left(\\frac{ax+b}{cx-a}\\right) = \\frac{a\\cdot\\frac{ax+b}{cx-a} + b}{c\\cdot\\frac{ax+b}{cx-a} - a}", explanation: "Substitute the inner output \\(\\tfrac{ax+b}{cx-a}\\) into every occurrence of \\(x\\) in \\(f\\)." }, { stepNumber: 2, description: "Combine the numerator over a common denominator.", workingLatex: "a\\cdot\\frac{ax+b}{cx-a} + b = \\frac{a(ax+b) + b(cx-a)}{cx-a}", explanation: "Write \\(b\\) as \\(\\tfrac{b(cx-a)}{cx-a}\\) so both terms share the denominator \\(cx - a\\)." }, { stepNumber: 3, description: "Expand and simplify the numerator.", workingLatex: "\\frac{a(ax+b) + b(cx-a)}{cx-a} = \\frac{a^2x + ab + bcx - ab}{cx-a} = \\frac{(a^2 + bc)x}{cx-a}", explanation: "Expanding gives \\(a^2x + ab\\) and \\(bcx - ab\\); the \\(+ab\\) and \\(-ab\\) cancel, leaving \\((a^2 + bc)x\\)." }, { stepNumber: 4, description: "Combine the denominator over a common denominator.", workingLatex: "c\\cdot\\frac{ax+b}{cx-a} - a = \\frac{c(ax+b) - a(cx-a)}{cx-a}", explanation: "Write \\(a\\) as \\(\\tfrac{a(cx-a)}{cx-a}\\) so both terms share the denominator \\(cx - a\\)." }, { stepNumber: 5, description: "Expand and simplify the denominator.", workingLatex: "\\frac{c(ax+b) - a(cx-a)}{cx-a} = \\frac{acx + bc - acx + a^2}{cx-a} = \\frac{a^2 + bc}{cx-a}", explanation: "Expanding gives \\(acx + bc\\) and \\(acx - a^2\\); the \\(acx\\) terms cancel, leaving the constant \\(a^2 + bc\\)." }, { stepNumber: 6, description: "Divide numerator by denominator.", workingLatex: "ff(x) = \\frac{(a^2 + bc)x/(cx-a)}{(a^2 + bc)/(cx-a)} = \\frac{(a^2 + bc)x}{a^2 + bc}", explanation: "Dividing the two fractions, the common \\((cx-a)\\) factors cancel." }, { stepNumber: 7, description: "Cancel and conclude part (a).", workingLatex: "ff(x) = \\frac{(a^2 + bc)x}{a^2 + bc} = x \\quad (\\text{since } a^2 + bc \\ne 0)", explanation: "The condition \\(a^2 + bc \\ne 0\\) lets us cancel that factor, giving \\(ff(x) = x\\); hence \\(f\\) is self-inverse for every admissible \\(a, b, c\\)." }, { stepNumber: 8, description: "Part (b): identify the excluded value.", workingLatex: "cx - a = 0 \\Rightarrow x = \\frac{a}{c}", explanation: "\\(f\\) is undefined where its denominator vanishes; with \\(c \\ne 0\\), the value \\(x = \\tfrac{a}{c}\\) must be excluded from the domain." } ], finalAnswer: "(a) \\( ff(x) = \\dfrac{(a^2+bc)x}{a^2+bc} = x \\) since \\( a^2 + bc \\ne 0 \\), so \\( f^{-1} = f \\). (b) The value \\( x = \\dfrac{a}{c} \\) must be excluded." } },
  { id: "y2fg4-056", topicRef: "y2fg4", topicTitle: "Inverse Functions 56", difficulty: "Foundation", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = c - x \\), \\( x \\in \\mathbb{R} \\), where \\( c \\) is a constant. Show that \\( f \\) is self-inverse for every value of \\( c \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["inverse", "self-inverse", "proof"], workedSolution: { steps: [ { stepNumber: 1, description: "Substitute the inner output into f.", workingLatex: "ff(x) = f(c - x) = c - (c - x)", explanation: "The inner application gives \\(f(x) = c - x\\); substituting this back into \\(f\\), which subtracts its input from \\(c\\), produces \\(c - (c - x)\\)." }, { stepNumber: 2, description: "Expand the bracket.", workingLatex: "c - (c - x) = c - c + x", explanation: "Distribute the minus sign across the bracket — the \\(-x\\) inside becomes \\(+x\\)." }, { stepNumber: 3, description: "Simplify to x.", workingLatex: "c - c + x = x", explanation: "The \\(c\\) terms cancel for any value of \\(c\\), leaving exactly \\(x\\)." }, { stepNumber: 4, description: "Conclude.", workingLatex: "ff(x) = x \\text{ for every constant } c \\Rightarrow f^{-1} = f", explanation: "Since the result holds regardless of the value of \\(c\\), \\(f\\) is self-inverse for every \\(c\\). Geometrically, the line \\(y = c - x\\) is symmetrical about \\(y = x\\)." } ], finalAnswer: "\\( ff(x) = x \\) for every \\( c \\), so \\( f^{-1} = f \\). \\( \\blacksquare \\)" } },
  { id: "y2fg4-057", topicRef: "y2fg4", topicTitle: "Inverse Functions 57", difficulty: "Foundation", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = 2 - x \\), \\( x \\in \\mathbb{R} \\). Determine whether \\( f \\) is self-inverse, justifying your answer.", marks: 2, examStyle: false, yearCreated: 2026, tags: ["inverse", "self-inverse"], workedSolution: { steps: [ { stepNumber: 1, description: "State the self-inverse test.", workingLatex: "f \\text{ self-inverse} \\iff ff(x) = x \\text{ for all } x", explanation: "\\(f\\) is self-inverse exactly when applying it twice returns the original input for every \\(x\\)." }, { stepNumber: 2, description: "Substitute the inner output into f.", workingLatex: "ff(x) = f(2 - x) = 2 - (2 - x)", explanation: "The inner application gives \\(f(x) = 2 - x\\); substituting this back into \\(f\\), which subtracts its input from \\(2\\), produces \\(2 - (2 - x)\\)." }, { stepNumber: 3, description: "Expand and simplify.", workingLatex: "2 - (2 - x) = 2 - 2 + x = x", explanation: "Distribute the minus sign and cancel the constants, leaving exactly \\(x\\)." }, { stepNumber: 4, description: "Conclude.", workingLatex: "ff(x) = x \\Rightarrow f^{-1} = f", explanation: "The test is satisfied for all \\(x\\), so \\(f\\) is self-inverse. It is the special case of \\(c - x\\) with \\(c = 2\\)." } ], finalAnswer: "Yes — \\( ff(x) = x \\), so \\( f \\) is self-inverse." } },
  // ── f(f^{-1}(x)) = x verifications ────
  { id: "y2fg4-058", topicRef: "y2fg4", topicTitle: "Inverse Functions 58", difficulty: "Standard", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = 2x + 3 \\), \\( x \\in \\mathbb{R} \\). (a) Find \\( f^{-1}(x) \\), stating its domain. (b) Verify that \\( f(f^{-1}(x)) = x \\) for all \\( x \\in \\mathbb{R} \\). (c) Explain what part (b) tells you about the relationship between \\( f \\) and \\( f^{-1} \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["inverse", "verify"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): set \\(y = f(x)\\).", workingLatex: "y = 2x + 3", explanation: "Write the output of \\(f\\) as a new variable \\(y\\) so the equation can be rearranged to make \\(x\\) the subject." }, { stepNumber: 2, description: "Part (a): isolate the \\(x\\)-term.", workingLatex: "y - 3 = 2x", explanation: "Subtract 3 from both sides, undoing the \\(+3\\) in the rule for \\(f\\)." }, { stepNumber: 3, description: "Part (a): solve for \\(x\\).", workingLatex: "x = \\tfrac{y - 3}{2}", explanation: "Divide both sides by 2, undoing the \\(\\times 2\\); this completes the rearrangement." }, { stepNumber: 4, description: "Part (a): swap variables to write the inverse.", workingLatex: "f^{-1}(x) = \\tfrac{x - 3}{2}", explanation: "Relabel \\(y \\to x\\) so the inverse is expressed as a function of its own input." }, { stepNumber: 5, description: "Part (a): state the domain of the inverse.", workingLatex: "f^{-1}(x) = \\tfrac{x - 3}{2}, \\quad x \\in \\mathbb{R}", explanation: "The domain of \\(f^{-1}\\) is the range of \\(f\\); since the linear map \\(f\\) sends \\(\\mathbb{R}\\) onto \\(\\mathbb{R}\\), the inverse is defined for all real \\(x\\)." }, { stepNumber: 6, description: "Part (b): substitute \\(f^{-1}(x)\\) into \\(f\\).", workingLatex: "f(f^{-1}(x)) = 2 \\cdot \\tfrac{x - 3}{2} + 3", explanation: "Replace the input of \\(f\\) by the whole expression for \\(f^{-1}(x)\\); apply the rule \\(f(\\text{input}) = 2(\\text{input}) + 3\\)." }, { stepNumber: 7, description: "Part (b): cancel the factor of 2.", workingLatex: "2 \\cdot \\tfrac{x - 3}{2} + 3 = (x - 3) + 3", explanation: "The multiplier 2 cancels with the denominator 2, leaving \\((x - 3)\\). A common slip is to cancel only part of the numerator — the whole bracket survives." }, { stepNumber: 8, description: "Part (b): collect the constants.", workingLatex: "(x - 3) + 3 = x", explanation: "The \\(-3\\) and \\(+3\\) cancel, leaving \\(x\\) — this confirms \\(f(f^{-1}(x)) = x\\) for all real \\(x\\)." }, { stepNumber: 9, description: "Part (c): interpret the result.", workingLatex: "f(f^{-1}(x)) = x \\;\\;\\text{for all } x \\in \\mathbb{R}", explanation: "Applying \\(f\\) after \\(f^{-1}\\) returns the original input, so the two functions are mutually inverse — each exactly undoes the effect of the other, and their composition is the identity function." } ], finalAnswer: "(a) \\( f^{-1}(x) = \\tfrac{x - 3}{2}, \\; x \\in \\mathbb{R} \\). (b) \\( f(f^{-1}(x)) = x \\). \\(\\blacksquare\\) (c) \\(f\\) and \\(f^{-1}\\) undo each other — composing them gives the identity." } },
  { id: "y2fg4-059", topicRef: "y2fg4", topicTitle: "Inverse Functions 59", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = \\dfrac{3x + 4}{x - 2} \\), \\( x \\in \\mathbb{R}, \\; x \\neq 2 \\). (a) Find \\( f^{-1}(x) \\) and state the value of \\(x\\) that must be excluded from its domain. (b) By substituting your expression for \\( f^{-1}(x) \\) into \\( f \\), verify in full algebraic detail that \\( f(f^{-1}(x)) = x \\). (c) State, with a reason, what your answer to (a) reveals about \\( f \\).", marks: 8, examStyle: true, yearCreated: 2026, tags: ["inverse", "verify", "self-inverse"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): set \\(y = f(x)\\).", workingLatex: "y = \\tfrac{3x + 4}{x - 2}", explanation: "Write the output as \\(y\\); the goal is to rearrange this rational equation to make \\(x\\) the subject." }, { stepNumber: 2, description: "Part (a): cross-multiply to clear the fraction.", workingLatex: "y(x - 2) = 3x + 4", explanation: "Multiply both sides by \\((x - 2)\\) so \\(x\\) no longer sits in a denominator." }, { stepNumber: 3, description: "Part (a): expand the left-hand side.", workingLatex: "xy - 2y = 3x + 4", explanation: "Distribute \\(y\\) across the bracket so every \\(x\\)-term is visible for collecting." }, { stepNumber: 4, description: "Part (a): gather \\(x\\)-terms on one side.", workingLatex: "xy - 3x = 2y + 4", explanation: "Move \\(3x\\) to the left and \\(-2y\\) to the right so all terms containing \\(x\\) are together." }, { stepNumber: 5, description: "Part (a): factor out \\(x\\).", workingLatex: "x(y - 3) = 2y + 4", explanation: "Take the common factor \\(x\\) outside; this is the key move that lets us divide to isolate \\(x\\)." }, { stepNumber: 6, description: "Part (a): solve for \\(x\\) and write the inverse.", workingLatex: "x = \\tfrac{2y + 4}{y - 3} \\;\\Rightarrow\\; f^{-1}(x) = \\tfrac{2x + 4}{x - 3}", explanation: "Divide by \\((y - 3)\\), then swap \\(y \\to x\\) to express the inverse as a function of its input." }, { stepNumber: 7, description: "Part (a): state the excluded value.", workingLatex: "x \\neq 3", explanation: "The denominator \\(x - 3\\) vanishes at \\(x = 3\\), so \\(x = 3\\) must be excluded from the domain of \\(f^{-1}\\) — it is the value \\(f\\) can never output." }, { stepNumber: 8, description: "Part (b): substitute \\(f^{-1}(x)\\) into \\(f\\).", workingLatex: "f(f^{-1}(x)) = \\dfrac{3 \\cdot \\tfrac{2x + 4}{x - 3} + 4}{\\tfrac{2x + 4}{x - 3} - 2}", explanation: "Place the expression for \\(f^{-1}(x)\\) into both the numerator and the denominator of the rule for \\(f\\)." }, { stepNumber: 9, description: "Part (b): multiply top and bottom by \\((x - 3)\\).", workingLatex: "f(f^{-1}(x)) = \\dfrac{3(2x + 4) + 4(x - 3)}{(2x + 4) - 2(x - 3)}", explanation: "Multiplying numerator and denominator by the same factor \\((x - 3)\\) flattens the compound fraction without changing its value." }, { stepNumber: 10, description: "Part (b): expand the numerator.", workingLatex: "3(2x + 4) + 4(x - 3) = 6x + 12 + 4x - 12 = 10x", explanation: "Distribute both brackets; the constants \\(+12\\) and \\(-12\\) cancel, leaving \\(10x\\)." }, { stepNumber: 11, description: "Part (b): expand the denominator.", workingLatex: "(2x + 4) - 2(x - 3) = 2x + 4 - 2x + 6 = 10", explanation: "Distribute the \\(-2\\); the \\(2x\\) terms cancel, leaving the constant 10. A common slip is sign error on \\(-2 \\times (-3) = +6\\)." }, { stepNumber: 12, description: "Part (b): simplify the quotient.", workingLatex: "f(f^{-1}(x)) = \\tfrac{10x}{10} = x", explanation: "The verification holds: composing \\(f\\) with \\(f^{-1}\\) returns \\(x\\)." }, { stepNumber: 13, description: "Part (c): compare the two rules.", workingLatex: "f^{-1}(x) = \\tfrac{2x + 4}{x - 3} \\;\\neq\\; \\tfrac{3x + 4}{x - 2} = f(x)", explanation: "The inverse is a different rule from \\(f\\), so \\(f\\) is not self-inverse — it is a genuine one-to-one rational (Möbius) function whose inverse is a distinct Möbius map." } ], finalAnswer: "(a) \\( f^{-1}(x) = \\tfrac{2x + 4}{x - 3}, \\; x \\neq 3 \\). (b) \\( f(f^{-1}(x)) = \\tfrac{10x}{10} = x \\). \\(\\blacksquare\\) (c) \\(f^{-1} \\neq f\\), so \\(f\\) is one-to-one but not self-inverse." } },
  { id: "y2fg4-060", topicRef: "y2fg4", topicTitle: "Inverse Functions 60", difficulty: "Foundation", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = e^x \\), \\( x \\in \\mathbb{R} \\). (a) Write down \\( f^{-1}(x) \\) and state its domain. (b) Verify that \\( f(f^{-1}(x)) = x \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["inverse", "verify"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): identify the inverse of the exponential.", workingLatex: "f^{-1}(x) = \\ln x", explanation: "The natural logarithm is defined as the inverse of \\(e^x\\): solving \\(y = e^x\\) for \\(x\\) gives \\(x = \\ln y\\)." }, { stepNumber: 2, description: "Part (a): state the domain of the inverse.", workingLatex: "f^{-1}(x) = \\ln x, \\quad x > 0", explanation: "The range of \\(f(x) = e^x\\) is \\((0, \\infty)\\), and the domain of \\(f^{-1}\\) equals the range of \\(f\\); the logarithm is undefined for \\(x \\le 0\\)." }, { stepNumber: 3, description: "Part (b): substitute \\(f^{-1}(x)\\) into \\(f\\).", workingLatex: "f(f^{-1}(x)) = f(\\ln x) = e^{\\ln x}", explanation: "Apply the rule \\(f(\\text{input}) = e^{\\text{input}}\\) to the output \\(\\ln x\\) of the inverse." }, { stepNumber: 4, description: "Part (b): apply the inverse identity.", workingLatex: "e^{\\ln x} = x \\quad (x > 0)", explanation: "Exponential and natural logarithm are mutual inverses on \\((0, \\infty)\\), so the composition cancels to return the original input \\(x\\)." } ], finalAnswer: "(a) \\( f^{-1}(x) = \\ln x, \\; x > 0 \\). (b) \\( f(f^{-1}(x)) = x \\). \\(\\blacksquare\\)" } },
  { id: "y2fg4-061", topicRef: "y2fg4", topicTitle: "Inverse Functions 61", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = \\dfrac{2x - 1}{x + 3} \\), \\( x \\in \\mathbb{R}, \\; x \\neq -3 \\). (a) Show that \\( f^{-1}(x) = \\dfrac{3x + 1}{2 - x} \\), \\( x \\neq 2 \\). (b) Verify, showing all algebra, that \\( f(f^{-1}(x)) = x \\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["inverse", "verify"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): set \\(y = f(x)\\).", workingLatex: "y = \\tfrac{2x - 1}{x + 3}", explanation: "Write the output as \\(y\\) so the rational equation can be rearranged for \\(x\\)." }, { stepNumber: 2, description: "Part (a): cross-multiply to clear the fraction.", workingLatex: "y(x + 3) = 2x - 1", explanation: "Multiply both sides by \\((x + 3)\\) so \\(x\\) leaves the denominator." }, { stepNumber: 3, description: "Part (a): expand the left-hand side.", workingLatex: "xy + 3y = 2x - 1", explanation: "Distribute \\(y\\) so every \\(x\\)-term is exposed for collecting." }, { stepNumber: 4, description: "Part (a): collect \\(x\\)-terms and factor.", workingLatex: "xy - 2x = -1 - 3y \\;\\Rightarrow\\; x(y - 2) = -1 - 3y", explanation: "Move \\(2x\\) left and \\(3y\\) right, then take out the common factor \\(x\\)." }, { stepNumber: 5, description: "Part (a): solve for \\(x\\).", workingLatex: "x = \\tfrac{-1 - 3y}{y - 2}", explanation: "Divide both sides by \\((y - 2)\\) to isolate \\(x\\)." }, { stepNumber: 6, description: "Part (a): tidy signs and swap variables.", workingLatex: "x = \\tfrac{3y + 1}{2 - y} \\;\\Rightarrow\\; f^{-1}(x) = \\tfrac{3x + 1}{2 - x}, \\quad x \\neq 2", explanation: "Multiplying numerator and denominator by \\(-1\\) gives the required form; swapping \\(y \\to x\\) yields the inverse. The denominator \\(2 - x\\) forces \\(x \\neq 2\\)." }, { stepNumber: 7, description: "Part (b): substitute \\(f^{-1}(x)\\) into \\(f\\).", workingLatex: "f(f^{-1}(x)) = \\dfrac{2 \\cdot \\tfrac{3x + 1}{2 - x} - 1}{\\tfrac{3x + 1}{2 - x} + 3}", explanation: "Place \\(f^{-1}(x)\\) into both the numerator and denominator of the rule for \\(f\\)." }, { stepNumber: 8, description: "Part (b): multiply top and bottom by \\((2 - x)\\).", workingLatex: "f(f^{-1}(x)) = \\dfrac{2(3x + 1) - (2 - x)}{(3x + 1) + 3(2 - x)}", explanation: "Multiplying numerator and denominator by the same factor \\((2 - x)\\) clears the inner fractions without changing the value." }, { stepNumber: 9, description: "Part (b): expand the numerator.", workingLatex: "2(3x + 1) - (2 - x) = 6x + 2 - 2 + x = 7x", explanation: "Distribute the bracket and subtract; the constants \\(+2\\) and \\(-2\\) cancel, leaving \\(7x\\). A common slip is sign error on \\(-(2 - x) = -2 + x\\)." }, { stepNumber: 10, description: "Part (b): expand the denominator.", workingLatex: "(3x + 1) + 3(2 - x) = 3x + 1 + 6 - 3x = 7", explanation: "Distribute the \\(3\\); the \\(\\pm 3x\\) terms cancel, leaving the constant 7." }, { stepNumber: 11, description: "Part (b): simplify the quotient.", workingLatex: "f(f^{-1}(x)) = \\tfrac{7x}{7} = x", explanation: "Verified — \\(f\\) and \\(f^{-1}\\) compose to give the identity." } ], finalAnswer: "(a) \\( f^{-1}(x) = \\tfrac{3x + 1}{2 - x}, \\; x \\neq 2 \\). (b) \\( f(f^{-1}(x)) = \\tfrac{7x}{7} = x \\). \\(\\blacksquare\\)" } },
  // ── Find unknown constants ────
  { id: "y2fg4-062", topicRef: "y2fg4", topicTitle: "Inverse Functions 62", difficulty: "Standard", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = ax + 3 \\), \\( x \\in \\mathbb{R} \\), where \\(a\\) is a constant. (a) Given that \\( f^{-1}(5) = 2 \\), find the value of \\(a\\). (b) Using your value of \\(a\\), write down \\( f^{-1}(x) \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["inverse", "unknown"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): rewrite the inverse condition in terms of \\(f\\).", workingLatex: "f^{-1}(5) = 2 \\;\\iff\\; f(2) = 5", explanation: "By definition, \\(f^{-1}(b) = a\\) is equivalent to \\(f(a) = b\\). Converting avoids having to find \\(f^{-1}\\) explicitly before \\(a\\) is known." }, { stepNumber: 2, description: "Part (a): substitute \\(x = 2\\) into \\(f\\).", workingLatex: "f(2) = 2a + 3", explanation: "Replace \\(x\\) by 2 in the rule \\(f(x) = ax + 3\\); \\(a\\) is still unknown and stays as a symbol." }, { stepNumber: 3, description: "Part (a): set equal to 5.", workingLatex: "2a + 3 = 5", explanation: "Equate the expression for \\(f(2)\\) with the known value 5, giving a linear equation in \\(a\\)." }, { stepNumber: 4, description: "Part (a): solve for \\(a\\).", workingLatex: "2a = 2 \\;\\Rightarrow\\; a = 1", explanation: "Subtract 3 from both sides, then divide by 2." }, { stepNumber: 5, description: "Part (b): write \\(f\\) with the value of \\(a\\) and set \\(y = f(x)\\).", workingLatex: "f(x) = x + 3 \\;\\Rightarrow\\; y = x + 3", explanation: "With \\(a = 1\\) the rule simplifies; introduce \\(y\\) to rearrange for the inverse." }, { stepNumber: 6, description: "Part (b): rearrange and swap variables.", workingLatex: "x = y - 3 \\;\\Rightarrow\\; f^{-1}(x) = x - 3", explanation: "Subtracting 3 undoes adding 3; relabel \\(y \\to x\\) to express the inverse as a function of its input." } ], finalAnswer: "(a) \\( a = 1 \\). (b) \\( f^{-1}(x) = x - 3 \\)." } },
  { id: "y2fg4-063", topicRef: "y2fg4", topicTitle: "Inverse Functions 63", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = \\dfrac{kx + 2}{x - k} \\), \\( x \\in \\mathbb{R}, \\; x \\neq k \\), where \\(k\\) is a constant. (a) Show that \\( f \\) is self-inverse for every real value of \\(k\\). (b) Hence write down \\( f^{-1}(x) \\), and state the geometrical relationship between the graph of \\( y = f(x) \\) and the line \\( y = x \\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["inverse", "self-inverse"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): set up the self-inverse test.", workingLatex: "f \\text{ is self-inverse} \\;\\iff\\; f(f(x)) = x", explanation: "A function is self-inverse exactly when composing it with itself gives the identity; we form \\(f(f(x))\\) and aim to simplify it to \\(x\\)." }, { stepNumber: 2, description: "Part (a): form the composite \\(f(f(x))\\).", workingLatex: "f(f(x)) = \\dfrac{k \\cdot \\tfrac{kx + 2}{x - k} + 2}{\\tfrac{kx + 2}{x - k} - k}", explanation: "Substitute the expression \\(f(x)\\) into both the numerator and denominator of the rule for \\(f\\)." }, { stepNumber: 3, description: "Part (a): multiply top and bottom by \\((x - k)\\).", workingLatex: "f(f(x)) = \\dfrac{k(kx + 2) + 2(x - k)}{(kx + 2) - k(x - k)}", explanation: "Multiplying numerator and denominator by the same factor \\((x - k)\\) flattens the compound fraction without changing its value." }, { stepNumber: 4, description: "Part (a): expand the numerator.", workingLatex: "k(kx + 2) + 2(x - k) = k^2 x + 2k + 2x - 2k = (k^2 + 2)x", explanation: "Distribute both brackets; the \\(\\pm 2k\\) terms cancel, and the remaining \\(x\\)-terms factor as \\((k^2 + 2)x\\)." }, { stepNumber: 5, description: "Part (a): expand the denominator.", workingLatex: "(kx + 2) - k(x - k) = kx + 2 - kx + k^2 = k^2 + 2", explanation: "Distribute the \\(-k\\); the \\(\\pm kx\\) terms cancel, leaving the constant \\(k^2 + 2\\)." }, { stepNumber: 6, description: "Part (a): simplify and conclude.", workingLatex: "f(f(x)) = \\tfrac{(k^2 + 2)x}{k^2 + 2} = x", explanation: "Since \\(k^2 + 2 > 0\\) for every real \\(k\\), the common factor is non-zero and may be cancelled; thus \\(f(f(x)) = x\\) for all \\(k\\), so \\(f\\) is self-inverse." }, { stepNumber: 7, description: "Part (b): state the inverse and the geometric meaning.", workingLatex: "f^{-1}(x) = f(x) = \\tfrac{kx + 2}{x - k}", explanation: "Because \\(f\\) is self-inverse, \\(f^{-1}\\) is the same rule as \\(f\\). Geometrically, the graph of \\(y = f(x)\\) is its own reflection in the line \\(y = x\\), i.e. it is symmetric about \\(y = x\\)." } ], finalAnswer: "(a) \\( f(f(x)) = \\tfrac{(k^2+2)x}{k^2+2} = x \\) for all real \\(k\\), so \\(f\\) is self-inverse. \\(\\blacksquare\\) (b) \\( f^{-1}(x) = \\tfrac{kx + 2}{x - k} \\); the graph of \\(y = f(x)\\) is symmetrical in the line \\(y = x\\)." } },
  { id: "y2fg4-064", topicRef: "y2fg4", topicTitle: "Inverse Functions 64", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = ax + b \\), \\( x \\in \\mathbb{R} \\), where \\(a\\) and \\(b\\) are constants. It is given that \\( f^{-1}(7) = 1 \\) and \\( f^{-1}(-5) = -2 \\). (a) By forming two equations, find the values of \\(a\\) and \\(b\\). (b) Find \\( f^{-1}(x) \\). (c) Verify that \\( f(f^{-1}(x)) = x \\).", marks: 8, examStyle: true, yearCreated: 2026, tags: ["inverse", "unknown", "verify"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): convert each inverse statement into a statement about \\(f\\).", workingLatex: "f^{-1}(7) = 1 \\iff f(1) = 7, \\qquad f^{-1}(-5) = -2 \\iff f(-2) = -5", explanation: "By definition of the inverse, \\(f^{-1}(b) = a\\) is equivalent to \\(f(a) = b\\); this turns the data into ordinary function values." }, { stepNumber: 2, description: "Part (a): substitute \\(x = 1\\) to form the first equation.", workingLatex: "a(1) + b = 7 \\;\\Rightarrow\\; a + b = 7 \\qquad (1)", explanation: "Put \\(x = 1\\) into \\(f(x) = ax + b\\) and use \\(f(1) = 7\\)." }, { stepNumber: 3, description: "Part (a): substitute \\(x = -2\\) to form the second equation.", workingLatex: "a(-2) + b = -5 \\;\\Rightarrow\\; -2a + b = -5 \\qquad (2)", explanation: "Put \\(x = -2\\) into \\(f(x) = ax + b\\) and use \\(f(-2) = -5\\)." }, { stepNumber: 4, description: "Part (a): eliminate \\(b\\) by subtracting (2) from (1).", workingLatex: "(a + b) - (-2a + b) = 7 - (-5) \\;\\Rightarrow\\; 3a = 12", explanation: "The \\(b\\) terms cancel; note \\(7 - (-5) = 12\\), so the result is \\(3a = 12\\)." }, { stepNumber: 5, description: "Part (a): solve for \\(a\\).", workingLatex: "a = 4", explanation: "Divide both sides of \\(3a = 12\\) by 3." }, { stepNumber: 6, description: "Part (a): back-substitute to find \\(b\\).", workingLatex: "4 + b = 7 \\;\\Rightarrow\\; b = 3", explanation: "Substitute \\(a = 4\\) into equation (1). Hence \\(f(x) = 4x + 3\\)." }, { stepNumber: 7, description: "Part (b): set \\(y = f(x)\\) and rearrange.", workingLatex: "y = 4x + 3 \\;\\Rightarrow\\; x = \\tfrac{y - 3}{4}", explanation: "Subtract 3, then divide by 4 to make \\(x\\) the subject." }, { stepNumber: 8, description: "Part (b): swap variables to write the inverse.", workingLatex: "f^{-1}(x) = \\tfrac{x - 3}{4}", explanation: "Relabel \\(y \\to x\\) so the inverse is a function of its own input." }, { stepNumber: 9, description: "Part (b): check against the given data.", workingLatex: "f^{-1}(7) = \\tfrac{7 - 3}{4} = 1, \\qquad f^{-1}(-5) = \\tfrac{-5 - 3}{4} = -2", explanation: "Both given conditions are reproduced, confirming the values of \\(a\\) and \\(b\\)." }, { stepNumber: 10, description: "Part (c): substitute \\(f^{-1}(x)\\) into \\(f\\).", workingLatex: "f(f^{-1}(x)) = 4 \\cdot \\tfrac{x - 3}{4} + 3", explanation: "Apply the rule \\(f(\\text{input}) = 4(\\text{input}) + 3\\) to the expression for \\(f^{-1}(x)\\)." }, { stepNumber: 11, description: "Part (c): simplify to complete the verification.", workingLatex: "4 \\cdot \\tfrac{x - 3}{4} + 3 = (x - 3) + 3 = x", explanation: "The factor 4 cancels with the denominator; the \\(-3\\) and \\(+3\\) cancel, leaving \\(x\\) — verification complete." } ], finalAnswer: "(a) \\( a = 4, \\; b = 3 \\). (b) \\( f^{-1}(x) = \\tfrac{x - 3}{4} \\). (c) \\( f(f^{-1}(x)) = x \\). \\(\\blacksquare\\)" } },
  // ── Graph / reflection questions ────
  { id: "y2fg4-065", topicRef: "y2fg4", topicTitle: "Inverse Functions 65", difficulty: "Standard", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = 2x - 4 \\), \\( x \\in \\mathbb{R} \\). (a) Find \\( f^{-1}(x) \\). (b) On the same set of axes, sketch the graphs of \\( y = f(x) \\) and \\( y = f^{-1}(x) \\), marking the points where each graph crosses the coordinate axes. (c) State the geometrical transformation that maps the graph of \\( y = f(x) \\) onto the graph of \\( y = f^{-1}(x) \\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["inverse", "graphs", "reflection"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): set \\(y = f(x)\\) and rearrange.", workingLatex: "y = 2x - 4 \\;\\Rightarrow\\; y + 4 = 2x", explanation: "Add 4 to both sides, undoing the \\(-4\\) in the rule for \\(f\\)." }, { stepNumber: 2, description: "Part (a): solve and swap variables.", workingLatex: "x = \\tfrac{y + 4}{2} \\;\\Rightarrow\\; f^{-1}(x) = \\tfrac{x + 4}{2}", explanation: "Divide by 2, then relabel \\(y \\to x\\) to express the inverse as a function of its input." }, { stepNumber: 3, description: "Part (b): find the axis intercepts of \\(y = f(x)\\).", workingLatex: "f(0) = -4; \\qquad 2x - 4 = 0 \\Rightarrow x = 2", explanation: "Setting \\(x = 0\\) gives the \\(y\\)-intercept \\((0, -4)\\); setting \\(y = 0\\) gives the \\(x\\)-intercept \\((2, 0)\\)." }, { stepNumber: 4, description: "Part (b): find the axis intercepts of \\(y = f^{-1}(x)\\).", workingLatex: "f^{-1}(0) = 2; \\qquad \\tfrac{x + 4}{2} = 0 \\Rightarrow x = -4", explanation: "The inverse crosses the \\(y\\)-axis at \\((0, 2)\\) and the \\(x\\)-axis at \\((-4, 0)\\) — exactly the intercepts of \\(f\\) with their coordinates swapped." }, { stepNumber: 5, description: "Part (b): locate the intersection of the two graphs.", workingLatex: "2x - 4 = x \\;\\Rightarrow\\; x = 4 \\;\\Rightarrow\\; (4, 4)", explanation: "Any intersection lies on \\(y = x\\), so solve \\(f(x) = x\\); the graphs meet at \\((4, 4)\\) on the mirror line." }, { stepNumber: 6, description: "Part (b): describe the completed sketch.", workingLatex: "y = f(x): \\text{ line through } (2,0),(0,-4); \\quad y = f^{-1}(x): \\text{ line through } (-4,0),(0,2)", explanation: "Draw two straight lines: \\(y = f(x)\\) is the steeper one (gradient 2) and \\(y = f^{-1}(x)\\) the shallower (gradient \\(\\tfrac12\\)). Add the dashed line \\(y = x\\); each graph is the mirror image of the other in it, and they cross at \\((4, 4)\\)." }, { stepNumber: 7, description: "Part (c): state the transformation.", workingLatex: "y = f^{-1}(x) = \\text{reflection of } y = f(x) \\text{ in the line } y = x", explanation: "Reflecting in \\(y = x\\) swaps the coordinates of every point, which is precisely the inverse relationship between input and output." } ], finalAnswer: "(a) \\( f^{-1}(x) = \\tfrac{x + 4}{2} \\). (b) \\(y = f(x)\\) through \\((2,0)\\) and \\((0,-4)\\); \\(y = f^{-1}(x)\\) through \\((-4,0)\\) and \\((0,2)\\); the two lines are reflections of each other in \\(y = x\\), meeting at \\((4,4)\\). (c) Reflection in the line \\( y = x \\)." } },
  { id: "y2fg4-066", topicRef: "y2fg4", topicTitle: "Inverse Functions 66", difficulty: "Foundation", answerType: "expression", questionText: "The point \\( (3, 7) \\) lies on the graph of \\( y = f(x) \\), where \\( f \\) is a one-to-one function. (a) Write down the value of \\( f^{-1}(7) \\). (b) State the coordinates of the corresponding point on the graph of \\( y = f^{-1}(x) \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["inverse", "graphs"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): read off the input–output pair of \\(f\\).", workingLatex: "(3, 7) \\text{ on } y = f(x) \\;\\Rightarrow\\; f(3) = 7", explanation: "A point on the graph of \\(y = f(x)\\) records that the input 3 produces the output 7." }, { stepNumber: 2, description: "Part (a): apply the definition of the inverse.", workingLatex: "f(3) = 7 \\;\\iff\\; f^{-1}(7) = 3", explanation: "The inverse reverses the input–output pair, so \\(f^{-1}\\) sends 7 back to 3; hence \\(f^{-1}(7) = 3\\)." }, { stepNumber: 3, description: "Part (b): swap the coordinates.", workingLatex: "(3, 7) \\text{ on } y = f(x) \\;\\Rightarrow\\; (7, 3) \\text{ on } y = f^{-1}(x)", explanation: "The graph of \\(y = f^{-1}(x)\\) is the reflection of \\(y = f(x)\\) in \\(y = x\\), and reflecting in \\(y = x\\) swaps each point's coordinates." } ], finalAnswer: "(a) \\( f^{-1}(7) = 3 \\). (b) \\( (7, 3) \\)." } },
  { id: "y2fg4-067", topicRef: "y2fg4", topicTitle: "Inverse Functions 67", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = 2x - 3 \\), \\( x \\in \\mathbb{R} \\). (a) Find \\( f^{-1}(x) \\). (b) Sketch \\( y = f(x) \\) and \\( y = f^{-1}(x) \\) on the same axes, together with the line \\( y = x \\). (c) Explain how your diagram shows there is exactly one solution to \\( f(x) = f^{-1}(x) \\). (d) Solve \\( f(x) = f^{-1}(x) \\).", marks: 7, examStyle: true, yearCreated: 2026, tags: ["inverse", "graphs", "reflection"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): set \\(y = f(x)\\) and rearrange.", workingLatex: "y = 2x - 3 \\;\\Rightarrow\\; y + 3 = 2x", explanation: "Add 3 to both sides, undoing the \\(-3\\) in the rule for \\(f\\)." }, { stepNumber: 2, description: "Part (a): solve and swap variables.", workingLatex: "x = \\tfrac{y + 3}{2} \\;\\Rightarrow\\; f^{-1}(x) = \\tfrac{x + 3}{2}", explanation: "Divide by 2, then relabel \\(y \\to x\\) to express the inverse as a function of its input." }, { stepNumber: 3, description: "Part (b): describe the sketch.", workingLatex: "y = f(x): \\text{ line, gradient } 2, \\text{ intercept } (0,-3); \\quad y = f^{-1}(x): \\text{ line, gradient } \\tfrac12, \\text{ intercept } \\left(0,\\tfrac32\\right)", explanation: "Both graphs are straight lines: \\(y = f(x)\\) is steep, \\(y = f^{-1}(x)\\) is shallow, and each is the reflection of the other in the dashed line \\(y = x\\) drawn at 45°." }, { stepNumber: 4, description: "Part (c): use the reflection to locate intersections on \\(y = x\\).", workingLatex: "y = f^{-1}(x) \\text{ is the reflection of } y = f(x) \\text{ in } y = x", explanation: "Because each graph is the mirror image of the other in \\(y = x\\), any point where they cross must lie on the mirror line itself — intersections cannot occur off \\(y = x\\) for these increasing lines." }, { stepNumber: 5, description: "Part (c): count the crossings of \\(y = x\\).", workingLatex: "\\text{gradient of } f = 2 \\neq 1 \\;\\Rightarrow\\; y = f(x) \\text{ meets } y = x \\text{ once}", explanation: "An increasing straight line with gradient \\(\\neq 1\\) crosses \\(y = x\\) exactly once; the diagram therefore shows a single crossing on the mirror line, so \\(f(x) = f^{-1}(x)\\) has exactly one solution." }, { stepNumber: 6, description: "Part (d): reduce the equation to \\(f(x) = x\\).", workingLatex: "f(x) = f^{-1}(x) \\;\\Rightarrow\\; f(x) = x \\;\\Rightarrow\\; 2x - 3 = x", explanation: "Since the intersection lies on \\(y = x\\), the common value equals the input, so it suffices to solve \\(f(x) = x\\)." }, { stepNumber: 7, description: "Part (d): solve the linear equation.", workingLatex: "2x - 3 = x \\;\\Rightarrow\\; x = 3", explanation: "Subtract \\(x\\) from both sides and add 3 to obtain \\(x = 3\\)." }, { stepNumber: 8, description: "Part (d): verify the solution.", workingLatex: "f(3) = 2(3) - 3 = 3, \\qquad f^{-1}(3) = \\tfrac{3 + 3}{2} = 3", explanation: "Both functions equal 3 at \\(x = 3\\), so the unique intersection is \\((3, 3)\\), confirming it lies on \\(y = x\\)." } ], finalAnswer: "(a) \\( f^{-1}(x) = \\tfrac{x + 3}{2} \\). (b) Two straight lines reflected in \\(y = x\\). (c) Each line meets \\(y = x\\) exactly once, so the graphs intersect exactly once. (d) \\( x = 3 \\), at the point \\((3, 3)\\)." } },
  { id: "y2fg4-068", topicRef: "y2fg4", topicTitle: "Inverse Functions 68", difficulty: "Challenge", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = x^2 - 6x + 11 \\). (a) Express \\( f(x) \\) in the form \\( (x - p)^2 + q \\), and hence explain why \\( f \\) is not one-to-one on \\( \\mathbb{R} \\). (b) The domain of \\( f \\) is now restricted to \\( x \\geq 3 \\). Find \\( f^{-1}(x) \\) and state its domain. (c) Evaluate \\( f^{-1}(6) \\), and verify your answer by showing that \\( f \\) maps it to \\( 6 \\).", marks: 8, examStyle: true, yearCreated: 2026, tags: ["inverse", "unknown", "one-to-one", "domain"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): complete the square.", workingLatex: "x^2 - 6x + 11 = (x - 3)^2 - 9 + 11", explanation: "Half of the \\(x\\)-coefficient \\(-6\\) is \\(-3\\), and \\((x - 3)^2 = x^2 - 6x + 9\\); subtracting the extra 9 keeps the expression equal." }, { stepNumber: 2, description: "Part (a): simplify the constant.", workingLatex: "f(x) = (x - 3)^2 + 2", explanation: "Combine \\(-9 + 11 = 2\\), giving the completed-square form with \\(p = 3\\) and \\(q = 2\\)." }, { stepNumber: 3, description: "Part (a): explain why \\(f\\) is not one-to-one.", workingLatex: "f(3 + t) = t^2 + 2 = f(3 - t)", explanation: "The graph is a parabola with vertex \\((3, 2)\\), symmetric about \\(x = 3\\). Inputs equidistant from 3 give the same output, so a horizontal line cuts the curve twice — \\(f\\) is many-to-one on \\(\\mathbb{R}\\) and has no inverse there." }, { stepNumber: 4, description: "Part (b): set \\(y = f(x)\\) and isolate the square.", workingLatex: "y = (x - 3)^2 + 2 \\;\\Rightarrow\\; (x - 3)^2 = y - 2", explanation: "Subtract 2 from both sides of the completed-square form to leave the perfect square alone." }, { stepNumber: 5, description: "Part (b): take square roots.", workingLatex: "x - 3 = \\pm\\sqrt{y - 2}", explanation: "Square-rooting introduces two branches; the correct sign is fixed by the domain restriction in the next step." }, { stepNumber: 6, description: "Part (b): choose the correct root using \\(x \\geq 3\\).", workingLatex: "x \\geq 3 \\;\\Rightarrow\\; x - 3 \\geq 0 \\;\\Rightarrow\\; x = 3 + \\sqrt{y - 2}", explanation: "The restriction \\(x \\geq 3\\) makes \\(x - 3\\) non-negative, so only the positive root is valid; the negative branch is discarded." }, { stepNumber: 7, description: "Part (b): swap variables and state the domain.", workingLatex: "f^{-1}(x) = 3 + \\sqrt{x - 2}, \\qquad x \\geq 2", explanation: "Relabel \\(y \\to x\\). On \\(x \\geq 3\\) the range of \\(f\\) is \\(y \\geq 2\\) (minimum value 2 at the vertex), so the domain of \\(f^{-1}\\) is \\(x \\geq 2\\)." }, { stepNumber: 8, description: "Part (c): evaluate \\(f^{-1}(6)\\).", workingLatex: "f^{-1}(6) = 3 + \\sqrt{6 - 2} = 3 + \\sqrt{4} = 5", explanation: "Substitute \\(x = 6\\) into \\(f^{-1}(x) = 3 + \\sqrt{x - 2}\\); note \\(\\sqrt{4} = 2\\)." }, { stepNumber: 9, description: "Part (c): verify by applying \\(f\\).", workingLatex: "f(5) = 5^2 - 6(5) + 11 = 25 - 30 + 11 = 6", explanation: "Since \\(f(5) = 6\\), it follows that \\(f^{-1}(6) = 5\\), confirming the result. Also \\(5 \\geq 3\\), so the answer lies inside the restricted domain." } ], finalAnswer: "(a) \\( f(x) = (x - 3)^2 + 2 \\); the parabola is symmetric about \\(x = 3\\), so \\(f\\) is many-to-one on \\(\\mathbb{R}\\). (b) \\( f^{-1}(x) = 3 + \\sqrt{x - 2}, \\; x \\geq 2 \\). (c) \\( f^{-1}(6) = 5 \\), and \\( f(5) = 6 \\). \\(\\checkmark\\)" } },
  { id: "y2fg4-069", topicRef: "y2fg4", topicTitle: "Inverse Functions 69", difficulty: "Standard", answerType: "expression", questionText: "The functions \\( f \\) and \\( f^{-1} \\) are both increasing. (a) Explain why any point of intersection of the graphs of \\( y = f(x) \\) and \\( y = f^{-1}(x) \\) must lie on the line \\( y = x \\). (b) Hence state the equation that must be solved to find such intersections.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["inverse", "graphs", "reflection"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): recall the reflection relationship.", workingLatex: "(a, b) \\in y = f(x) \\;\\iff\\; (b, a) \\in y = f^{-1}(x)", explanation: "The graph of \\(y = f^{-1}(x)\\) is the reflection of \\(y = f(x)\\) in the line \\(y = x\\), and reflecting in \\(y = x\\) swaps the coordinates of every point." }, { stepNumber: 2, description: "Part (a): apply the condition at an intersection point.", workingLatex: "(a, b) \\text{ lies on both graphs} \\;\\Rightarrow\\; (a, b) = (b, a)", explanation: "If a point lies on both graphs it is its own reflection in \\(y = x\\); since reflection swaps coordinates, the point and its image must coincide." }, { stepNumber: 3, description: "Part (a): conclude the point is on \\(y = x\\).", workingLatex: "(a, b) = (b, a) \\;\\Rightarrow\\; a = b", explanation: "Equal coordinates means the intersection lies on \\(y = x\\). Because \\(f\\) is increasing this captures every intersection — none can occur off the mirror line." }, { stepNumber: 4, description: "Part (b): state the equation to solve.", workingLatex: "f(x) = x", explanation: "Since all intersections lie on \\(y = x\\), the output equals the input there, so solving \\(f(x) = x\\) gives the \\(x\\)-coordinates of every intersection." } ], finalAnswer: "(a) The graphs are reflections in \\(y = x\\); an intersection point equals its own reflection, so it lies on \\(y = x\\). (b) Solve \\( f(x) = x \\)." } },
  { id: "y2fg4-070", topicRef: "y2fg4", topicTitle: "Inverse Functions 70", difficulty: "Standard", answerType: "expression", questionText: "The function \\( f \\) is defined by \\( f(x) = 3x - 4 \\), \\( x \\in \\mathbb{R} \\). (a) Find \\( f^{-1}(x) \\). (b) Find the coordinates of the point where the graph of \\( y = f(x) \\) meets the graph of \\( y = f^{-1}(x) \\). (c) Verify your answer by checking it satisfies both \\( y = f(x) \\) and \\( y = f^{-1}(x) \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["inverse", "graphs"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): set \\(y = f(x)\\) and rearrange.", workingLatex: "y = 3x - 4 \\;\\Rightarrow\\; y + 4 = 3x", explanation: "Add 4 to both sides, undoing the \\(-4\\) in the rule for \\(f\\)." }, { stepNumber: 2, description: "Part (a): solve and swap variables.", workingLatex: "x = \\tfrac{y + 4}{3} \\;\\Rightarrow\\; f^{-1}(x) = \\tfrac{x + 4}{3}", explanation: "Divide by 3, then relabel \\(y \\to x\\) to express the inverse as a function of its input." }, { stepNumber: 3, description: "Part (b): reduce the intersection to \\(f(x) = x\\).", workingLatex: "f(x) = f^{-1}(x) \\;\\Rightarrow\\; f(x) = x \\;\\Rightarrow\\; 3x - 4 = x", explanation: "Since \\(y = f^{-1}(x)\\) is the reflection of \\(y = f(x)\\) in \\(y = x\\) and \\(f\\) is increasing, any intersection lies on \\(y = x\\); so solve \\(f(x) = x\\)." }, { stepNumber: 4, description: "Part (b): solve the linear equation.", workingLatex: "3x - 4 = x \\;\\Rightarrow\\; 2x = 4 \\;\\Rightarrow\\; x = 2", explanation: "Subtract \\(x\\) from both sides, then divide by 2." }, { stepNumber: 5, description: "Part (b): state the intersection point.", workingLatex: "(2, 2)", explanation: "On \\(y = x\\) the \\(y\\)-coordinate equals the \\(x\\)-coordinate, so the graphs meet at \\((2, 2)\\)." }, { stepNumber: 6, description: "Part (c): verify against both functions.", workingLatex: "f(2) = 3(2) - 4 = 2, \\qquad f^{-1}(2) = \\tfrac{2 + 4}{3} = 2", explanation: "Both \\(f\\) and \\(f^{-1}\\) give 2 at \\(x = 2\\), so \\((2, 2)\\) lies on both graphs — the answer is confirmed." } ], finalAnswer: "(a) \\( f^{-1}(x) = \\tfrac{x + 4}{3} \\). (b) The graphs meet at \\( (2, 2) \\). (c) \\( f(2) = 2 \\) and \\( f^{-1}(2) = 2 \\). \\(\\checkmark\\)" } },
  { id: "y2fg4-071", topicRef: "y2fg4", topicTitle: "Inverse Functions 71", difficulty: "Challenge", answerType: "expression", questionText: "The functions \\( f \\) and \\( g \\) are defined by \\( f(x) = 2x + 1 \\), \\( x \\in \\mathbb{R} \\) and \\( g(x) = x - 3 \\), \\( x \\in \\mathbb{R} \\). (a) Find \\( fg(x) \\) and hence find \\( (fg)^{-1}(x) \\). (b) Find \\( f^{-1}(x) \\) and \\( g^{-1}(x) \\), and hence find \\( g^{-1}f^{-1}(x) \\). (c) Verify that \\( (fg)^{-1}(x) = g^{-1}f^{-1}(x) \\), and explain why the order of \\(f^{-1}\\) and \\(g^{-1}\\) is reversed.", marks: 7, examStyle: true, yearCreated: 2026, tags: ["inverse", "composite"], workedSolution: { steps: [ { stepNumber: 1, description: "Part (a): form the composite \\(fg(x)\\).", workingLatex: "fg(x) = f(g(x)) = f(x - 3)", explanation: "In \\(fg\\) the function \\(g\\) is applied first, producing the input \\(x - 3\\) for \\(f\\)." }, { stepNumber: 2, description: "Part (a): apply \\(f\\) and simplify.", workingLatex: "f(x - 3) = 2(x - 3) + 1 = 2x - 5", explanation: "The rule for \\(f\\) doubles its input and adds 1; expand and collect constants to get \\(2x - 5\\)." }, { stepNumber: 3, description: "Part (a): set \\(y = fg(x)\\) and rearrange.", workingLatex: "y = 2x - 5 \\;\\Rightarrow\\; x = \\tfrac{y + 5}{2}", explanation: "Add 5, then divide by 2 to make \\(x\\) the subject." }, { stepNumber: 4, description: "Part (a): swap variables to write the inverse.", workingLatex: "(fg)^{-1}(x) = \\tfrac{x + 5}{2}", explanation: "Relabel \\(y \\to x\\) so the inverse of the composite is a function of its input." }, { stepNumber: 5, description: "Part (b): invert \\(f\\).", workingLatex: "y = 2x + 1 \\;\\Rightarrow\\; f^{-1}(x) = \\tfrac{x - 1}{2}", explanation: "Undo the rule for \\(f\\): subtract 1, then halve." }, { stepNumber: 6, description: "Part (b): invert \\(g\\).", workingLatex: "y = x - 3 \\;\\Rightarrow\\; g^{-1}(x) = x + 3", explanation: "Undo the rule for \\(g\\): adding 3 reverses subtracting 3." }, { stepNumber: 7, description: "Part (b): compose \\(g^{-1}f^{-1}\\).", workingLatex: "g^{-1}f^{-1}(x) = g^{-1}\\!\\left(\\tfrac{x - 1}{2}\\right) = \\tfrac{x - 1}{2} + 3", explanation: "Apply \\(f^{-1}\\) first to get \\(\\tfrac{x - 1}{2}\\), then apply \\(g^{-1}\\), which adds 3." }, { stepNumber: 8, description: "Part (c): simplify and compare.", workingLatex: "\\tfrac{x - 1}{2} + 3 = \\tfrac{x - 1 + 6}{2} = \\tfrac{x + 5}{2} = (fg)^{-1}(x)", explanation: "Write 3 as \\(\\tfrac{6}{2}\\) and combine over the common denominator 2; the result matches \\((fg)^{-1}(x)\\) from part (a)." }, { stepNumber: 9, description: "Part (c): explain the reversed order.", workingLatex: "(fg)^{-1} = g^{-1}f^{-1}, \\quad \\text{not } f^{-1}g^{-1}", explanation: "\\(fg\\) applies \\(g\\) then \\(f\\). To undo it the steps must be reversed: first undo the last operation \\(f\\) (with \\(f^{-1}\\)), then undo \\(g\\) (with \\(g^{-1}\\)) — like taking off shoes then socks in reverse of putting them on." } ], finalAnswer: "(a) \\( fg(x) = 2x - 5 \\), \\( (fg)^{-1}(x) = \\tfrac{x + 5}{2} \\). (b) \\( f^{-1}(x) = \\tfrac{x - 1}{2} \\), \\( g^{-1}(x) = x + 3 \\), \\( g^{-1}f^{-1}(x) = \\tfrac{x + 5}{2} \\). (c) Both equal \\(\\tfrac{x+5}{2}\\); the order reverses because undoing a composite means undoing the last-applied function first. \\(\\blacksquare\\)" } },
];
